insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (417, 67, 1, 15, 'سورة الملك ١ – ١٥', 'الملك: ليبلوكم أيكم أحسن عملاً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 417) = $j$[{"lbl": "الآيات ١ – ٥", "q": "تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١﴾ ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ ﴿٢﴾ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ ﴿٣﴾ ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ ﴿٤﴾ وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ ﴿٥﴾", "w": [["تبارك الذي بيده الملك", "تعاظم وكثر خير الذي بيده الملك أجمع، ملكاً وتصرّفاً."], ["وهو على كل شيء قدير", "على إيجاد كل ممكن وإعدامه قدير."], ["الذي خلق الموت والحياة", "أوجد الموت والحياة، فكل حيّ هو بالحياة التي خلق الله، وكل ميت هو بالموت الذي خلق الله."], ["ليبلوكم أيكم أحسن عملاً", "أحياكم ليختبركم أيكم يكون أحسن عملاً، ثم يميتكم ثم يحييكم ليجزيكم."], ["وهو العزيز الغفور", "الغالب على ما يريده، العظيم المغفرة."], ["طباقاً", "طبقة فوق طبقة، وهي السبع الطباق."], ["ما ترى في خلق الرحمن من تفاوت", "من تباين وعدم تناسب."], ["هل ترى من فطور", "من شقوق أو تصدّع."], ["كرّتين", "مرتين، مرة بعد مرة."], ["خاسئاً وهو حسير", "ذليلاً مبعداً، كالّاً تعباً منقطعاً عن الرؤية، إذ لا يرى خللاً."], ["بمصابيح", "بنجوم مضيئة كالمصابيح."], ["رجوماً للشياطين", "مراجم يُرمى بها."], ["وأعتدنا لهم عذاب السعير", "وهيّأنا لهم عذاب النار المسعّرة الشديدة الاتّقاد."]], "m": "يمجّد الرب تعالى نفسه ويثني عليها بما هو أهله من الملك والسلطان والقدرة والعلم والحكمة: تعاظم وكثر خير الذي بيده الملك الحقيقي، يحكم ويتصرّف ويدبّر بعلمه وحكمته لا شريك له، وهو على كل شيء قدير، فما أراد ممكناً إلا كان، ولا أراد انعدام ممكن إلا انعدم. الذي خلق الموت والحياة لحكمة عالية، لا عبثاً كما يتصوّر الكافرون والملاحدة، بل ليبلوكم أيكم أحسن عملاً؛ خلق الحياة بكل ما فيها ليُذكر ويُشكر، فمن ذكر وشكر وأحسن ذلك أعدّ له جنات ينقله إليها بعد نهاية الحياة، ومن لم يذكر ولم يشكر، أو ذكر وشكر ولم يحسن ذلك بأن لم يخلص فيه لله ولم يؤدّه كما شرع، أعدّ له ناراً، إذ هذه الحياة للعمل، وحياة الآخرة للجزاء. وهو العزيز الغالب الذي لا يُحال بينه وبين ما يريد، الغفور الذي يغفر الذنوب للتائب ولو كانت مثل الجبال. الذي خلق سبع سماوات طباقاً، سماء فوق سماء من غير مماسّة، ما ترى في خلق الرحمن من اختلاف أو تضاد، والسماء فوقك لا تجد إلا الاتّساق والانتظام، فارجع البصر هل ترى من فطور، ثم ارجع البصر مرة بعد مرة، فإنك لا تجد تفاوتاً، بل يرجع إليك بصرك ذليلاً مبعداً عما أراد، كليلاً تعباً. ولقد زيّنا السماء الدنيا القريبة من الأرض بمصابيح هي النجوم والكواكب، وجعلناها رجوماً ترجم بها الملائكة شياطين الجن الذين يريدون استراق السمع حتى لا يفتنوا الناس عن دين الله، وأعتدنا للشياطين عذاب السعير يوم القيامة كسائر الكافرين من الإنس والجن.", "h": ["تقرير ربوبية الله تعالى بعرض دلائل القدرة والعلم والحكمة والخير والبركة، وهي موجبة لألوهيته، أي عبادته دون من سواه عز وجل.", "بيان الحكمة من خلق الموت والحياة.", "بيان الحكمة من خلق النجوم، وهي في قول قتادة رحمه الله: أن الله جل ثناؤه إنما خلق هذه النجوم لثلاث خصال: زينة للسماء الدنيا، ورجوماً للشياطين، وعلامات يُهتدى بها."], "k": "«ليبلوكم أيكم أحسن عملاً»… لم يقل أكثر عملاً بل أحسن؛ فهل أحسّن عملي أم أكثّره فقط؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٦﴾ إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقٗا وَهِيَ تَفُورُ ﴿٧﴾ تَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ ﴿٨﴾ قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرٞ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ كَبِيرٖ ﴿٩﴾ وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ ﴿١٠﴾ فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ ﴿١١﴾", "w": [["وللذين كفروا بربهم", "لم يؤمنوا به فلم يعبدوه."], ["إذا أُلقوا فيها", "في جهنم، ألقتهم الملائكة فيها يوم القيامة."], ["سمعوا لها شهيقاً", "صوتاً منكراً مزعجاً كصوت الحمار."], ["وهي تفور تكاد تميّز من الغيظ", "تغلي تكاد تتقطّع من الغيظ غضباً على الكفار."], ["سألهم خزنتها", "سؤال توبيخ وتقريع."], ["ألم يأتكم نذير", "رسول ينذركم عذاب الله يوم القيامة؟"], ["وقلنا ما نزّل الله من شيء", "كذّبنا الرسل وقلنا لهم: ما نزّل الله مما تقولون شيئاً."], ["إن أنتم إلا في ضلال كبير", "ما أنتم أيها الرسل إلا في خطأ عقلي وتصوّر باطل."], ["لو كنا نسمع أو نعقل", "وبّخوا أنفسهم: لو كنا في الدنيا نسمع أو نعقل لآمنّا، وما كنا اليوم في أصحاب السعير."], ["فسحقاً لأصحاب السعير", "بُعداً بُعداً من رحمة الله لأصحاب سعير جهنم."]], "m": "لما ذكر تعالى أنه أعدّ للشياطين مسترقي السمع عذاب السعير، عطف عليه: وللذين كفروا بربهم فجحدوا ألوهيته ولقاءه من الإنس والجن عذاب جهنم، وبئس المصير، شرابها الحميم وطعامها الضريع والزقوم. إذا أُلقي الكافرون فيها سمعوا لها صوتاً منكراً مزعجاً، وهي تغلي تقرب أن تتقطّع من شدة الغضب، وغضبها من غضب الرب مالكها، وكل مؤمن بالله عارف به يغضب لما يغضب له ربه ويرضى لما يرضى به. كلما أُلقي فيها جماعة سألهم الملائكة الموكّلون بها سؤال توبيخ: ألم يأتكم رسول في الدنيا يدعوكم إلى الإيمان والطاعة؟ فيجيبون: بلى قد جاءنا نذير، ولكن كذّبنا الرسل وقلنا لهم: ما نزّل الله من شيء، ما أنتم إلا في ضلال عقلي وخطأ تصوري كبير. ثم رجعوا إلى أنفسهم يوبّخونها: لو كنا نسمع أو نعقل ما كنا في أصحاب السعير، فاعترفوا بذنبهم، فبعداً من رحمة الله لأصحاب السعير.", "h": ["تقرير عقيدة البعث والجزاء ببيان ما يجري فيها من عذاب وعقاب.", "بيان أن تكذيب الرسل كفر موجب للعذاب، وتكذيب العلماء كتكذيب الرسل بعدهم في وجوب العذاب المترتّب على ترك طاعة الله ورسوله.", "بيان أن ما يقوله أهل النار في اعترافهم هو ما يقوله الملاحدة اليوم في ردّهم على العلماء بأن التديّن تأخّر عقلي ونظر رجعي.", "تقرير أن الكافر اليوم لا يسمع ولا يعقل، أي سماعاً ينفعه وعقلاً يحجزه عن المهالك، باعتراف أهل النار إذ قالوا: «لو كنا نسمع أو نعقل ما كنا في أصحاب السعير»."], "k": "«لو كنا نسمع أو نعقل»… أسمع المواعظ كثيراً؛ فهل أسمعها سماع من يعقل؟"}, {"lbl": "الآيات ١٢ – ١٥", "q": "إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ﴿١٢﴾ وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١٣﴾ أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ﴿١٤﴾ هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ ﴿١٥﴾", "w": [["إن الذين يخشون ربهم بالغيب", "يخافونه وهم غائبون عن أعين الناس فلا يعصونه."], ["لهم مغفرة وأجر كبير", "مغفرة لذنوبهم، وأجر كبير هو الجنة."], ["ألا يعلم من خلق", "كيف لا يعلم سرّكم كما يعلم جهركم وهو الخالق لكم؟"], ["وهو اللطيف الخبير", "اللطيف بعباده، الخبير بهم وبأعمالهم."], ["ذلولاً", "سهلة للمشي والسير عليها."], ["فامشوا في مناكبها", "في جوانبها ونواحيها."], ["وإليه النشور", "إليه وحده نشركم، أي إحياؤكم من قبوركم للحساب والجزاء."]], "m": "لما ذكر تعالى جزاء الكافرين رغّب في الإيمان والطاعة للنجاة من السعير، فكان الأسلوب أسلوب الترهيب والترغيب الذي عُرف به القرآن: إن الذين يخافون ربهم وهم لا يرونه، وكذا وهم في غيبة عن الناس، فيطيعونه ولا يعصونه، لهم مغفرة لما فرط من ذنوبهم وأجر كبير هو الجنة. ولما قال بعض المشركين بمكة: لا تجهروا بالقول فيسمعكم إله محمد، قال تعالى رداً عليهم: وأسرّوا قولكم أو اجهروا به، فإنه عليم بما هو مكنون في الصدور من حديث النفس وخواطرها، كيف لا يعلم من خلقهم وهو اللطيف بهم الخبير بأحوالهم؟ هو الذي جعل لكم الأرض سهلة، فامشوا في جوانبها شرقاً وغرباً، وكلوا من رزقه الذي يخلقه لكم، وإليه وحده إحياؤكم وإخراجكم من قبوركم ليحاسبكم ويجزيكم: على إيمانكم وطاعتكم بالجنة، وعلى كفر من كفر وعصى بالنار.", "h": ["فضيلة الإيمان بالغيب، ومراقبة الله تعالى في السر والعلن.", "مشروعية السير في الأرض لطلب الرزق من التجارة والفلاحة وغيرهما.", "تقرير عقيدة البعث والجزاء."], "k": "«يخشون ربهم بالغيب»… حين يغيب عني الناس، هل يبقى في قلبي من يراني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 417;
insert into public.tdb_cards(topic, i, body) select 417, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "تَبَٰرَكَ ٱلَّذِي بِيَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿١﴾ ٱلَّذِي خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَيَوٰةَ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلٗاۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡغَفُورُ ﴿٢﴾ ٱلَّذِي خَلَقَ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗاۖ مَّا تَرَىٰ فِي خَلۡقِ ٱلرَّحۡمَٰنِ مِن تَفَٰوُتٖۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورٖ ﴿٣﴾ ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَيۡنِ يَنقَلِبۡ إِلَيۡكَ ٱلۡبَصَرُ خَاسِئٗا وَهُوَ حَسِيرٞ ﴿٤﴾ وَلَقَدۡ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَجَعَلۡنَٰهَا رُجُومٗا لِّلشَّيَٰطِينِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِيرِ ﴿٥﴾", "w": [["تبارك الذي بيده الملك", "تعاظم وكثر خير الذي بيده الملك أجمع، ملكاً وتصرّفاً."], ["وهو على كل شيء قدير", "على إيجاد كل ممكن وإعدامه قدير."], ["الذي خلق الموت والحياة", "أوجد الموت والحياة، فكل حيّ هو بالحياة التي خلق الله، وكل ميت هو بالموت الذي خلق الله."], ["ليبلوكم أيكم أحسن عملاً", "أحياكم ليختبركم أيكم يكون أحسن عملاً، ثم يميتكم ثم يحييكم ليجزيكم."], ["وهو العزيز الغفور", "الغالب على ما يريده، العظيم المغفرة."], ["طباقاً", "طبقة فوق طبقة، وهي السبع الطباق."], ["ما ترى في خلق الرحمن من تفاوت", "من تباين وعدم تناسب."], ["هل ترى من فطور", "من شقوق أو تصدّع."], ["كرّتين", "مرتين، مرة بعد مرة."], ["خاسئاً وهو حسير", "ذليلاً مبعداً، كالّاً تعباً منقطعاً عن الرؤية، إذ لا يرى خللاً."], ["بمصابيح", "بنجوم مضيئة كالمصابيح."], ["رجوماً للشياطين", "مراجم يُرمى بها."], ["وأعتدنا لهم عذاب السعير", "وهيّأنا لهم عذاب النار المسعّرة الشديدة الاتّقاد."]], "m": "يمجّد الرب تعالى نفسه ويثني عليها بما هو أهله من الملك والسلطان والقدرة والعلم والحكمة: تعاظم وكثر خير الذي بيده الملك الحقيقي، يحكم ويتصرّف ويدبّر بعلمه وحكمته لا شريك له، وهو على كل شيء قدير، فما أراد ممكناً إلا كان، ولا أراد انعدام ممكن إلا انعدم. الذي خلق الموت والحياة لحكمة عالية، لا عبثاً كما يتصوّر الكافرون والملاحدة، بل ليبلوكم أيكم أحسن عملاً؛ خلق الحياة بكل ما فيها ليُذكر ويُشكر، فمن ذكر وشكر وأحسن ذلك أعدّ له جنات ينقله إليها بعد نهاية الحياة، ومن لم يذكر ولم يشكر، أو ذكر وشكر ولم يحسن ذلك بأن لم يخلص فيه لله ولم يؤدّه كما شرع، أعدّ له ناراً، إذ هذه الحياة للعمل، وحياة الآخرة للجزاء. وهو العزيز الغالب الذي لا يُحال بينه وبين ما يريد، الغفور الذي يغفر الذنوب للتائب ولو كانت مثل الجبال. الذي خلق سبع سماوات طباقاً، سماء فوق سماء من غير مماسّة، ما ترى في خلق الرحمن من اختلاف أو تضاد، والسماء فوقك لا تجد إلا الاتّساق والانتظام، فارجع البصر هل ترى من فطور، ثم ارجع البصر مرة بعد مرة، فإنك لا تجد تفاوتاً، بل يرجع إليك بصرك ذليلاً مبعداً عما أراد، كليلاً تعباً. ولقد زيّنا السماء الدنيا القريبة من الأرض بمصابيح هي النجوم والكواكب، وجعلناها رجوماً ترجم بها الملائكة شياطين الجن الذين يريدون استراق السمع حتى لا يفتنوا الناس عن دين الله، وأعتدنا للشياطين عذاب السعير يوم القيامة كسائر الكافرين من الإنس والجن.", "h": ["تقرير ربوبية الله تعالى بعرض دلائل القدرة والعلم والحكمة والخير والبركة، وهي موجبة لألوهيته، أي عبادته دون من سواه عز وجل.", "بيان الحكمة من خلق الموت والحياة.", "بيان الحكمة من خلق النجوم، وهي في قول قتادة رحمه الله: أن الله جل ثناؤه إنما خلق هذه النجوم لثلاث خصال: زينة للسماء الدنيا، ورجوماً للشياطين، وعلامات يُهتدى بها."], "k": "«ليبلوكم أيكم أحسن عملاً»… لم يقل أكثر عملاً بل أحسن؛ فهل أحسّن عملي أم أكثّره فقط؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَلِلَّذِينَ كَفَرُواْ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِيرُ ﴿٦﴾ إِذَآ أُلۡقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقٗا وَهِيَ تَفُورُ ﴿٧﴾ تَكَادُ تَمَيَّزُ مِنَ ٱلۡغَيۡظِۖ كُلَّمَآ أُلۡقِيَ فِيهَا فَوۡجٞ سَأَلَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ نَذِيرٞ ﴿٨﴾ قَالُواْ بَلَىٰ قَدۡ جَآءَنَا نَذِيرٞ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَيۡءٍ إِنۡ أَنتُمۡ إِلَّا فِي ضَلَٰلٖ كَبِيرٖ ﴿٩﴾ وَقَالُواْ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِيٓ أَصۡحَٰبِ ٱلسَّعِيرِ ﴿١٠﴾ فَٱعۡتَرَفُواْ بِذَنۢبِهِمۡ فَسُحۡقٗا لِّأَصۡحَٰبِ ٱلسَّعِيرِ ﴿١١﴾", "w": [["وللذين كفروا بربهم", "لم يؤمنوا به فلم يعبدوه."], ["إذا أُلقوا فيها", "في جهنم، ألقتهم الملائكة فيها يوم القيامة."], ["سمعوا لها شهيقاً", "صوتاً منكراً مزعجاً كصوت الحمار."], ["وهي تفور تكاد تميّز من الغيظ", "تغلي تكاد تتقطّع من الغيظ غضباً على الكفار."], ["سألهم خزنتها", "سؤال توبيخ وتقريع."], ["ألم يأتكم نذير", "رسول ينذركم عذاب الله يوم القيامة؟"], ["وقلنا ما نزّل الله من شيء", "كذّبنا الرسل وقلنا لهم: ما نزّل الله مما تقولون شيئاً."], ["إن أنتم إلا في ضلال كبير", "ما أنتم أيها الرسل إلا في خطأ عقلي وتصوّر باطل."], ["لو كنا نسمع أو نعقل", "وبّخوا أنفسهم: لو كنا في الدنيا نسمع أو نعقل لآمنّا، وما كنا اليوم في أصحاب السعير."], ["فسحقاً لأصحاب السعير", "بُعداً بُعداً من رحمة الله لأصحاب سعير جهنم."]], "m": "لما ذكر تعالى أنه أعدّ للشياطين مسترقي السمع عذاب السعير، عطف عليه: وللذين كفروا بربهم فجحدوا ألوهيته ولقاءه من الإنس والجن عذاب جهنم، وبئس المصير، شرابها الحميم وطعامها الضريع والزقوم. إذا أُلقي الكافرون فيها سمعوا لها صوتاً منكراً مزعجاً، وهي تغلي تقرب أن تتقطّع من شدة الغضب، وغضبها من غضب الرب مالكها، وكل مؤمن بالله عارف به يغضب لما يغضب له ربه ويرضى لما يرضى به. كلما أُلقي فيها جماعة سألهم الملائكة الموكّلون بها سؤال توبيخ: ألم يأتكم رسول في الدنيا يدعوكم إلى الإيمان والطاعة؟ فيجيبون: بلى قد جاءنا نذير، ولكن كذّبنا الرسل وقلنا لهم: ما نزّل الله من شيء، ما أنتم إلا في ضلال عقلي وخطأ تصوري كبير. ثم رجعوا إلى أنفسهم يوبّخونها: لو كنا نسمع أو نعقل ما كنا في أصحاب السعير، فاعترفوا بذنبهم، فبعداً من رحمة الله لأصحاب السعير.", "h": ["تقرير عقيدة البعث والجزاء ببيان ما يجري فيها من عذاب وعقاب.", "بيان أن تكذيب الرسل كفر موجب للعذاب، وتكذيب العلماء كتكذيب الرسل بعدهم في وجوب العذاب المترتّب على ترك طاعة الله ورسوله.", "بيان أن ما يقوله أهل النار في اعترافهم هو ما يقوله الملاحدة اليوم في ردّهم على العلماء بأن التديّن تأخّر عقلي ونظر رجعي.", "تقرير أن الكافر اليوم لا يسمع ولا يعقل، أي سماعاً ينفعه وعقلاً يحجزه عن المهالك، باعتراف أهل النار إذ قالوا: «لو كنا نسمع أو نعقل ما كنا في أصحاب السعير»."], "k": "«لو كنا نسمع أو نعقل»… أسمع المواعظ كثيراً؛ فهل أسمعها سماع من يعقل؟"}, {"lbl": "الآيات ١٢ – ١٥", "q": "إِنَّ ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ لَهُم مَّغۡفِرَةٞ وَأَجۡرٞ كَبِيرٞ ﴿١٢﴾ وَأَسِرُّواْ قَوۡلَكُمۡ أَوِ ٱجۡهَرُواْ بِهِۦٓۖ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ ﴿١٣﴾ أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ ﴿١٤﴾ هُوَ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولٗا فَٱمۡشُواْ فِي مَنَاكِبِهَا وَكُلُواْ مِن رِّزۡقِهِۦۖ وَإِلَيۡهِ ٱلنُّشُورُ ﴿١٥﴾", "w": [["إن الذين يخشون ربهم بالغيب", "يخافونه وهم غائبون عن أعين الناس فلا يعصونه."], ["لهم مغفرة وأجر كبير", "مغفرة لذنوبهم، وأجر كبير هو الجنة."], ["ألا يعلم من خلق", "كيف لا يعلم سرّكم كما يعلم جهركم وهو الخالق لكم؟"], ["وهو اللطيف الخبير", "اللطيف بعباده، الخبير بهم وبأعمالهم."], ["ذلولاً", "سهلة للمشي والسير عليها."], ["فامشوا في مناكبها", "في جوانبها ونواحيها."], ["وإليه النشور", "إليه وحده نشركم، أي إحياؤكم من قبوركم للحساب والجزاء."]], "m": "لما ذكر تعالى جزاء الكافرين رغّب في الإيمان والطاعة للنجاة من السعير، فكان الأسلوب أسلوب الترهيب والترغيب الذي عُرف به القرآن: إن الذين يخافون ربهم وهم لا يرونه، وكذا وهم في غيبة عن الناس، فيطيعونه ولا يعصونه، لهم مغفرة لما فرط من ذنوبهم وأجر كبير هو الجنة. ولما قال بعض المشركين بمكة: لا تجهروا بالقول فيسمعكم إله محمد، قال تعالى رداً عليهم: وأسرّوا قولكم أو اجهروا به، فإنه عليم بما هو مكنون في الصدور من حديث النفس وخواطرها، كيف لا يعلم من خلقهم وهو اللطيف بهم الخبير بأحوالهم؟ هو الذي جعل لكم الأرض سهلة، فامشوا في جوانبها شرقاً وغرباً، وكلوا من رزقه الذي يخلقه لكم، وإليه وحده إحياؤكم وإخراجكم من قبوركم ليحاسبكم ويجزيكم: على إيمانكم وطاعتكم بالجنة، وعلى كفر من كفر وعصى بالنار.", "h": ["فضيلة الإيمان بالغيب، ومراقبة الله تعالى في السر والعلن.", "مشروعية السير في الأرض لطلب الرزق من التجارة والفلاحة وغيرهما.", "تقرير عقيدة البعث والجزاء."], "k": "«يخشون ربهم بالغيب»… حين يغيب عني الناس، هل يبقى في قلبي من يراني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (418, 67, 16, 30, 'سورة الملك ١٦ – ٣٠', 'الملك: قل هو الرحمن آمنّا به', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 418) = $j$[{"lbl": "الآيات ١٦ – ١٩", "q": "ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ ﴿١٦﴾ أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ فَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ ﴿١٧﴾ وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ ﴿١٨﴾ أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَـٰٓفَّـٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ ﴿١٩﴾", "w": [["أن يخسف بكم الأرض", "يجعلها بحيث تغورون فيها وتصبحون في جوفها."], ["فإذا هي تمور", "تتحرّك وتضطرب حتى يتم الخسف بكم."], ["أن يرسل عليكم حاصباً", "ريحاً عاصفاً ترميكم بالحصباء فتهلكون."], ["فستعلمون كيف نذير", "كيف كان عاقبة إنذاري لكم بالعذاب على ألسنة رسلي."], ["فكيف كان نكير", "إنكاري عليهم الكفر والتكذيب، والجواب: كان إنكاراً حقاً واقعاً."], ["صافّات", "باسطات أجنحتها."], ["ما يمسكهن إلا الرحمن", "حتى لا يسقطن على الأرض حال البسط للأجنحة والقبض لها."]], "m": "يقول تعالى واعظاً عباده ليؤمنوا به ويعبدوه وحده: أأمنتم من في السماء، الذي هو العلو المطلق، وهو الله عز وجل في عليائه فوق عرشه بائن من خلقه، أن يخسف بكم الأرض فتهلكوا في جوفها، فإذا هي تتحرّك وتضطرب حتى تغوروا في بطنها؟ والجواب: لم يأمنوا ذلك، فكيف إذاً يصرّون على الشرك والتكذيب؟ أم أمنتم من في السماء أن يرسل عليكم ريحاً تحمل الحصباء والحجارة فتهلككم؟ فستعلمون كيف إنذاري لكم، إنه حق واقع مقتضاه. ولقد كذّب الذين من قبلهم كعاد وثمود رسلي، فأهلكناهم، فكيف كان إنكاري لهم؟ كان حقاً واقع المقتضى. أوَلم يروا إلى الطير فوقهم باسطات أجنحتهن ويقبضنها، ما يمسكهن في حالة البسط أو القبض إلا الرحمن، الذي أنكره المشركون وقالوا: وما الرحمن؟ وهم يعيشون في رحمته التي وسعت كل شيء، وهي متجلّية حتى في الطير تحفظه من السقوط، إنه بكل شيء بصير، سواء عنده السابح في الماء والسارح في الغبراء والطائر في السماء.", "h": ["تحذير المعرضين عن الله وإنذارهم بسوء العواقب إن استمرّوا على إعراضهم، فإن الله قادر على أن يخسف بهم الأرض أو يرسل عليهم حاصباً من السماء، وليس هناك من يؤمّنهم ويجيرهم إلا إيمانهم وإسلامهم لله عز وجل.", "في الهالكين الأوّلين عبر وعظات لمن له قلب حي وعقل يعقل به.", "من آيات الله في الآفاق الدالة على قدرته وعلمه ورحمته الموجبة لعبادته وحده طيران الطير في السماء وهو يبسط جناحيه ويقبضهما ولا يسقط، إذ الرحمن عز وجل يمسكه فلا يسقط."], "k": "«ما يمسكهن إلا الرحمن»… الذي يمسك الطير في الهواء يمسكني أنا أيضاً؛ فلماذا أقلق؟"}, {"lbl": "الآيات ٢٠ – ٢٧", "q": "أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ ﴿٢٠﴾ أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ وَنُفُورٍ ﴿٢١﴾ أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٢٢﴾ قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٢٣﴾ قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ ﴿٢٤﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٥﴾ قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ ﴿٢٦﴾ فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَدَّعُونَ ﴿٢٧﴾", "w": [["جند لكم", "أعوان لكم."], ["من دون الرحمن", "غيره تعالى، يدفع عنكم عذابه."], ["إن الكافرون إلا في غرور", "ما الكافرون إلا في غرور، غرّهم الشيطان بأن لا عذاب ينزل بهم."], ["إن أمسك رزقه", "إن أمسك الرحمن رزقه، فلا أحد غير الله يرسله."], ["بل لجّوا في عتوّ ونفور", "لم يتأثّروا بذلك التبكيت، بل تمادوا في التكبّر والتباعد عن الحق."], ["أفمن يمشي مكبّاً على وجهه", "واقعاً على وجهه."], ["أمّن يمشي سويّاً", "مستقيماً."], ["والأفئدة", "القلوب."], ["قليلاً ما تشكرون", "شكركم قليل."], ["ذرأكم في الأرض", "خلقكم في الأرض، وإليه تُحشرون لا إلى سواه."], ["متى هذا الوعد", "الذي تعدوننا به، وهو يوم القيامة؟"], ["قل إنما العلم عند الله", "علم مجيئه عند الله لا غير."], ["فلما رأوه زلفة", "لما رأوا العذاب قريباً منهم في عرصات القيامة."], ["سيئت وجوه الذين كفروا", "تغيّرت مسودّة."], ["هذا الذي كنتم به تدّعون", "هذا العذاب الذي كنتم تكذّبون بإنذاره وتطالبون به تحدّياً."]], "m": "ما زال السياق في مطلب هداية كفار قريش: من هذا الذي هو جند لكم ينصركم من دون الرحمن إن أراد بكم سوءاً فيدفعه عنكم؟ ما الكافرون إلا في غرور أوقعهم الشيطان فيه، زيّن لهم الشرك ومنّاهم أنه لا حساب ولا عقاب، وأن آلهتهم تشفع لهم. من هذا الذي يطعمكم ويسقيكم إن أمسك الله ربكم رزقه عنكم؟ فلو قطع عنكم المطر ما أتاكم به أحد غير الله. بل تمادوا في الكبر والتباعد عن الحق. ثم ضرب مثلاً للمشرك والموحّد: أفمن يمشي واقعاً على وجهه، وهو المشرك الذي سيُكبّ على وجهه في جهنم، أهدى أمّن يمشي مستقيماً على طريق مستقيم، وهو الموحّد؟ والجواب قطعاً: الموحّد مهتدٍ والمشرك ضال. قل هو الذي خلقكم وجعل لكم السمع والأبصار والقلوب، وأنتم لا تنكرون ذلك، فما لكم لا تشكرون المنعم بالإيمان به وطاعته؟ إنكم ما تشكرون إلا قليلاً. قل: الله هو الذي خلقكم في الأرض، لا أصنامكم التي لا تخلق ذباباً، وإليه وحده تُحشرون يوم القيامة. ويقول الكافرون: متى هذا الوعد إن كنتم صادقين؟ قل: علم مجيء يوم القيامة عند الله، وليس هو من شأني، وإنما أنا نذير مبين. فلما رأوا عذاب يوم القيامة قريباً منهم أساء الله وجوههم فتغيّرت بالاسوداد والكآبة، وقيل لهم: هذا العذاب الذي كنتم تطالبون به متحدّين رسولنا والمؤمنين.", "h": ["الكافر يعيش في غرور كامل، ولذا يرفض دعوة الحق.", "تقرير حقيقة ثابتة، وهي انحراف الكافر وضلاله، واستقامة المؤمن وهدايته.", "وجوب الشكر لله تعالى على نعمة السمع والبصر والقلب، وذلك بالإيمان والطاعة.", "تقرير عقيدة البعث والجزاء."], "k": "«وجعل لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… فيمَ استعملت سمعي وبصري اليوم؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ ﴿٢٨﴾ قُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٢٩﴾ قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرٗا فَمَن يَأۡتِيكُم بِمَآءٖ مَّعِينِۭ ﴿٣٠﴾", "w": [["قل أرأيتم", "أخبروني."], ["إن أهلكني الله ومن معي", "من المؤمنين."], ["أو رحمنا", "فلم يهلكنا."], ["فمن يجير الكافرين", "فمن يحفظ ويقي الكافرين العذاب؟"], ["قل هو الرحمن", "قل: هو الرحمن الذي أدعوكم إلى عبادته."], ["إن أصبح ماؤكم غوراً", "غائراً لا تناله الدلاء ولا تراه العيون."], ["فمن يأتيكم بماء معين", "بماء جارٍ ظاهر تراه العيون."]], "m": "ما زال السياق في مطلب هداية كفار قريش: قل يا رسولنا لهؤلاء المشركين الذين تمنّوا موتك وقالوا: نتربّص به ريب المنون: أخبروني إن أهلكني الله ومن معي من المؤمنين، أو رحمنا فلم يهلكنا، فمن يجير الكافرين من عذاب أليم؟ والجواب: لا أحد، إذاً فماذا تنتفعون بهلاكنا؟ قل هو الرحمن الذي يدعوكم إلى عبادته وحده، آمنّا به وعليه توكّلنا، أي اعتمدنا عليه وفوّضنا أمرنا إليه، فستعلمون في يوم ما من هو في ضلال مبين. قل أخبروني إن أصبح ماؤكم الذي تشربون منه، بئر زمزم وغيرها، غائراً لا تناله الدلاء، فمن يأتيكم بماء معين غير الله تعالى؟ والجواب: لا أحد، إذاً فلمَ لا تؤمنون به وتوحّدونه في عبادته؟", "h": ["بيان ما كان عليه المشركون من عداوة لرسول الله ﷺ حتى تمنّوا موته.", "وجوب التوكّل على الله عز وجل بعد الإيمان.", "مشروعية الحِجاج لإحقاق الحق وإبطال الباطل."], "k": "«فمن يأتيكم بماء معين»… كوب الماء الذي أشربه من رحمته؛ فهل أذكره عند كل شربة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 418;
insert into public.tdb_cards(topic, i, body) select 418, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦ – ١٩", "q": "ءَأَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِيَ تَمُورُ ﴿١٦﴾ أَمۡ أَمِنتُم مَّن فِي ٱلسَّمَآءِ أَن يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗاۖ فَسَتَعۡلَمُونَ كَيۡفَ نَذِيرِ ﴿١٧﴾ وَلَقَدۡ كَذَّبَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَكَيۡفَ كَانَ نَكِيرِ ﴿١٨﴾ أَوَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ فَوۡقَهُمۡ صَـٰٓفَّـٰتٖ وَيَقۡبِضۡنَۚ مَا يُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَٰنُۚ إِنَّهُۥ بِكُلِّ شَيۡءِۭ بَصِيرٌ ﴿١٩﴾", "w": [["أن يخسف بكم الأرض", "يجعلها بحيث تغورون فيها وتصبحون في جوفها."], ["فإذا هي تمور", "تتحرّك وتضطرب حتى يتم الخسف بكم."], ["أن يرسل عليكم حاصباً", "ريحاً عاصفاً ترميكم بالحصباء فتهلكون."], ["فستعلمون كيف نذير", "كيف كان عاقبة إنذاري لكم بالعذاب على ألسنة رسلي."], ["فكيف كان نكير", "إنكاري عليهم الكفر والتكذيب، والجواب: كان إنكاراً حقاً واقعاً."], ["صافّات", "باسطات أجنحتها."], ["ما يمسكهن إلا الرحمن", "حتى لا يسقطن على الأرض حال البسط للأجنحة والقبض لها."]], "m": "يقول تعالى واعظاً عباده ليؤمنوا به ويعبدوه وحده: أأمنتم من في السماء، الذي هو العلو المطلق، وهو الله عز وجل في عليائه فوق عرشه بائن من خلقه، أن يخسف بكم الأرض فتهلكوا في جوفها، فإذا هي تتحرّك وتضطرب حتى تغوروا في بطنها؟ والجواب: لم يأمنوا ذلك، فكيف إذاً يصرّون على الشرك والتكذيب؟ أم أمنتم من في السماء أن يرسل عليكم ريحاً تحمل الحصباء والحجارة فتهلككم؟ فستعلمون كيف إنذاري لكم، إنه حق واقع مقتضاه. ولقد كذّب الذين من قبلهم كعاد وثمود رسلي، فأهلكناهم، فكيف كان إنكاري لهم؟ كان حقاً واقع المقتضى. أوَلم يروا إلى الطير فوقهم باسطات أجنحتهن ويقبضنها، ما يمسكهن في حالة البسط أو القبض إلا الرحمن، الذي أنكره المشركون وقالوا: وما الرحمن؟ وهم يعيشون في رحمته التي وسعت كل شيء، وهي متجلّية حتى في الطير تحفظه من السقوط، إنه بكل شيء بصير، سواء عنده السابح في الماء والسارح في الغبراء والطائر في السماء.", "h": ["تحذير المعرضين عن الله وإنذارهم بسوء العواقب إن استمرّوا على إعراضهم، فإن الله قادر على أن يخسف بهم الأرض أو يرسل عليهم حاصباً من السماء، وليس هناك من يؤمّنهم ويجيرهم إلا إيمانهم وإسلامهم لله عز وجل.", "في الهالكين الأوّلين عبر وعظات لمن له قلب حي وعقل يعقل به.", "من آيات الله في الآفاق الدالة على قدرته وعلمه ورحمته الموجبة لعبادته وحده طيران الطير في السماء وهو يبسط جناحيه ويقبضهما ولا يسقط، إذ الرحمن عز وجل يمسكه فلا يسقط."], "k": "«ما يمسكهن إلا الرحمن»… الذي يمسك الطير في الهواء يمسكني أنا أيضاً؛ فلماذا أقلق؟"}, {"lbl": "الآيات ٢٠ – ٢٧", "q": "أَمَّنۡ هَٰذَا ٱلَّذِي هُوَ جُندٞ لَّكُمۡ يَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَٰنِۚ إِنِ ٱلۡكَٰفِرُونَ إِلَّا فِي غُرُورٍ ﴿٢٠﴾ أَمَّنۡ هَٰذَا ٱلَّذِي يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّواْ فِي عُتُوّٖ وَنُفُورٍ ﴿٢١﴾ أَفَمَن يَمۡشِي مُكِبًّا عَلَىٰ وَجۡهِهِۦٓ أَهۡدَىٰٓ أَمَّن يَمۡشِي سَوِيًّا عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٢٢﴾ قُلۡ هُوَ ٱلَّذِيٓ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿٢٣﴾ قُلۡ هُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ ﴿٢٤﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٥﴾ قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٞ مُّبِينٞ ﴿٢٦﴾ فَلَمَّا رَأَوۡهُ زُلۡفَةٗ سِيٓـَٔتۡ وُجُوهُ ٱلَّذِينَ كَفَرُواْ وَقِيلَ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَدَّعُونَ ﴿٢٧﴾", "w": [["جند لكم", "أعوان لكم."], ["من دون الرحمن", "غيره تعالى، يدفع عنكم عذابه."], ["إن الكافرون إلا في غرور", "ما الكافرون إلا في غرور، غرّهم الشيطان بأن لا عذاب ينزل بهم."], ["إن أمسك رزقه", "إن أمسك الرحمن رزقه، فلا أحد غير الله يرسله."], ["بل لجّوا في عتوّ ونفور", "لم يتأثّروا بذلك التبكيت، بل تمادوا في التكبّر والتباعد عن الحق."], ["أفمن يمشي مكبّاً على وجهه", "واقعاً على وجهه."], ["أمّن يمشي سويّاً", "مستقيماً."], ["والأفئدة", "القلوب."], ["قليلاً ما تشكرون", "شكركم قليل."], ["ذرأكم في الأرض", "خلقكم في الأرض، وإليه تُحشرون لا إلى سواه."], ["متى هذا الوعد", "الذي تعدوننا به، وهو يوم القيامة؟"], ["قل إنما العلم عند الله", "علم مجيئه عند الله لا غير."], ["فلما رأوه زلفة", "لما رأوا العذاب قريباً منهم في عرصات القيامة."], ["سيئت وجوه الذين كفروا", "تغيّرت مسودّة."], ["هذا الذي كنتم به تدّعون", "هذا العذاب الذي كنتم تكذّبون بإنذاره وتطالبون به تحدّياً."]], "m": "ما زال السياق في مطلب هداية كفار قريش: من هذا الذي هو جند لكم ينصركم من دون الرحمن إن أراد بكم سوءاً فيدفعه عنكم؟ ما الكافرون إلا في غرور أوقعهم الشيطان فيه، زيّن لهم الشرك ومنّاهم أنه لا حساب ولا عقاب، وأن آلهتهم تشفع لهم. من هذا الذي يطعمكم ويسقيكم إن أمسك الله ربكم رزقه عنكم؟ فلو قطع عنكم المطر ما أتاكم به أحد غير الله. بل تمادوا في الكبر والتباعد عن الحق. ثم ضرب مثلاً للمشرك والموحّد: أفمن يمشي واقعاً على وجهه، وهو المشرك الذي سيُكبّ على وجهه في جهنم، أهدى أمّن يمشي مستقيماً على طريق مستقيم، وهو الموحّد؟ والجواب قطعاً: الموحّد مهتدٍ والمشرك ضال. قل هو الذي خلقكم وجعل لكم السمع والأبصار والقلوب، وأنتم لا تنكرون ذلك، فما لكم لا تشكرون المنعم بالإيمان به وطاعته؟ إنكم ما تشكرون إلا قليلاً. قل: الله هو الذي خلقكم في الأرض، لا أصنامكم التي لا تخلق ذباباً، وإليه وحده تُحشرون يوم القيامة. ويقول الكافرون: متى هذا الوعد إن كنتم صادقين؟ قل: علم مجيء يوم القيامة عند الله، وليس هو من شأني، وإنما أنا نذير مبين. فلما رأوا عذاب يوم القيامة قريباً منهم أساء الله وجوههم فتغيّرت بالاسوداد والكآبة، وقيل لهم: هذا العذاب الذي كنتم تطالبون به متحدّين رسولنا والمؤمنين.", "h": ["الكافر يعيش في غرور كامل، ولذا يرفض دعوة الحق.", "تقرير حقيقة ثابتة، وهي انحراف الكافر وضلاله، واستقامة المؤمن وهدايته.", "وجوب الشكر لله تعالى على نعمة السمع والبصر والقلب، وذلك بالإيمان والطاعة.", "تقرير عقيدة البعث والجزاء."], "k": "«وجعل لكم السمع والأبصار والأفئدة قليلاً ما تشكرون»… فيمَ استعملت سمعي وبصري اليوم؟"}, {"lbl": "الآيات ٢٨ – ٣٠", "q": "قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِيَ ٱللَّهُ وَمَن مَّعِيَ أَوۡ رَحِمَنَا فَمَن يُجِيرُ ٱلۡكَٰفِرِينَ مِنۡ عَذَابٍ أَلِيمٖ ﴿٢٨﴾ قُلۡ هُوَ ٱلرَّحۡمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٢٩﴾ قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ مَآؤُكُمۡ غَوۡرٗا فَمَن يَأۡتِيكُم بِمَآءٖ مَّعِينِۭ ﴿٣٠﴾", "w": [["قل أرأيتم", "أخبروني."], ["إن أهلكني الله ومن معي", "من المؤمنين."], ["أو رحمنا", "فلم يهلكنا."], ["فمن يجير الكافرين", "فمن يحفظ ويقي الكافرين العذاب؟"], ["قل هو الرحمن", "قل: هو الرحمن الذي أدعوكم إلى عبادته."], ["إن أصبح ماؤكم غوراً", "غائراً لا تناله الدلاء ولا تراه العيون."], ["فمن يأتيكم بماء معين", "بماء جارٍ ظاهر تراه العيون."]], "m": "ما زال السياق في مطلب هداية كفار قريش: قل يا رسولنا لهؤلاء المشركين الذين تمنّوا موتك وقالوا: نتربّص به ريب المنون: أخبروني إن أهلكني الله ومن معي من المؤمنين، أو رحمنا فلم يهلكنا، فمن يجير الكافرين من عذاب أليم؟ والجواب: لا أحد، إذاً فماذا تنتفعون بهلاكنا؟ قل هو الرحمن الذي يدعوكم إلى عبادته وحده، آمنّا به وعليه توكّلنا، أي اعتمدنا عليه وفوّضنا أمرنا إليه، فستعلمون في يوم ما من هو في ضلال مبين. قل أخبروني إن أصبح ماؤكم الذي تشربون منه، بئر زمزم وغيرها، غائراً لا تناله الدلاء، فمن يأتيكم بماء معين غير الله تعالى؟ والجواب: لا أحد، إذاً فلمَ لا تؤمنون به وتوحّدونه في عبادته؟", "h": ["بيان ما كان عليه المشركون من عداوة لرسول الله ﷺ حتى تمنّوا موته.", "وجوب التوكّل على الله عز وجل بعد الإيمان.", "مشروعية الحِجاج لإحقاق الحق وإبطال الباطل."], "k": "«فمن يأتيكم بماء معين»… كوب الماء الذي أشربه من رحمته؛ فهل أذكره عند كل شربة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (419, 68, 1, 16, 'سورة القلم ١ – ١٦', 'القلم: وإنك لعلى خلق عظيم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 419) = $j$[{"lbl": "الآيات ١ – ٧", "q": "نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ ﴿١﴾ مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونٖ ﴿٢﴾ وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونٖ ﴿٣﴾ وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٖ ﴿٤﴾ فَسَتُبۡصِرُ وَيُبۡصِرُونَ ﴿٥﴾ بِأَييِّكُمُ ٱلۡمَفۡتُونُ ﴿٦﴾ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿٧﴾", "w": [["ن", "أحد الحروف المقطّعة، يُكتب «ن» ويُقرأ «نون»."], ["والقلم وما يسطرون", "والقلم الذي كُتب به الذِّكر والقدر، والذي يخطّون ويكتبون."], ["ما أنت بنعمة ربك", "لست بما أنعم الله عليك من النبوة وما وهبك من الكمال…"], ["بمجنون", "بذي جنون كما يزعم المشركون."], ["غير ممنون", "غير مقطوع، بل هو دائم أبداً."], ["بأيّكم المفتون", "بأيكم الجنون."]], "m": "ن: أحد الحروف المقطّعة، الله أعلم بمراده به. والقلم الذي هو أول ما خلق الله، وقال له: اكتب، فقال: ما أكتب؟ قال: اكتب ما هو كائن إلى يوم القيامة، فجرى بذلك، وما يسطرون، أي ما تكتبه الملائكة نقلاً من اللوح المحفوظ، وما يكتبه الكرام الكاتبون من أعمال العباد. أقسم تعالى بهما على أنك يا رسولنا لست بنعمة ربك بمجنون، تكذيباً للمشركين الذين قالوا إن محمداً مجنون بسبب ما رأوا من الوحي وتأثّره به. وإن لك لأجراً غير مقطوع أبداً بسبب ما قدّمت من أعمال صالحة، أعظمها ما بيّنت من الهدى وما سننت من طرق الخير، إذ من سنّ سنة حسنة فله أجرها وأجر من عمل بها إلى يوم الدين. وإنك لعلى خلق عظيم، حيث أدّبه ربه، فكيف لا يكون أكمل الخلق أدباً، وقد خوطب في القرآن بمثل: «خذ العفو وأمر بالعرف وأعرض عن الجاهلين»، ومثل: «وشاورهم في الأمر»، و«ولو كنت فظاً غليظ القلب لانفضّوا من حولك»؟ وقد سُئلت عائشة عن خلقه ﷺ فقالت: كان خلقه القرآن، وقال ﷺ: «إنما بُعثت لأتمّم مكارم الأخلاق». فدُم على ما أنت عليه من الكمال واصبر على دعوتنا، فستبصر بعد قليل ويبصر قومك المتّهمون لك بأيّكم الجنون: أنت، وحاشاك، أو هم. إن ربك هو أعلم بمن ضلّ عن سبيله وهو أعلم بالمهتدين؛ وفي هذا تسلية لرسول الله ﷺ ليصبر على دعوة الله، وتهديد للمشركين، إذ سيعذّب حسب سنّته الضالّ، ويرحم المهتدي.", "h": ["تقرير مسألة أن لله تعالى أن يقسم بما شاء من خلقه.", "بيان فضل القلم الذي يُكتب به الهدى والخير.", "تقرير عقيدة القضاء والقدر، إذ كان ذلك بالقلم الذي هو أول ما خلق الله.", "بيان كمال الرسول ﷺ في أدبه وأخلاقه، وجعله قدوة في ذلك."], "k": "«وإنك لعلى خلق عظيم»… كان خلقه القرآن؛ فأي خلق من القرآن أحمله أنا اليوم؟"}, {"lbl": "الآيات ٨ – ١٦", "q": "فَلَا تُطِعِ ٱلۡمُكَذِّبِينَ ﴿٨﴾ وَدُّواْ لَوۡ تُدۡهِنُ فَيُدۡهِنُونَ ﴿٩﴾ وَلَا تُطِعۡ كُلَّ حَلَّافٖ مَّهِينٍ ﴿١٠﴾ هَمَّازٖ مَّشَّآءِۭ بِنَمِيمٖ ﴿١١﴾ مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٍ أَثِيمٍ ﴿١٢﴾ عُتُلِّۭ بَعۡدَ ذَٰلِكَ زَنِيمٍ ﴿١٣﴾ أَن كَانَ ذَا مَالٖ وَبَنِينَ ﴿١٤﴾ إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿١٥﴾ سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ ﴿١٦﴾", "w": [["ودّوا لو تُدهن", "تمنّوا وأحبّوا لو تلين لهم بألا تذكر آلهتهم بسوء."], ["فيُدهنون", "فيلينون لك، ولا يغلظون لك في القول."], ["كل حلّاف مهين", "كثير الحلف بالباطل، حقير."], ["همّاز مشّاء بنميم", "عيّاب مغتاب، نمّام ينقل الحديث على وجه الإفساد."], ["معتدٍ أثيم", "معتدٍ على الناس بأذيّتهم في أنفسهم وأموالهم، أثيم يرتكب الجرائم."], ["عُتُلّ بعد ذلك زنيم", "غليظ جافّ، زنيم: دعيّ في قريش وليس منهم."], ["قال أساطير الأولين", "ما رواه الأولون من قصص وحكايات، وليس بوحي."], ["سنسِمه على الخرطوم", "سنجعل على أنفه علامة يُعيّر بها ما عاش."]], "m": "بناءً على أنك أيها الرسول مهتدٍ وقومك ضالون فلا تطع المكذّبين بالله ولقائه وبك وبما جئت به من الدين الحق. ومما يؤكّد لك عدم مشروعية طاعتهم أنهم تمنّوا لو تلين لهم فتمالئهم بسكوتك عن آلهتهم، فيلينون بالكفّ عن أذيّتك. ثم بعدما نهاه عن إطاعة الكافرين عامة نهاه عن طاعة أفراد شرّيرين لا خير فيهم البتة كالوليد بن المغيرة: ولا تطع كل حلّاف كثير الحلف بالباطل، حقير، عيّاب، مغتاب نمّام ينقل الحديث على وجه الإفساد، منّاع للخير يبخل بالمال أشد البخل، ظالم للناس معتدٍ على أموالهم وأنفسهم، كثير الإثم لغشيانه المحرّمات، غليظ الطبع جافّ لا أدب معه، دعيّ في قريش وليس منهم. لأجل أن كان ذا مال وبنين حمله الشعور بالغنى على التكذيب بآيات الله، فإذا تُليت عليه قال: أساطير الأولين، أي أكاذيب مسطّرة من أساطير الأمم الماضية. قال تعالى: سنجعل له سمة شر وقبح يُعرف بها مدى حياته، تكون بمثابة من جُدع أنفه أو وُسم عليه.", "h": ["التنديد بأصحاب الصفات التالية: كثرة الحلف بالكذب، والمهانة، والهمز، والنميمة، والغيبة، والبخل، والاعتداء، وغشيان الذنوب، والغلظة والجفاء، والشهرة بالشر.", "التحذير من كثرة المال والولد، فإنها سبب الطغيان: «إن الإنسان ليطغى أن رآه استغنى».", "التنديد بالمكذّبين بآيات الله تعالى جملة أو تفصيلاً."], "k": "«همّاز مشّاء بنميم»… كلمة أنقلها بين اثنين قد تجعلني منهم؛ فهل أمسك لساني عن النقل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 419;
