insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (420, 68, 17, 52, 'سورة القلم ١٧ – ٥٢', 'القلم: إنا بلوناهم كما بلونا أصحاب الجنة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 420) = $j$[{"lbl": "الآيات ١٧ – ٣٣", "q": "إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ ﴿١٧﴾ وَلَا يَسۡتَثۡنُونَ ﴿١٨﴾ فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ ﴿١٩﴾ فَأَصۡبَحَتۡ كَٱلصَّرِيمِ ﴿٢٠﴾ فَتَنَادَوۡاْ مُصۡبِحِينَ ﴿٢١﴾ أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ ﴿٢٢﴾ فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ ﴿٢٣﴾ أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ ﴿٢٤﴾ وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ ﴿٢٥﴾ فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ ﴿٢٦﴾ بَلۡ نَحۡنُ مَحۡرُومُونَ ﴿٢٧﴾ قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ ﴿٢٨﴾ قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٢٩﴾ فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ ﴿٣٠﴾ قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ ﴿٣١﴾ عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ ﴿٣٢﴾ كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٣٣﴾", "w": [["إنا بلوناهم", "امتحنّا كفار مكة بالمال والولد والجاه فلم يشكروا، بل كفروا، فأصبناهم بالقحط والقتل لعلهم يتوبون."], ["ليصرمنّها مصبحين", "ليجدّنّها، أي يقطعون ثمارها صباحاً."], ["ولا يستثنون", "لم يقولوا: إن شاء الله."], ["فطاف عليها طائف من ربك وهم نائمون", "نار فأحرقتها."], ["فأصبحت كالصريم", "كالليل الأسود الشديد الظلمة."], ["أن اغدوا على حرثكم", "على غلّة جنّتكم."], ["وهم يتخافتون", "يتشاورون بأصوات مخفوضة حتى لا يُسمع بهم."], ["وغدوا على حرد قادرين", "غدوا صباحاً على قصد، قادرين على صرمها قبل أن يطّلع عليهم المساكين."], ["إنا لضالّون", "مخطئو الطريق، ما هذه جنّتنا."], ["بل نحن محرومون", "لما علموا أنها هي وقد احترقت قالوا: بل نحن محرومون منها لعزمنا على حرمان المساكين."], ["قال أوسطهم", "خيرهم تقوى، وأرجحهم عقلاً."], ["لولا تسبّحون", "هلّا تسبّحون الله وتستثنون عندما قلتم: لنصرمنّها مصبحين."], ["يتلاومون", "يلوم بعضهم بعضاً تندّماً وتحسّراً."], ["إنا إلى ربنا راغبون", "طامعون."], ["كذلك العذاب", "مثل هذا العذاب بالحرمان العذاب لمن خالف أمرنا."]], "m": "ما زال السياق في مطلب هداية قريش: إنا امتحنّا كفار قريش بالنعم لعلهم يشكرون فلم يشكروا، ثم بالقحط والجدب والقتل لعلهم يتوبون، كما بلونا أصحاب الجنة فتابوا. ثم ذكر قصتهم: إذ حلفوا ليقطعنّ ثمارها في الصباح الباكر قبل أن يعلم المساكين حتى لا يعطوهم شيئاً، ولم يقولوا: إلا أن يشاء الله، فطاف عليها نار من ربك أحرقتها وهم نائمون، فأصبحت كالليل الأسود. فنادى بعضهم بعضاً، وهم إخوة، في أول الصباح: اغدوا على حرثكم إن كنتم جادّين في الصرام، فانطلقوا مسرعين يتشاورون في صوت خافت حتى لا يفطن لهم الفقراء، وأجمعوا ألا يدخلنّها اليوم عليهم مسكين، كما كانوا يدخلونها ويأخذون منها أيام حياة والدهم، وانطلقوا على قصد تام قادرين على ذلك. فلما رأوها محترقة سوداء قالوا: إنا لضالّون عنها، أخطأنا الطريق إليها، ولما علموا أنها هي قالوا: بل نحن محرومون منها لعزمنا على منع المساكين، وقد كان والدنا يعطيهم شكراً لله. فقال أوسطهم، أي خيرهم تقوى وأرجحهم عقلاً: ألم أقل لكم لولا تسبّحون؟ أي هلّا تستثنون، وأُطلق لفظ التسبيح على الاستثناء لأن التسبيح تنزيه لله عن النقائص ومنها العجز، والذي يقول: أفعل، ولم يستثنِ، أعطى لنفسه قدرة كقدرة الله، فكان الاستثناء تسبيحاً لله وتنزيهاً له عن المشارك. فقالوا: سبحان ربنا إنا كنا ظالمين، فتابوا بهذا الاعتراف، وأقبل بعضهم على بعض يتلاومون، وقالوا: يا هلاكنا، إنا كنا متجاوزين حدود الله، ثم رجوا ربهم ولم ييأسوا: عسى ربنا أن يبدلنا خيراً منها إنا إلى ربنا راغبون. هكذا ابتُلوا بالنعمة ثم بسلبها فتابوا، وكذلك كفار قريش ابتُلوا بالنعمة ثم سُلبوها، فهل يتوبون؟ كذلك العذاب لمن خالف أمر الله، ولعذاب الآخرة أكبر لو كانوا يعلمون، فإن عذاب الدنيا محدود، أما عذاب الآخرة فأبدي.", "h": ["الابتلاء يكون بالسرّاء والضرّاء، أي بالخير والشر، وأسعد الناس الشاكرون عند السرّاء، الصابرون على طاعة الله ورسوله عند الضرّاء.", "مشروعية التذكير بأحوال المبتلين والمعافين، ليُتّخذ من ذلك طريق إلى الشكر والصبر.", "صلاح الآباء ينفع أبناء المؤمنين، فقد انتفع أصحاب الجنة بصلاح أبيهم الذي كان يتصدّق على المساكين من غلّة بستانه، وعلامة انتفاعهم توبتهم.", "مشروعية الاستثناء في اليمين، وأنه تسبيح لله تعالى، وأن تركه يوقع في الإثم، ولذا إذا حنث الحالف الذي لم يستثنِ لزمته الكفارة الشرعية: إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن لم يقدر صام ثلاثة أيام."], "k": "«أن لا يدخلنّها اليوم عليكم مسكين»… منعوا حق الفقير فاحترق الكل؛ فهل في مالي حق أمنعه؟"}, {"lbl": "الآيات ٣٤ – ٤٣", "q": "إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٣٤﴾ أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ ﴿٣٥﴾ مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿٣٦﴾ أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ ﴿٣٧﴾ إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ ﴿٣٨﴾ أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ ﴿٣٩﴾ سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ ﴿٤٠﴾ أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ ﴿٤١﴾ يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ ﴿٤٢﴾ خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ ﴿٤٣﴾", "w": [["إن للمتقين", "الذين اتقوا ربهم فآمنوا به ووحّدوه فاتقوا بذلك الشرك."], ["عند ربهم جنات النعيم", "لهم جنات النعيم يوم القيامة عند ربهم عز وجل."], ["أفنجعل المسلمين كالمجرمين", "أنحيف في الحكم فنجعل المسلمين والمجرمين متساوين في العطاء؟"], ["أم لكم كتاب فيه تدرسون", "تقرؤون فعلمتم بواسطته ما تدّعون."], ["إن لكم فيه لما تخيّرون", "فوجدتم فيه أن لكم ما تختارونه."], ["أم لكم أيمان علينا بالغة", "ألكم عهود منا موثّقة بالأيمان لا نتحلّل منها إلى يوم القيامة؟"], ["إن لكم لما تحكمون", "أن لكم ما تحكمون به لأنفسكم."], ["سلهم أيهم بذلك زعيم", "سلهم يا رسولنا عن زعيمهم الذي يكفل لهم ما يحكمون به لأنفسهم."], ["أم لهم شركاء", "أعندهم شركاء موافقون لهم يكفلون لهم ما ادّعوه؟"], ["يوم يُكشف عن ساق", "يوم يعظم الهول ويشتد الكرب، ويكشف الرب عن ساقه الكريم التي لا يشبهها شيء عندما يأتي لفصل القضاء."], ["ترهقهم ذلّة", "تغشاهم ذلّة عظيمة."], ["وقد كانوا يُدعون إلى السجود وهم سالمون", "كانوا يُدعون في الدنيا إلى الصلاة وهم سالمون من كل علّة، ولا يصلّون تكبّراً."]], "m": "نزلت هذه الآيات ردّاً على المشركين الذين ادّعوا أنهم إذا بُعثوا يُعطَون أفضل مما يُعطى المؤمنون، قياساً على حالهم في الدنيا حيث كانوا أغنياء والمؤمنون فقراء، فقال تعالى: إن للمتقين عند ربهم جنات كلها نعيم. ثم ردّ عليهم في سبعة استفهامات إنكارية: أفنجعل المسلمين الذين أسلموا لله وجوههم كالمجرمين الذين ارتكبوا الشرك والموبقات، فنحيف في حكمنا ونسوّي بينهما؟ ما لكم، أي شيء حصل لكم حتى ادّعيتم هذا؟ كيف تحكمون، ما حجتكم؟ أم لكم كتاب جاءكم به رسول تقرؤون فيه هذا الحكم؟ أم لكم عهود موثّقة بأيمان لا نتحلّل منها إلى يوم القيامة بأن لكم ما حكمتم؟ سلهم يا رسولنا أيّهم يكفل لهم ذلك؟ أم لهم شركاء يكفلونه لهم؟ فليأتوا بهم إن كانوا صادقين. بهذه الاستفهامات نفى عنهم كل ما يمكنهم أن يتشبّثوا به. واذكر لهم يوم يعظم الهول ويأتي الرب لفصل القضاء ويكشف عن ساق، فيخرّ كل مؤمن ومؤمنة ساجداً، ويحاول المنافقون السجود فلا يستطيعون، إذ يكون ظهر أحدهم طبقاً واحداً، وذلك علامة شقائه المترتب على نفاقه، خاشعة أبصارهم لا تطرف من شدة الخوف، تغشاهم ذلّة عظيمة، وقد كانوا في الدنيا يُدعون إلى السجود وهم سالمون معافون في أبدانهم فلا يسجدون تكبّراً وكفراً.", "h": ["تقرير أن المجرمين لا يساوون المؤمنين يوم القيامة، إذ لا يستوي أصحاب النار وأصحاب الجنة، فمن زعم أنه يُعطى ما يُعطاه المؤمنون من جنات النعيم فهو مخطئ في تصوّره، كاذب في قوله.", "بيان عظم هول يوم القيامة، وأن الرب تبارك وتعالى يأتي لفصل القضاء ويكشف عن ساق فلا يبقى أحد إلا سجد، وأن الكافر والمنافق لا يستطيع السجود عقوبة له وفضيحة، إذ كان في الدنيا يُدعى إلى الصلاة فلا يصلّي تكبّراً وكفراً."], "k": "«وقد كانوا يُدعون إلى السجود وهم سالمون»… أنا سالم الآن؛ فهل أغتنم السجود قبل أن يُحال بيني وبينه؟"}, {"lbl": "الآيات ٤٤ – ٥٢", "q": "فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ﴿٤٤﴾ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ ﴿٤٥﴾ أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ ﴿٤٦﴾ أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ ﴿٤٧﴾ فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ ﴿٤٨﴾ لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ ﴿٤٩﴾ فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ ﴿٥٠﴾ وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ ﴿٥١﴾ وَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٥٢﴾", "w": [["فذرني ومن يكذّب", "دعني ومن لا يصدّق."], ["بهذا الحديث", "بالقرآن الكريم."], ["سنستدرجهم", "نستنزلهم درجة درجة حتى نصل بهم إلى العذاب."], ["وأملي لهم", "وأمهلهم."], ["إن كيدي متين", "شديد قويّ لا يُطاق."], ["فهم من مغرم مثقلون", "فهم مما يعطونكه مكلّفون حملاً ثقيلاً."], ["أم عندهم الغيب", "اللوح المحفوظ."], ["فهم يكتبون", "ينقلون منه ما يدّعونه."], ["ولا تكن كصاحب الحوت", "يونس، في الضجر والعجلة."], ["وهو مكظوم", "مملوء غمّاً."], ["لنُبذ بالعراء", "بالأرض الفضاء، لكن لما تاب نُبذ وهو غير مذموم."], ["فاجتباه ربه", "اصطفاه."], ["ليُزلقونك بأبصارهم", "ينظرون إليك نظراً شديداً يكاد أن يصرعك."], ["وما هو إلا ذكر للعالمين", "محمد ﷺ ذكر للإنس والجن، فليس بمجنون كما يقول المبطلون."]], "m": "بعد ذلك التقريع الشديد للمشركين الذي لم يؤثّر في نفوسهم، قال تعالى لرسوله: فذرني ومن يكذّب بهذا القرآن، دعني وإياهم، سنستنزلهم درجة درجة من حيث لا يعلمون حتى ننتهي بهم إلى عذابهم، وأمهلهم فلا أعاجلهم، فأوسّع لهم في الرزق وأصحّح لهم الجسم حتى يروا أن هذا لكرامتهم وأنهم خير من المؤمنين، ثم نأخذهم، وهذا من كيدي الشديد. أم تسألهم على تبليغ الدعوة أجراً فهم يشعرون بحمل ثقيل فلذا لا يتابعونك؟ أم عندهم اللوح المحفوظ فهم ينقلون منه ما يقولون؟ والجواب: لا، إذاً فاصبر يا رسولنا لحكم ربك وامضِ في دعوتك، ولا تكن كصاحب الحوت يونس بن متّى في الضجر وعدم الصبر، إذ نادى وهو مملوء غمّاً: لا إله إلا أنت سبحانك إني كنت من الظالمين، لولا أن أدركته رحمة الله حيث ألهمه التوبة ووفّقه لها لطُرح بالفضاء وهو مذموم، لكن لما تاب طُرح على ساحل البحر وهو غير مذموم، فاصطفاه ربه مرة ثانية فجعله من الكاملين في الصلاح، وأرسله إلى مائة ألف أو يزيدون فآمنوا. وإن يكاد الذين كفروا ليصرعونك من شدة النظر إليك غيظاً وحنقاً لما سمعوا القرآن تقرؤه عليهم، ويقولون حسداً وصرفاً للناس عنك: إنه لمجنون، وما هو إلا ذكر للعالمين يذكّر الله به الإنس والجن.", "h": ["ردّ الأمور إلى الله إذا استعصى حلّها، فالله كفيل بذلك.", "لا يصح أخذ أجرة على تبليغ الدعوة.", "وجوب الصبر على الدعوة مهما كانت الصعاب، فلا تُترك لأذى يصيب الداعي.", "بيان حال المشركين مع الرسول ﷺ، وما كانوا يضمرونه له من البغض والحسد، وما يرمونه به من الاتهامات الباطلة كالجنون والسحر والكذب."], "k": "«فاصبر لحكم ربك ولا تكن كصاحب الحوت»… حين أضجر من طول الطريق، فلأتذكّر: لا إله إلا أنت سبحانك."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 420;
insert into public.tdb_cards(topic, i, body) select 420, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧ – ٣٣", "q": "إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ ﴿١٧﴾ وَلَا يَسۡتَثۡنُونَ ﴿١٨﴾ فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ ﴿١٩﴾ فَأَصۡبَحَتۡ كَٱلصَّرِيمِ ﴿٢٠﴾ فَتَنَادَوۡاْ مُصۡبِحِينَ ﴿٢١﴾ أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ ﴿٢٢﴾ فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ ﴿٢٣﴾ أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ ﴿٢٤﴾ وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ ﴿٢٥﴾ فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ ﴿٢٦﴾ بَلۡ نَحۡنُ مَحۡرُومُونَ ﴿٢٧﴾ قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ ﴿٢٨﴾ قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٢٩﴾ فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ ﴿٣٠﴾ قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ ﴿٣١﴾ عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ ﴿٣٢﴾ كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٣٣﴾", "w": [["إنا بلوناهم", "امتحنّا كفار مكة بالمال والولد والجاه فلم يشكروا، بل كفروا، فأصبناهم بالقحط والقتل لعلهم يتوبون."], ["ليصرمنّها مصبحين", "ليجدّنّها، أي يقطعون ثمارها صباحاً."], ["ولا يستثنون", "لم يقولوا: إن شاء الله."], ["فطاف عليها طائف من ربك وهم نائمون", "نار فأحرقتها."], ["فأصبحت كالصريم", "كالليل الأسود الشديد الظلمة."], ["أن اغدوا على حرثكم", "على غلّة جنّتكم."], ["وهم يتخافتون", "يتشاورون بأصوات مخفوضة حتى لا يُسمع بهم."], ["وغدوا على حرد قادرين", "غدوا صباحاً على قصد، قادرين على صرمها قبل أن يطّلع عليهم المساكين."], ["إنا لضالّون", "مخطئو الطريق، ما هذه جنّتنا."], ["بل نحن محرومون", "لما علموا أنها هي وقد احترقت قالوا: بل نحن محرومون منها لعزمنا على حرمان المساكين."], ["قال أوسطهم", "خيرهم تقوى، وأرجحهم عقلاً."], ["لولا تسبّحون", "هلّا تسبّحون الله وتستثنون عندما قلتم: لنصرمنّها مصبحين."], ["يتلاومون", "يلوم بعضهم بعضاً تندّماً وتحسّراً."], ["إنا إلى ربنا راغبون", "طامعون."], ["كذلك العذاب", "مثل هذا العذاب بالحرمان العذاب لمن خالف أمرنا."]], "m": "ما زال السياق في مطلب هداية قريش: إنا امتحنّا كفار قريش بالنعم لعلهم يشكرون فلم يشكروا، ثم بالقحط والجدب والقتل لعلهم يتوبون، كما بلونا أصحاب الجنة فتابوا. ثم ذكر قصتهم: إذ حلفوا ليقطعنّ ثمارها في الصباح الباكر قبل أن يعلم المساكين حتى لا يعطوهم شيئاً، ولم يقولوا: إلا أن يشاء الله، فطاف عليها نار من ربك أحرقتها وهم نائمون، فأصبحت كالليل الأسود. فنادى بعضهم بعضاً، وهم إخوة، في أول الصباح: اغدوا على حرثكم إن كنتم جادّين في الصرام، فانطلقوا مسرعين يتشاورون في صوت خافت حتى لا يفطن لهم الفقراء، وأجمعوا ألا يدخلنّها اليوم عليهم مسكين، كما كانوا يدخلونها ويأخذون منها أيام حياة والدهم، وانطلقوا على قصد تام قادرين على ذلك. فلما رأوها محترقة سوداء قالوا: إنا لضالّون عنها، أخطأنا الطريق إليها، ولما علموا أنها هي قالوا: بل نحن محرومون منها لعزمنا على منع المساكين، وقد كان والدنا يعطيهم شكراً لله. فقال أوسطهم، أي خيرهم تقوى وأرجحهم عقلاً: ألم أقل لكم لولا تسبّحون؟ أي هلّا تستثنون، وأُطلق لفظ التسبيح على الاستثناء لأن التسبيح تنزيه لله عن النقائص ومنها العجز، والذي يقول: أفعل، ولم يستثنِ، أعطى لنفسه قدرة كقدرة الله، فكان الاستثناء تسبيحاً لله وتنزيهاً له عن المشارك. فقالوا: سبحان ربنا إنا كنا ظالمين، فتابوا بهذا الاعتراف، وأقبل بعضهم على بعض يتلاومون، وقالوا: يا هلاكنا، إنا كنا متجاوزين حدود الله، ثم رجوا ربهم ولم ييأسوا: عسى ربنا أن يبدلنا خيراً منها إنا إلى ربنا راغبون. هكذا ابتُلوا بالنعمة ثم بسلبها فتابوا، وكذلك كفار قريش ابتُلوا بالنعمة ثم سُلبوها، فهل يتوبون؟ كذلك العذاب لمن خالف أمر الله، ولعذاب الآخرة أكبر لو كانوا يعلمون، فإن عذاب الدنيا محدود، أما عذاب الآخرة فأبدي.", "h": ["الابتلاء يكون بالسرّاء والضرّاء، أي بالخير والشر، وأسعد الناس الشاكرون عند السرّاء، الصابرون على طاعة الله ورسوله عند الضرّاء.", "مشروعية التذكير بأحوال المبتلين والمعافين، ليُتّخذ من ذلك طريق إلى الشكر والصبر.", "صلاح الآباء ينفع أبناء المؤمنين، فقد انتفع أصحاب الجنة بصلاح أبيهم الذي كان يتصدّق على المساكين من غلّة بستانه، وعلامة انتفاعهم توبتهم.", "مشروعية الاستثناء في اليمين، وأنه تسبيح لله تعالى، وأن تركه يوقع في الإثم، ولذا إذا حنث الحالف الذي لم يستثنِ لزمته الكفارة الشرعية: إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن لم يقدر صام ثلاثة أيام."], "k": "«أن لا يدخلنّها اليوم عليكم مسكين»… منعوا حق الفقير فاحترق الكل؛ فهل في مالي حق أمنعه؟"}, {"lbl": "الآيات ٣٤ – ٤٣", "q": "إِنَّ لِلۡمُتَّقِينَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِيمِ ﴿٣٤﴾ أَفَنَجۡعَلُ ٱلۡمُسۡلِمِينَ كَٱلۡمُجۡرِمِينَ ﴿٣٥﴾ مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ ﴿٣٦﴾ أَمۡ لَكُمۡ كِتَٰبٞ فِيهِ تَدۡرُسُونَ ﴿٣٧﴾ إِنَّ لَكُمۡ فِيهِ لَمَا تَخَيَّرُونَ ﴿٣٨﴾ أَمۡ لَكُمۡ أَيۡمَٰنٌ عَلَيۡنَا بَٰلِغَةٌ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ ﴿٣٩﴾ سَلۡهُمۡ أَيُّهُم بِذَٰلِكَ زَعِيمٌ ﴿٤٠﴾ أَمۡ لَهُمۡ شُرَكَآءُ فَلۡيَأۡتُواْ بِشُرَكَآئِهِمۡ إِن كَانُواْ صَٰدِقِينَ ﴿٤١﴾ يَوۡمَ يُكۡشَفُ عَن سَاقٖ وَيُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا يَسۡتَطِيعُونَ ﴿٤٢﴾ خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۖ وَقَدۡ كَانُواْ يُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَٰلِمُونَ ﴿٤٣﴾", "w": [["إن للمتقين", "الذين اتقوا ربهم فآمنوا به ووحّدوه فاتقوا بذلك الشرك."], ["عند ربهم جنات النعيم", "لهم جنات النعيم يوم القيامة عند ربهم عز وجل."], ["أفنجعل المسلمين كالمجرمين", "أنحيف في الحكم فنجعل المسلمين والمجرمين متساوين في العطاء؟"], ["أم لكم كتاب فيه تدرسون", "تقرؤون فعلمتم بواسطته ما تدّعون."], ["إن لكم فيه لما تخيّرون", "فوجدتم فيه أن لكم ما تختارونه."], ["أم لكم أيمان علينا بالغة", "ألكم عهود منا موثّقة بالأيمان لا نتحلّل منها إلى يوم القيامة؟"], ["إن لكم لما تحكمون", "أن لكم ما تحكمون به لأنفسكم."], ["سلهم أيهم بذلك زعيم", "سلهم يا رسولنا عن زعيمهم الذي يكفل لهم ما يحكمون به لأنفسهم."], ["أم لهم شركاء", "أعندهم شركاء موافقون لهم يكفلون لهم ما ادّعوه؟"], ["يوم يُكشف عن ساق", "يوم يعظم الهول ويشتد الكرب، ويكشف الرب عن ساقه الكريم التي لا يشبهها شيء عندما يأتي لفصل القضاء."], ["ترهقهم ذلّة", "تغشاهم ذلّة عظيمة."], ["وقد كانوا يُدعون إلى السجود وهم سالمون", "كانوا يُدعون في الدنيا إلى الصلاة وهم سالمون من كل علّة، ولا يصلّون تكبّراً."]], "m": "نزلت هذه الآيات ردّاً على المشركين الذين ادّعوا أنهم إذا بُعثوا يُعطَون أفضل مما يُعطى المؤمنون، قياساً على حالهم في الدنيا حيث كانوا أغنياء والمؤمنون فقراء، فقال تعالى: إن للمتقين عند ربهم جنات كلها نعيم. ثم ردّ عليهم في سبعة استفهامات إنكارية: أفنجعل المسلمين الذين أسلموا لله وجوههم كالمجرمين الذين ارتكبوا الشرك والموبقات، فنحيف في حكمنا ونسوّي بينهما؟ ما لكم، أي شيء حصل لكم حتى ادّعيتم هذا؟ كيف تحكمون، ما حجتكم؟ أم لكم كتاب جاءكم به رسول تقرؤون فيه هذا الحكم؟ أم لكم عهود موثّقة بأيمان لا نتحلّل منها إلى يوم القيامة بأن لكم ما حكمتم؟ سلهم يا رسولنا أيّهم يكفل لهم ذلك؟ أم لهم شركاء يكفلونه لهم؟ فليأتوا بهم إن كانوا صادقين. بهذه الاستفهامات نفى عنهم كل ما يمكنهم أن يتشبّثوا به. واذكر لهم يوم يعظم الهول ويأتي الرب لفصل القضاء ويكشف عن ساق، فيخرّ كل مؤمن ومؤمنة ساجداً، ويحاول المنافقون السجود فلا يستطيعون، إذ يكون ظهر أحدهم طبقاً واحداً، وذلك علامة شقائه المترتب على نفاقه، خاشعة أبصارهم لا تطرف من شدة الخوف، تغشاهم ذلّة عظيمة، وقد كانوا في الدنيا يُدعون إلى السجود وهم سالمون معافون في أبدانهم فلا يسجدون تكبّراً وكفراً.", "h": ["تقرير أن المجرمين لا يساوون المؤمنين يوم القيامة، إذ لا يستوي أصحاب النار وأصحاب الجنة، فمن زعم أنه يُعطى ما يُعطاه المؤمنون من جنات النعيم فهو مخطئ في تصوّره، كاذب في قوله.", "بيان عظم هول يوم القيامة، وأن الرب تبارك وتعالى يأتي لفصل القضاء ويكشف عن ساق فلا يبقى أحد إلا سجد، وأن الكافر والمنافق لا يستطيع السجود عقوبة له وفضيحة، إذ كان في الدنيا يُدعى إلى الصلاة فلا يصلّي تكبّراً وكفراً."], "k": "«وقد كانوا يُدعون إلى السجود وهم سالمون»… أنا سالم الآن؛ فهل أغتنم السجود قبل أن يُحال بيني وبينه؟"}, {"lbl": "الآيات ٤٤ – ٥٢", "q": "فَذَرۡنِي وَمَن يُكَذِّبُ بِهَٰذَا ٱلۡحَدِيثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ﴿٤٤﴾ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ ﴿٤٥﴾ أَمۡ تَسۡـَٔلُهُمۡ أَجۡرٗا فَهُم مِّن مَّغۡرَمٖ مُّثۡقَلُونَ ﴿٤٦﴾ أَمۡ عِندَهُمُ ٱلۡغَيۡبُ فَهُمۡ يَكۡتُبُونَ ﴿٤٧﴾ فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ ﴿٤٨﴾ لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ ﴿٤٩﴾ فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ ﴿٥٠﴾ وَإِن يَكَادُ ٱلَّذِينَ كَفَرُواْ لَيُزۡلِقُونَكَ بِأَبۡصَٰرِهِمۡ لَمَّا سَمِعُواْ ٱلذِّكۡرَ وَيَقُولُونَ إِنَّهُۥ لَمَجۡنُونٞ ﴿٥١﴾ وَمَا هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ﴿٥٢﴾", "w": [["فذرني ومن يكذّب", "دعني ومن لا يصدّق."], ["بهذا الحديث", "بالقرآن الكريم."], ["سنستدرجهم", "نستنزلهم درجة درجة حتى نصل بهم إلى العذاب."], ["وأملي لهم", "وأمهلهم."], ["إن كيدي متين", "شديد قويّ لا يُطاق."], ["فهم من مغرم مثقلون", "فهم مما يعطونكه مكلّفون حملاً ثقيلاً."], ["أم عندهم الغيب", "اللوح المحفوظ."], ["فهم يكتبون", "ينقلون منه ما يدّعونه."], ["ولا تكن كصاحب الحوت", "يونس، في الضجر والعجلة."], ["وهو مكظوم", "مملوء غمّاً."], ["لنُبذ بالعراء", "بالأرض الفضاء، لكن لما تاب نُبذ وهو غير مذموم."], ["فاجتباه ربه", "اصطفاه."], ["ليُزلقونك بأبصارهم", "ينظرون إليك نظراً شديداً يكاد أن يصرعك."], ["وما هو إلا ذكر للعالمين", "محمد ﷺ ذكر للإنس والجن، فليس بمجنون كما يقول المبطلون."]], "m": "بعد ذلك التقريع الشديد للمشركين الذي لم يؤثّر في نفوسهم، قال تعالى لرسوله: فذرني ومن يكذّب بهذا القرآن، دعني وإياهم، سنستنزلهم درجة درجة من حيث لا يعلمون حتى ننتهي بهم إلى عذابهم، وأمهلهم فلا أعاجلهم، فأوسّع لهم في الرزق وأصحّح لهم الجسم حتى يروا أن هذا لكرامتهم وأنهم خير من المؤمنين، ثم نأخذهم، وهذا من كيدي الشديد. أم تسألهم على تبليغ الدعوة أجراً فهم يشعرون بحمل ثقيل فلذا لا يتابعونك؟ أم عندهم اللوح المحفوظ فهم ينقلون منه ما يقولون؟ والجواب: لا، إذاً فاصبر يا رسولنا لحكم ربك وامضِ في دعوتك، ولا تكن كصاحب الحوت يونس بن متّى في الضجر وعدم الصبر، إذ نادى وهو مملوء غمّاً: لا إله إلا أنت سبحانك إني كنت من الظالمين، لولا أن أدركته رحمة الله حيث ألهمه التوبة ووفّقه لها لطُرح بالفضاء وهو مذموم، لكن لما تاب طُرح على ساحل البحر وهو غير مذموم، فاصطفاه ربه مرة ثانية فجعله من الكاملين في الصلاح، وأرسله إلى مائة ألف أو يزيدون فآمنوا. وإن يكاد الذين كفروا ليصرعونك من شدة النظر إليك غيظاً وحنقاً لما سمعوا القرآن تقرؤه عليهم، ويقولون حسداً وصرفاً للناس عنك: إنه لمجنون، وما هو إلا ذكر للعالمين يذكّر الله به الإنس والجن.", "h": ["ردّ الأمور إلى الله إذا استعصى حلّها، فالله كفيل بذلك.", "لا يصح أخذ أجرة على تبليغ الدعوة.", "وجوب الصبر على الدعوة مهما كانت الصعاب، فلا تُترك لأذى يصيب الداعي.", "بيان حال المشركين مع الرسول ﷺ، وما كانوا يضمرونه له من البغض والحسد، وما يرمونه به من الاتهامات الباطلة كالجنون والسحر والكذب."], "k": "«فاصبر لحكم ربك ولا تكن كصاحب الحوت»… حين أضجر من طول الطريق، فلأتذكّر: لا إله إلا أنت سبحانك."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (421, 69, 1, 24, 'سورة الحاقة ١ – ٢٤', 'الحاقة: هاؤم اقرؤوا كتابيه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 421) = $j$[{"lbl": "الآيات ١ – ١٢", "q": "ٱلۡحَآقَّةُ ﴿١﴾ مَا ٱلۡحَآقَّةُ ﴿٢﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡحَآقَّةُ ﴿٣﴾ كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ ﴿٤﴾ فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ ﴿٥﴾ وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ ﴿٦﴾ سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ ﴿٧﴾ فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ ﴿٨﴾ وَجَآءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَٰتُ بِٱلۡخَاطِئَةِ ﴿٩﴾ فَعَصَوۡاْ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةٗ رَّابِيَةً ﴿١٠﴾ إِنَّا لَمَّا طَغَا ٱلۡمَآءُ حَمَلۡنَٰكُمۡ فِي ٱلۡجَارِيَةِ ﴿١١﴾ لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةٗ وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ ﴿١٢﴾", "w": [["الحاقّة", "الساعة الواجبة الوقوع، وهي القيامة."], ["بالقارعة", "بالقيامة، لأنها تقرع القلوب بالخوف والهول."], ["فأُهلكوا بالطاغية", "بطغيانهم وعتوّهم عن أمر ربهم، فأخذتهم صيحة طاغية."], ["بريح صرصر عاتية", "ذات صوت لشدة عصوفها، عاتية في الهبوب."], ["حسوماً", "متتابعات الهبوب بلا فاصل، كتتابع الكيّ القاطع للداء."], ["كأنهم أعجاز نخل خاوية", "أصول نخل ساقطة فارغة ليس في جوفها شيء."], ["والمؤتفكات بالخاطئة", "أهل قرى لوط بالفعلات ذات الخطأ."], ["أخذة رابية", "زائدة في الشدة على غيرها."], ["لما طغى الماء", "علا فوق كل شيء من الجبال وغيرها."], ["حملناكم في الجارية", "في السفينة التي صنعها نوح ونجا بها هو ومن معه من المؤمنين."], ["وتعيها أذن واعية", "وتحفظها أذن حافظة لما تسمع."]], "m": "الحاقّة، أي شيء هي؟ وما أعلمك بها؟ والمراد بها القيامة، لأنها حاقّة المجيء واجبته لا محالة. كذّبت ثمود قوم صالح وعاد قوم هود بالقيامة، فهم ككفار قريش مكذّبون بالبعث والجزاء. فأما ثمود فأُهلكوا بطغيانهم وعتوّهم، فأخذتهم صيحة طاغية، وأما عاد فأُهلكوا بريح ذات صوت شديد عاتية، سخّرها الله عليهم سبع ليال وثمانية أيام متتابعات بلا انقطاع حسماً لوجودهم، كما يحسم الكيّ الداء، فترى القوم فيها صرعى ساقطين على الأرض كأنهم أصول نخل ساقطة فارغة، فهل ترى لهم من باقية؟ لا شيء، إذ هلكوا أجمعون. وجاء فرعون ومن قبله كقوم نوح، والمؤتفكات قرى لوط، بالأفعال الخاطئة وهي الشرك والمعاصي، فعصوا رسول ربهم فأخذهم أخذة زائدة في الشدة. إنا لما طغى ماء الطوفان الذي أهلك الله به قوم نوح حملنا آباءكم في سفينة نوح، لنجعلها لكم عظة وعبرة، وتحفظ هذه العظة أذن حافظة لا تنسى ما هو حق وخير.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان أن كلاً من عاد وثمود كانوا يكذّبون بالبعث، وبيان ما أهلكهم الله به.", "بيان أن معصية الرسول موجبة للعذاب الدنيوي والأخروي.", "التذكير بحادثة الطوفان وما فيها من عظة وعبرة."], "k": "«وتعيها أذن واعية»… أسمع كثيراً وأنسى كثيراً؛ فهل أذني واعية أم مستمعة فقط؟"}, {"lbl": "الآيات ١٣ – ١٨", "q": "فَإِذَا نُفِخَ فِي ٱلصُّورِ نَفۡخَةٞ وَٰحِدَةٞ ﴿١٣﴾ وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةٗ وَٰحِدَةٗ ﴿١٤﴾ فَيَوۡمَئِذٖ وَقَعَتِ ٱلۡوَاقِعَةُ ﴿١٥﴾ وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِيَ يَوۡمَئِذٖ وَاهِيَةٞ ﴿١٦﴾ وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذٖ ثَمَٰنِيَةٞ ﴿١٧﴾ يَوۡمَئِذٖ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةٞ ﴿١٨﴾", "w": [["نفخة واحدة", "النفخة الأولى."], ["وحُملت الأرض والجبال", "رُفعت من أماكنها."], ["فدُكّتا دكّة واحدة", "ضُرب بعضها ببعض فاندكّت وصارت كثيباً مهيلاً."], ["فهي يومئذ واهية", "مسترخية ضعيفة القوة."], ["والملك على أرجائها", "على أطرافها وحافّاتها."], ["ويحمل عرش ربك فوقهم يومئذ ثمانية", "ثمانية من الملائكة، وهم حملة العرش الأربعة وزيد عليهم أربعة."], ["لا تخفى منكم خافية", "لا تخفى منكم سريرة من السرائر التي تخفونها."]], "m": "ما زال السياق في الحديث عن القيامة تقريراً لعقيدة البعث والجزاء التي هي الدافع إلى فعل الخير وترك الشر في الدنيا: فإذا نفخ إسرافيل في الصور، وهو القرن، النفخة الأولى، ورُفعت الأرض والجبال فضُرب بعضها ببعض فاندكّت فصارت هباءً منبثّاً، فيومئذ قامت القيامة، وانشقّت السماء وتمزّقت، فهي يومئذ ضعيفة مسترخية، والملائكة على أطرافها، ويحمل عرش ربك فوقهم يومئذ ثمانية من الملائكة، أربعة هم حملة العرش دائماً وزيد عليهم أربعة. يومئذ تُعرضون على الله، لا تخفى منكم سريرة مما كنتم تخفونه.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان كيفية الانقلاب الكوني لنهاية الحياة الأولى.", "تقرير العرض على الله عز وجل للحساب ثم الجزاء."], "k": "«لا تخفى منكم خافية»… ما الذي أخفيه اليوم وأخاف أن يُعرض؟ فلأصلحه قبل العرض."}, {"lbl": "الآيات ١٩ – ٢٤", "q": "فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ ﴿١٩﴾ إِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ حِسَابِيَهۡ ﴿٢٠﴾ فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ ﴿٢١﴾ فِي جَنَّةٍ عَالِيَةٖ ﴿٢٢﴾ قُطُوفُهَا دَانِيَةٞ ﴿٢٣﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ ﴿٢٤﴾", "w": [["هاؤم اقرؤوا كتابيه", "خذوا كتابي فاقرؤوه."], ["إني ظننت", "علمت."], ["أني ملاقٍ حسابيه", "أني ملاقٍ حسابي لا محالة."], ["في عيشة راضية", "يرضى بها صاحبها."], ["قطوفها دانية", "ما يُقتطف ويُجنى من ثمارها قريب التناول."], ["بما أسلفتم", "بما قدّمتم."], ["في الأيام الخالية", "الماضية."]], "m": "بعد مجيء الرب تبارك وتعالى لفصل القضاء تُعطى الكتب، فمن آخذ كتابه بيمينه، ومن آخذ كتابه بشماله؛ فأما من أوتي كتابه الذي ضمّ حسناته بيمينه فيقول في فرح عظيم: خذوا كتابي فاقرؤوه، إنه مشرق كله، ما فيه سواد السيئات، ويعلّل سلامة كتابه فيقول: إني علمت أني ملاقٍ حسابي لا محالة، فلذا لم أقارف السيئات، وإن قارفت شيئاً جهلاً تبت منه فوراً فانمحى أثره. قال تعالى: فهو في عيشة يرضاها لهناءتها وسعة خيراتها، في جنة عالية، ثمارها قريبة التناول ينالها بيده وهو متّكئ على أريكته، ويقال لهم: كلوا واشربوا هنيئاً بما قدّمتم لأنفسكم في أيام الدنيا الماضية، إذ كانوا مؤمنين صوّامين قوّامين آمرين بالمعروف ناهين عن المنكر.", "h": ["تقرير عقيدة البعث والجزاء، أي الإيمان باليوم الآخر.", "آثار الإيمان بالبعث والجزاء ظاهرة في سلامة كتاب المؤمن من السيئات، وقد علّل لذلك بقوله: إني ظننت أني ملاقٍ حسابيه، فلذا لم أعصِ ربي.", "إثبات حقيقة هي قول العامة: الدنيا مزرعة الآخرة، أي من عمل في الدنيا نال ثمار عمله في الآخرة خيراً أو شراً."], "k": "«إني ظننت أني ملاقٍ حسابيه»… اليقين بالحساب هو الذي بيّض كتابه؛ فكم في قلبي منه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 421;
insert into public.tdb_cards(topic, i, body) select 421, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٢", "q": "ٱلۡحَآقَّةُ ﴿١﴾ مَا ٱلۡحَآقَّةُ ﴿٢﴾ وَمَآ أَدۡرَىٰكَ مَا ٱلۡحَآقَّةُ ﴿٣﴾ كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ ﴿٤﴾ فَأَمَّا ثَمُودُ فَأُهۡلِكُواْ بِٱلطَّاغِيَةِ ﴿٥﴾ وَأَمَّا عَادٞ فَأُهۡلِكُواْ بِرِيحٖ صَرۡصَرٍ عَاتِيَةٖ ﴿٦﴾ سَخَّرَهَا عَلَيۡهِمۡ سَبۡعَ لَيَالٖ وَثَمَٰنِيَةَ أَيَّامٍ حُسُومٗاۖ فَتَرَى ٱلۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٖ ﴿٧﴾ فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٖ ﴿٨﴾ وَجَآءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَٰتُ بِٱلۡخَاطِئَةِ ﴿٩﴾ فَعَصَوۡاْ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةٗ رَّابِيَةً ﴿١٠﴾ إِنَّا لَمَّا طَغَا ٱلۡمَآءُ حَمَلۡنَٰكُمۡ فِي ٱلۡجَارِيَةِ ﴿١١﴾ لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةٗ وَتَعِيَهَآ أُذُنٞ وَٰعِيَةٞ ﴿١٢﴾", "w": [["الحاقّة", "الساعة الواجبة الوقوع، وهي القيامة."], ["بالقارعة", "بالقيامة، لأنها تقرع القلوب بالخوف والهول."], ["فأُهلكوا بالطاغية", "بطغيانهم وعتوّهم عن أمر ربهم، فأخذتهم صيحة طاغية."], ["بريح صرصر عاتية", "ذات صوت لشدة عصوفها، عاتية في الهبوب."], ["حسوماً", "متتابعات الهبوب بلا فاصل، كتتابع الكيّ القاطع للداء."], ["كأنهم أعجاز نخل خاوية", "أصول نخل ساقطة فارغة ليس في جوفها شيء."], ["والمؤتفكات بالخاطئة", "أهل قرى لوط بالفعلات ذات الخطأ."], ["أخذة رابية", "زائدة في الشدة على غيرها."], ["لما طغى الماء", "علا فوق كل شيء من الجبال وغيرها."], ["حملناكم في الجارية", "في السفينة التي صنعها نوح ونجا بها هو ومن معه من المؤمنين."], ["وتعيها أذن واعية", "وتحفظها أذن حافظة لما تسمع."]], "m": "الحاقّة، أي شيء هي؟ وما أعلمك بها؟ والمراد بها القيامة، لأنها حاقّة المجيء واجبته لا محالة. كذّبت ثمود قوم صالح وعاد قوم هود بالقيامة، فهم ككفار قريش مكذّبون بالبعث والجزاء. فأما ثمود فأُهلكوا بطغيانهم وعتوّهم، فأخذتهم صيحة طاغية، وأما عاد فأُهلكوا بريح ذات صوت شديد عاتية، سخّرها الله عليهم سبع ليال وثمانية أيام متتابعات بلا انقطاع حسماً لوجودهم، كما يحسم الكيّ الداء، فترى القوم فيها صرعى ساقطين على الأرض كأنهم أصول نخل ساقطة فارغة، فهل ترى لهم من باقية؟ لا شيء، إذ هلكوا أجمعون. وجاء فرعون ومن قبله كقوم نوح، والمؤتفكات قرى لوط، بالأفعال الخاطئة وهي الشرك والمعاصي، فعصوا رسول ربهم فأخذهم أخذة زائدة في الشدة. إنا لما طغى ماء الطوفان الذي أهلك الله به قوم نوح حملنا آباءكم في سفينة نوح، لنجعلها لكم عظة وعبرة، وتحفظ هذه العظة أذن حافظة لا تنسى ما هو حق وخير.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان أن كلاً من عاد وثمود كانوا يكذّبون بالبعث، وبيان ما أهلكهم الله به.", "بيان أن معصية الرسول موجبة للعذاب الدنيوي والأخروي.", "التذكير بحادثة الطوفان وما فيها من عظة وعبرة."], "k": "«وتعيها أذن واعية»… أسمع كثيراً وأنسى كثيراً؛ فهل أذني واعية أم مستمعة فقط؟"}, {"lbl": "الآيات ١٣ – ١٨", "q": "فَإِذَا نُفِخَ فِي ٱلصُّورِ نَفۡخَةٞ وَٰحِدَةٞ ﴿١٣﴾ وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةٗ وَٰحِدَةٗ ﴿١٤﴾ فَيَوۡمَئِذٖ وَقَعَتِ ٱلۡوَاقِعَةُ ﴿١٥﴾ وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِيَ يَوۡمَئِذٖ وَاهِيَةٞ ﴿١٦﴾ وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذٖ ثَمَٰنِيَةٞ ﴿١٧﴾ يَوۡمَئِذٖ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِيَةٞ ﴿١٨﴾", "w": [["نفخة واحدة", "النفخة الأولى."], ["وحُملت الأرض والجبال", "رُفعت من أماكنها."], ["فدُكّتا دكّة واحدة", "ضُرب بعضها ببعض فاندكّت وصارت كثيباً مهيلاً."], ["فهي يومئذ واهية", "مسترخية ضعيفة القوة."], ["والملك على أرجائها", "على أطرافها وحافّاتها."], ["ويحمل عرش ربك فوقهم يومئذ ثمانية", "ثمانية من الملائكة، وهم حملة العرش الأربعة وزيد عليهم أربعة."], ["لا تخفى منكم خافية", "لا تخفى منكم سريرة من السرائر التي تخفونها."]], "m": "ما زال السياق في الحديث عن القيامة تقريراً لعقيدة البعث والجزاء التي هي الدافع إلى فعل الخير وترك الشر في الدنيا: فإذا نفخ إسرافيل في الصور، وهو القرن، النفخة الأولى، ورُفعت الأرض والجبال فضُرب بعضها ببعض فاندكّت فصارت هباءً منبثّاً، فيومئذ قامت القيامة، وانشقّت السماء وتمزّقت، فهي يومئذ ضعيفة مسترخية، والملائكة على أطرافها، ويحمل عرش ربك فوقهم يومئذ ثمانية من الملائكة، أربعة هم حملة العرش دائماً وزيد عليهم أربعة. يومئذ تُعرضون على الله، لا تخفى منكم سريرة مما كنتم تخفونه.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان كيفية الانقلاب الكوني لنهاية الحياة الأولى.", "تقرير العرض على الله عز وجل للحساب ثم الجزاء."], "k": "«لا تخفى منكم خافية»… ما الذي أخفيه اليوم وأخاف أن يُعرض؟ فلأصلحه قبل العرض."}, {"lbl": "الآيات ١٩ – ٢٤", "q": "فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ ﴿١٩﴾ إِنِّي ظَنَنتُ أَنِّي مُلَٰقٍ حِسَابِيَهۡ ﴿٢٠﴾ فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ ﴿٢١﴾ فِي جَنَّةٍ عَالِيَةٖ ﴿٢٢﴾ قُطُوفُهَا دَانِيَةٞ ﴿٢٣﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَآ أَسۡلَفۡتُمۡ فِي ٱلۡأَيَّامِ ٱلۡخَالِيَةِ ﴿٢٤﴾", "w": [["هاؤم اقرؤوا كتابيه", "خذوا كتابي فاقرؤوه."], ["إني ظننت", "علمت."], ["أني ملاقٍ حسابيه", "أني ملاقٍ حسابي لا محالة."], ["في عيشة راضية", "يرضى بها صاحبها."], ["قطوفها دانية", "ما يُقتطف ويُجنى من ثمارها قريب التناول."], ["بما أسلفتم", "بما قدّمتم."], ["في الأيام الخالية", "الماضية."]], "m": "بعد مجيء الرب تبارك وتعالى لفصل القضاء تُعطى الكتب، فمن آخذ كتابه بيمينه، ومن آخذ كتابه بشماله؛ فأما من أوتي كتابه الذي ضمّ حسناته بيمينه فيقول في فرح عظيم: خذوا كتابي فاقرؤوه، إنه مشرق كله، ما فيه سواد السيئات، ويعلّل سلامة كتابه فيقول: إني علمت أني ملاقٍ حسابي لا محالة، فلذا لم أقارف السيئات، وإن قارفت شيئاً جهلاً تبت منه فوراً فانمحى أثره. قال تعالى: فهو في عيشة يرضاها لهناءتها وسعة خيراتها، في جنة عالية، ثمارها قريبة التناول ينالها بيده وهو متّكئ على أريكته، ويقال لهم: كلوا واشربوا هنيئاً بما قدّمتم لأنفسكم في أيام الدنيا الماضية، إذ كانوا مؤمنين صوّامين قوّامين آمرين بالمعروف ناهين عن المنكر.", "h": ["تقرير عقيدة البعث والجزاء، أي الإيمان باليوم الآخر.", "آثار الإيمان بالبعث والجزاء ظاهرة في سلامة كتاب المؤمن من السيئات، وقد علّل لذلك بقوله: إني ظننت أني ملاقٍ حسابيه، فلذا لم أعصِ ربي.", "إثبات حقيقة هي قول العامة: الدنيا مزرعة الآخرة، أي من عمل في الدنيا نال ثمار عمله في الآخرة خيراً أو شراً."], "k": "«إني ظننت أني ملاقٍ حسابيه»… اليقين بالحساب هو الذي بيّض كتابه؛ فكم في قلبي منه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (422, 69, 25, 52, 'سورة الحاقة ٢٥ – ٥٢', 'الحاقة: وإنه لتذكرة للمتقين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 422) = $j$[{"lbl": "الآيات ٢٥ – ٣٧", "q": "وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ ﴿٢٥﴾ وَلَمۡ أَدۡرِ مَا حِسَابِيَهۡ ﴿٢٦﴾ يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ ﴿٢٧﴾ مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ ﴿٢٨﴾ هَلَكَ عَنِّي سُلۡطَٰنِيَهۡ ﴿٢٩﴾ خُذُوهُ فَغُلُّوهُ ﴿٣٠﴾ ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ ﴿٣١﴾ ثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ ﴿٣٢﴾ إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ ﴿٣٣﴾ وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ﴿٣٤﴾ فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ ﴿٣٥﴾ وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ ﴿٣٦﴾ لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ ﴿٣٧﴾", "w": [["يا ليتني لم أوتَ كتابيه", "يتمنّى أنه لم يُعطَ كتابه لما رأى فيه من السيئات."], ["يا ليتها كانت القاضية", "ليت الموتة في الدنيا كانت القاطعة لحياتي حتى لا أُبعث."], ["هلك عني سلطانيه", "ذهبت قوتي وحجّتي."], ["خذوه", "أيها الزبانية خذوا هذا الكافر."], ["فغلّوه", "اجعلوا يديه إلى عنقه في الغلّ."], ["ثم الجحيم صلّوه", "ثم في النار المحرقة أدخلوه، وبالغوا في تصليته."], ["حميم", "قريب ينفعه، أو صديق."], ["إلا من غسلين", "صديد أهل النار."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء؛ تقدّم ذكر الذي أوتي كتابه بيمينه وما له من كرامة، وفي هذه الآيات ذكر الذي أوتي كتابه بشماله وما له من مهانة وعذاب جزاء كفره: فيقول بعد النظر فيه وما يلوح له من السيئات: يا ليتني لم أوتَ كتابيه، ولم أدرِ ما حسابيه، يا ليت الموتة التي متّها في الدنيا كانت القاطعة لحياتي حتى لا أُبعث. ثم يواصل تحسّره: ما أغنى عني مالي، ذهبت عني حججي فلم أجد ما أحتجّ به، والهاء في «كتابيه» و«حسابيه» و«ماليه» و«سلطانيه» هاء السكت. قال تعالى للزبانية: خذوه فشدّوا يديه إلى عنقه بالغلّ، ثم أدخلوه الجحيم، ثم في سلسلة طويلة ذرعها سبعون ذراعاً فأدخلوه فيها. وذكر علّة هذا الحكم: إنه كان في الدنيا لا يؤمن بالله العظيم، ولا يحضّ على طعام المسكين، فانحصرت جريمته في شيئين: الكفر بالله، ومنع الحقوق الواجبة في المال. فليس له اليوم في جهنم صديق أو قريب ينتفع به فيدفع عنه العذاب، وليس له طعام إلا من غسلين، صديد أهل النار، لا يأكله إلا الخاطئون الذين ارتكبوا خطيئة الكفر.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحداثها.", "المال الذي باع المفلسون فيه الأمة والملة لا يغني يوم القيامة عن صاحبه شيئاً.", "التنديد بالكفر بالله وأهله.", "عظم جريمة منع الحقوق المالية من الزكاة وغيرها."], "k": "«ولا يحضّ على طعام المسكين»… ليس فقط ألا أطعمه، بل ألا أحضّ غيري؛ فهل أدعو إلى إطعامه؟"}, {"lbl": "الآيات ٣٨ – ٥٢", "q": "فَلَآ أُقۡسِمُ بِمَا تُبۡصِرُونَ ﴿٣٨﴾ وَمَا لَا تُبۡصِرُونَ ﴿٣٩﴾ إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ﴿٤٠﴾ وَمَا هُوَ بِقَوۡلِ شَاعِرٖۚ قَلِيلٗا مَّا تُؤۡمِنُونَ ﴿٤١﴾ وَلَا بِقَوۡلِ كَاهِنٖۚ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٤٢﴾ تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٤٣﴾ وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ ﴿٤٤﴾ لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ ﴿٤٥﴾ ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ ﴿٤٦﴾ فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ ﴿٤٧﴾ وَإِنَّهُۥ لَتَذۡكِرَةٞ لِّلۡمُتَّقِينَ ﴿٤٨﴾ وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ ﴿٤٩﴾ وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَٰفِرِينَ ﴿٥٠﴾ وَإِنَّهُۥ لَحَقُّ ٱلۡيَقِينِ ﴿٥١﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٥٢﴾", "w": [["بما تبصرون وما لا تبصرون", "بكل مخلوق في الأرض وفي السماء."], ["إنه لقول رسول كريم", "القرآن، قاله تبليغاً رسول كريم هو محمد ﷺ."], ["وما هو بقول كاهن", "ليس القرآن بقول كاهن، إذ ليس فيه من سجع الكهّان شيء."], ["لأخذنا منه باليمين", "بالقوة، أو لأخذنا بيمينه."], ["ثم لقطعنا منه الوتين", "نياط القلب الذي إذا انقطع مات الإنسان."], ["حاجزين", "مانعين."], ["وإنه لحسرة على الكافرين", "التكذيب بالقرآن حسرة يوم القيامة على المكذّبين به."], ["وإنه لحق اليقين", "الثابت يقيناً، أو اليقين الحق."], ["فسبّح باسم ربك العظيم", "نزّه ربك العظيم الذي كل شيء أمام عظمته صغير، أي قل: سبحان ربي العظيم."]], "m": "فلا، ليس الأمر كما تقولون أيها المكذّبون، أقسم بما تبصرون وما لا تبصرون من المخلوقات في الأرض وفي السماوات، إن القرآن لقول رسول كريم على ربه، وهو محمد ﷺ، أي إنه تبليغه إليكم، وما هو بقول شاعر كما تقولون كذباً، قليلاً ما تؤمنون، فلو كان إيمانكم واسعاً لاتّسع للإيمان بالقرآن، وليس هو من جنس الشعر لمخالفته له نظماً ومعنى، ولا بقول كاهن، قليلاً ما تذكّرون، فلو تذكّرتم لعلمتم أن القرآن ليس بكلام الكهّان لملازمته للصدق والحق والهدى، بخلاف قول الكهان الذي سداه ولحمته الكذب، إنه تنزيل من رب العالمين. ولو تقوّل علينا محمد بعض الأقاويل ونسبها إلينا لبطشنا به وأخذنا بيمينه، ثم لقطعنا منه عرق القلب فيهلك، فمن منكم يحجزنا عنه؟ وإن القرآن لموعظة عظيمة للمتقين الذين يخافون عقاب الله، وإنا لنعلم أن منكم مكذّبين، وسنجزيهم وصفهم، وإنه لحسرة على الكافرين يوم القيامة عندما يرون المؤمنين به يؤخذ بهم إلى دار السلام والمكذّبين إلى دار البوار، وإنه لحق اليقين. ثم أمر رسوله أن يستعين على الصبر بذكر الله: فسبّح باسم ربك العظيم، قل: سبحان ربي العظيم، معظّماً ربك غاية التعظيم.", "h": ["لله تعالى أن يحلف بما شاء من مخلوقاته لحكم عالية، وليس للعبد أن يحلف بغير الرب.", "تقرير الوحي، وإثبات النبوة المحمدية.", "وصف الرسول ﷺ بالكرم وبكرامته على ربه تعالى.", "عجز الرسول ﷺ عن الكذب على الله تعالى، ولكن الذي لا يكذب على الناس لا يكذب على الله، كما قال هرقل: ما كان ليدع الكذب على الناس ويكذب على الله، ردّاً على أبي سفيان لما قال: لم نجرّب عليه كذباً قط.", "مشروعية التسبيح بقول: سبحان ربي العظيم؛ إذ صحّ أنه لما نزلت قال النبي ﷺ لأصحابه: «اجعلوها في ركوعكم»، فكانت سنة مؤكدة: سبحان ربي العظيم ثلاثاً في الركوع أو أكثر."], "k": "«وإنه لتذكرة للمتقين»… هل يذكّرني القرآن فعلاً، أم أقرؤه دون أن أتذكّر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 422;
insert into public.tdb_cards(topic, i, body) select 422, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٥ – ٣٧", "q": "وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ ﴿٢٥﴾ وَلَمۡ أَدۡرِ مَا حِسَابِيَهۡ ﴿٢٦﴾ يَٰلَيۡتَهَا كَانَتِ ٱلۡقَاضِيَةَ ﴿٢٧﴾ مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ ﴿٢٨﴾ هَلَكَ عَنِّي سُلۡطَٰنِيَهۡ ﴿٢٩﴾ خُذُوهُ فَغُلُّوهُ ﴿٣٠﴾ ثُمَّ ٱلۡجَحِيمَ صَلُّوهُ ﴿٣١﴾ ثُمَّ فِي سِلۡسِلَةٖ ذَرۡعُهَا سَبۡعُونَ ذِرَاعٗا فَٱسۡلُكُوهُ ﴿٣٢﴾ إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ ﴿٣٣﴾ وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ﴿٣٤﴾ فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ ﴿٣٥﴾ وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِينٖ ﴿٣٦﴾ لَّا يَأۡكُلُهُۥٓ إِلَّا ٱلۡخَٰطِـُٔونَ ﴿٣٧﴾", "w": [["يا ليتني لم أوتَ كتابيه", "يتمنّى أنه لم يُعطَ كتابه لما رأى فيه من السيئات."], ["يا ليتها كانت القاضية", "ليت الموتة في الدنيا كانت القاطعة لحياتي حتى لا أُبعث."], ["هلك عني سلطانيه", "ذهبت قوتي وحجّتي."], ["خذوه", "أيها الزبانية خذوا هذا الكافر."], ["فغلّوه", "اجعلوا يديه إلى عنقه في الغلّ."], ["ثم الجحيم صلّوه", "ثم في النار المحرقة أدخلوه، وبالغوا في تصليته."], ["حميم", "قريب ينفعه، أو صديق."], ["إلا من غسلين", "صديد أهل النار."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء؛ تقدّم ذكر الذي أوتي كتابه بيمينه وما له من كرامة، وفي هذه الآيات ذكر الذي أوتي كتابه بشماله وما له من مهانة وعذاب جزاء كفره: فيقول بعد النظر فيه وما يلوح له من السيئات: يا ليتني لم أوتَ كتابيه، ولم أدرِ ما حسابيه، يا ليت الموتة التي متّها في الدنيا كانت القاطعة لحياتي حتى لا أُبعث. ثم يواصل تحسّره: ما أغنى عني مالي، ذهبت عني حججي فلم أجد ما أحتجّ به، والهاء في «كتابيه» و«حسابيه» و«ماليه» و«سلطانيه» هاء السكت. قال تعالى للزبانية: خذوه فشدّوا يديه إلى عنقه بالغلّ، ثم أدخلوه الجحيم، ثم في سلسلة طويلة ذرعها سبعون ذراعاً فأدخلوه فيها. وذكر علّة هذا الحكم: إنه كان في الدنيا لا يؤمن بالله العظيم، ولا يحضّ على طعام المسكين، فانحصرت جريمته في شيئين: الكفر بالله، ومنع الحقوق الواجبة في المال. فليس له اليوم في جهنم صديق أو قريب ينتفع به فيدفع عنه العذاب، وليس له طعام إلا من غسلين، صديد أهل النار، لا يأكله إلا الخاطئون الذين ارتكبوا خطيئة الكفر.", "h": ["تقرير عقيدة البعث والجزاء بذكر أحداثها.", "المال الذي باع المفلسون فيه الأمة والملة لا يغني يوم القيامة عن صاحبه شيئاً.", "التنديد بالكفر بالله وأهله.", "عظم جريمة منع الحقوق المالية من الزكاة وغيرها."], "k": "«ولا يحضّ على طعام المسكين»… ليس فقط ألا أطعمه، بل ألا أحضّ غيري؛ فهل أدعو إلى إطعامه؟"}, {"lbl": "الآيات ٣٨ – ٥٢", "q": "فَلَآ أُقۡسِمُ بِمَا تُبۡصِرُونَ ﴿٣٨﴾ وَمَا لَا تُبۡصِرُونَ ﴿٣٩﴾ إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ﴿٤٠﴾ وَمَا هُوَ بِقَوۡلِ شَاعِرٖۚ قَلِيلٗا مَّا تُؤۡمِنُونَ ﴿٤١﴾ وَلَا بِقَوۡلِ كَاهِنٖۚ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٤٢﴾ تَنزِيلٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٤٣﴾ وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ ٱلۡأَقَاوِيلِ ﴿٤٤﴾ لَأَخَذۡنَا مِنۡهُ بِٱلۡيَمِينِ ﴿٤٥﴾ ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِينَ ﴿٤٦﴾ فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَٰجِزِينَ ﴿٤٧﴾ وَإِنَّهُۥ لَتَذۡكِرَةٞ لِّلۡمُتَّقِينَ ﴿٤٨﴾ وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ ﴿٤٩﴾ وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَٰفِرِينَ ﴿٥٠﴾ وَإِنَّهُۥ لَحَقُّ ٱلۡيَقِينِ ﴿٥١﴾ فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ ﴿٥٢﴾", "w": [["بما تبصرون وما لا تبصرون", "بكل مخلوق في الأرض وفي السماء."], ["إنه لقول رسول كريم", "القرآن، قاله تبليغاً رسول كريم هو محمد ﷺ."], ["وما هو بقول كاهن", "ليس القرآن بقول كاهن، إذ ليس فيه من سجع الكهّان شيء."], ["لأخذنا منه باليمين", "بالقوة، أو لأخذنا بيمينه."], ["ثم لقطعنا منه الوتين", "نياط القلب الذي إذا انقطع مات الإنسان."], ["حاجزين", "مانعين."], ["وإنه لحسرة على الكافرين", "التكذيب بالقرآن حسرة يوم القيامة على المكذّبين به."], ["وإنه لحق اليقين", "الثابت يقيناً، أو اليقين الحق."], ["فسبّح باسم ربك العظيم", "نزّه ربك العظيم الذي كل شيء أمام عظمته صغير، أي قل: سبحان ربي العظيم."]], "m": "فلا، ليس الأمر كما تقولون أيها المكذّبون، أقسم بما تبصرون وما لا تبصرون من المخلوقات في الأرض وفي السماوات، إن القرآن لقول رسول كريم على ربه، وهو محمد ﷺ، أي إنه تبليغه إليكم، وما هو بقول شاعر كما تقولون كذباً، قليلاً ما تؤمنون، فلو كان إيمانكم واسعاً لاتّسع للإيمان بالقرآن، وليس هو من جنس الشعر لمخالفته له نظماً ومعنى، ولا بقول كاهن، قليلاً ما تذكّرون، فلو تذكّرتم لعلمتم أن القرآن ليس بكلام الكهّان لملازمته للصدق والحق والهدى، بخلاف قول الكهان الذي سداه ولحمته الكذب، إنه تنزيل من رب العالمين. ولو تقوّل علينا محمد بعض الأقاويل ونسبها إلينا لبطشنا به وأخذنا بيمينه، ثم لقطعنا منه عرق القلب فيهلك، فمن منكم يحجزنا عنه؟ وإن القرآن لموعظة عظيمة للمتقين الذين يخافون عقاب الله، وإنا لنعلم أن منكم مكذّبين، وسنجزيهم وصفهم، وإنه لحسرة على الكافرين يوم القيامة عندما يرون المؤمنين به يؤخذ بهم إلى دار السلام والمكذّبين إلى دار البوار، وإنه لحق اليقين. ثم أمر رسوله أن يستعين على الصبر بذكر الله: فسبّح باسم ربك العظيم، قل: سبحان ربي العظيم، معظّماً ربك غاية التعظيم.", "h": ["لله تعالى أن يحلف بما شاء من مخلوقاته لحكم عالية، وليس للعبد أن يحلف بغير الرب.", "تقرير الوحي، وإثبات النبوة المحمدية.", "وصف الرسول ﷺ بالكرم وبكرامته على ربه تعالى.", "عجز الرسول ﷺ عن الكذب على الله تعالى، ولكن الذي لا يكذب على الناس لا يكذب على الله، كما قال هرقل: ما كان ليدع الكذب على الناس ويكذب على الله، ردّاً على أبي سفيان لما قال: لم نجرّب عليه كذباً قط.", "مشروعية التسبيح بقول: سبحان ربي العظيم؛ إذ صحّ أنه لما نزلت قال النبي ﷺ لأصحابه: «اجعلوها في ركوعكم»، فكانت سنة مؤكدة: سبحان ربي العظيم ثلاثاً في الركوع أو أكثر."], "k": "«وإنه لتذكرة للمتقين»… هل يذكّرني القرآن فعلاً، أم أقرؤه دون أن أتذكّر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (423, 70, 1, 44, 'سورة المعارج ١ – ٤٤', 'المعارج: إن الإنسان خُلق هلوعاً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 423) = $j$[{"lbl": "الآيات ١ – ١٨", "q": "سَأَلَ سَآئِلُۢ بِعَذَابٖ وَاقِعٖ ﴿١﴾ لِّلۡكَٰفِرِينَ لَيۡسَ لَهُۥ دَافِعٞ ﴿٢﴾ مِّنَ ٱللَّهِ ذِي ٱلۡمَعَارِجِ ﴿٣﴾ تَعۡرُجُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥ خَمۡسِينَ أَلۡفَ سَنَةٖ ﴿٤﴾ فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا ﴿٥﴾ إِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدٗا ﴿٦﴾ وَنَرَىٰهُ قَرِيبٗا ﴿٧﴾ يَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ ﴿٨﴾ وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ﴿٩﴾ وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمٗا ﴿١٠﴾ يُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۭ بِبَنِيهِ ﴿١١﴾ وَصَٰحِبَتِهِۦ وَأَخِيهِ ﴿١٢﴾ وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ ﴿١٣﴾ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ يُنجِيهِ ﴿١٤﴾ كَلَّآۖ إِنَّهَا لَظَىٰ ﴿١٥﴾ نَزَّاعَةٗ لِّلشَّوَىٰ ﴿١٦﴾ تَدۡعُواْ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ ﴿١٧﴾ وَجَمَعَ فَأَوۡعَىٰٓ ﴿١٨﴾", "w": [["سأل سائل بعذاب واقع", "دعا داعٍ بعذاب واقع."], ["ليس له دافع", "من الله، فهو واقع لا محالة."], ["ذي المعارج", "ذي العلو والدرجات ومصاعد الملائكة، وهي السماوات."], ["تعرج الملائكة والروح إليه", "تصعد الملائكة وجبريل إلى الله تعالى."], ["في يوم كان مقداره خمسين ألف سنة", "من منتهى أمره من أسفل الأرض السابعة إلى منتهى أمره فوق السماوات السبع، في يوم مقداره خمسون ألف سنة بالنسبة لصعود غير الملائكة."], ["إنهم يرونه بعيداً", "العذاب الذي يطالبون به لتكذيبهم بالبعث."], ["يوم تكون السماء كالمُهل", "كذائب النحاس."], ["وتكون الجبال كالعِهن", "كالصوف المصبوغ ألواناً في الخفة والطيران بالريح."], ["ولا يسأل حميم حميماً", "لا يسأل قريب قريبه لانشغال كلٍّ بحاله."], ["يُبصّرونهم", "يبصر الأقرباء بعضهم بعضاً ويتعارفون ولا يتكلمون."], ["وصاحبته", "زوجته."], ["وفصيلته التي تؤويه", "عشيرته التي تضمّه إليها نسباً وتحميه من الأذى."], ["إنها لظى نزّاعة للشوى", "إن جهنم هي لظى، نزّاعة لجلدة الرأس وأطراف البدن."], ["من أدبر وتولّى", "أدبر عن طاعة الله ورسوله، وتولّى عن الإيمان فأنكره."], ["وجمع فأوعى", "جمع المال وجعله في وعاء، ومنع حق الله فيه."]], "m": "نزلت هذه الآيات ردّاً على دعاء النضر بن الحارث ومن وافقه: اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم، فأخبر تعالى: سأل سائل بعذاب واقع للكافرين، ليس له من الله دافع، فهو واقع لا محالة، من الله ذي المعارج صاحب العلو ومصاعد الملائكة، تصعد الملائكة وجبريل إليه في يوم مقداره خمسون ألف سنة. فاصبر يا رسولنا صبراً جميلاً، إنهم يرون العذاب بعيداً لتكذيبهم بالبعث، ونراه قريباً. ثم بيّن وقت مجيئه: يوم تذوب السماء فتصير كذائب النحاس، وتكون الجبال كالصوف المصبوغ خفة وطيراناً بالريح، وهذا هو الانقلاب الكوني، ثم يعيد الله الخلق فإذا الناس في عرصات القيامة حفاة عراة، لا يسأل قريب قريبه لانشغال كلٍّ بنفسه، لا عن عدم معرفة، بل يُبصّرهم بهم فيعرف كل قريب قريبه، ولكن اشتغاله بنفسه يحول دون سؤاله، يودّ المجرم لو يفتدي من عذاب يومئذ ببنيه وزوجته وأخيه وعشيرته التي تؤويه ومن في الأرض جميعاً ثم ينجيه؛ فلنتصوّر عذاباً يودّ المجرم أن يفتدي منه بكل شيء، كيف يكون؟ كلا، لا قرابة تنفع ولا فداء يُقبل، إنها لظى، نزّاعة لجلدة الرأس ولكل عضو، تنادي: إليّ إليّ يا من أدبر عن طاعة الله ورسوله فلم يلتفت إليها، وتولّى عن الإيمان، وجمع الأموال فأوعاها ولم يؤدِّ الحقوق الواجبة فيها، إذ في المال حق غير الزكاة.", "h": ["حرمة سؤال العذاب، فإن عذاب الله لا يُطاق، ولكن تُسأل الرحمة والعافية.", "وجوب الصبر على الطاعة وعلى البلاء، فلا تسخّط ولا جزع.", "تقرير عقيدة البعث والجزاء.", "عظم هول الموقف يوم القيامة وصعوبة الحال.", "التنديد بالمعرضين عن طاعة الله ورسوله، الجامعين للأموال المشتغلين بها حتى سلبتهم الإيمان فأصبحوا يشكّون في الله وآياته ولقائه."], "k": "«يودّ المجرم لو يفتدي… ببنيه»… من أحبّهم اليوم قد يكون فداءً يومها؛ فلأعمل لنفسي الآن."}, {"lbl": "الآيات ١٩ – ٣٥", "q": "۞إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا ﴿١٩﴾ إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا ﴿٢٠﴾ وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا ﴿٢١﴾ إِلَّا ٱلۡمُصَلِّينَ ﴿٢٢﴾ ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ ﴿٢٣﴾ وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ ﴿٢٤﴾ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ ﴿٢٥﴾ وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ ﴿٢٦﴾ وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ ﴿٢٧﴾ إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونٖ ﴿٢٨﴾ وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ ﴿٢٩﴾ إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ ﴿٣٠﴾ فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ ﴿٣١﴾ وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ ﴿٣٢﴾ وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ ﴿٣٣﴾ وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ﴿٣٤﴾ أُوْلَـٰٓئِكَ فِي جَنَّـٰتٖ مُّكۡرَمُونَ ﴿٣٥﴾", "w": [["إن الإنسان خُلق هلوعاً", "إذا مسّه الشر جزوعاً، وإذا مسّه الخير منوعاً، أي كثير الجزع سريعه، وكثير المنع حريصاً."], ["على صلاتهم دائمون", "لا يقطعونها أبداً ما داموا أحياء يعقلون."], ["حق معلوم", "نصيب معيّن عيّنه الشارع، وهو الزكاة."], ["للسائل والمحروم", "الطالب للصدقة، والذي لا يطلبها حياءً وتعفّفاً."], ["يصدّقون بيوم الدين", "يؤمنون بيوم القيامة للبعث والجزاء."], ["مشفقون", "خائفون، متوقّعون العذاب عند المعصية."], ["لفروجهم حافظون", "صائنون لها عن النظر إليها وعن الفاحشة."], ["أو ما ملكت أيمانهم", "من السراري من الجواري التي يملكونها."], ["فأولئك هم العادون", "المعتدون الظالمون المتجاوزون الحلال إلى الحرام."], ["لأماناتهم", "ما اؤتمنوا عليه من أمور الدين والدنيا."], ["راعون", "حافظون غير مفرّطين."], ["بشهاداتهم قائمون", "يقيمون شهاداتهم، لا يكتمونها ولا يحرّفونها."], ["على صلاتهم يحافظون", "يؤدّونها في أوقاتها في جماعات مع كامل الشروط والأركان والواجبات والسنن."]], "m": "إن هذا الإنسان خُلق هلوعاً، قابلاً لوصف الهلع فيه عند بلوغه سن التمييز، والهلع مرض نفسي عرضه جزعه الشديد متى مسّه الشر، ومنعه القوي للخير متى ظفر به. ثم ذكر تعالى ما يُعالج به هذا المرض، باستثنائه من يتّصفون بصفات هي عبادات شرعية من شأنها القضاء عليه: الأولى: إدامة الصلاة بالمواظبة عليها ليلاً ونهاراً، إيماناً واحتساباً وأداءً صحيحاً. الثانية: الاعتراف بما أوجب الله في المال من حق، وإعطاؤه بطيب نفس لمن سأل ولمن لم يسأل. الثالثة: التصديق الكامل بيوم الدين. الرابعة: الإشفاق من عذاب الله عند عروض خاطر المعصية، لأن عذاب ربهم غير مأمون. الخامسة: حفظ الفرج بستره عن أعين الناس ما عدا الزوج، وصيانته من فاحشة الزنا واللواط والاستمناء باليد المعروف اليوم بالعادة السرية، إلا على أزواجهم أو ما ملكت أيمانهم، فمن طلب ما وراء ذلك فأولئك هم المعتدون. السادسة: حفظ الأمانات والعهود، ومن أبرزها ما التزم به العبد من عبادة الله وطاعته وطاعة رسوله، زيادة على أمانات الناس وعهودهم. السابعة: إقامة الشهادة بالاعتدال فيها، فيؤدّيها ولا يكتمها. الثامنة: المحافظة على الصلوات الخمس مستوفاة الشروط والأركان، من الخشوع إلى الطمأنينة في الركوع والسجود. فهذه الوصفة الربانية متى استعملها المؤمن، تحت إشراف عالم رباني إن وجده، وإلا فتطبيقها بدون إشراف ينفع بإذن الله، برئ من ذلك المرض الخطير، وأصبح أهلاً لإكرام الله في الآخرة: أولئك في جنات مكرمون في جوار ربهم.", "h": ["بيان شر صفات الإنسان، وأنها الهلع.", "بيان الدواء لداء الهلع الذي لا فلاح معه ولا نجاح.", "انحصار العلاج في ثماني صفات، أو ثماني مركّبات دوائية.", "وجوب العمل بما اشتملت عليه الوصفة من واجبات.", "حرمة ما اشتملت عليه الوصفة من محرّمات."], "k": "«إذا مسّه الشر جزوعاً وإذا مسّه الخير منوعاً»… أعرف نفسي في هذين؛ فأي دواء من الثمانية أحتاجه أكثر؟"}, {"lbl": "الآيات ٣٦ – ٤٤", "q": "فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ ﴿٣٦﴾ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ ﴿٣٧﴾ أَيَطۡمَعُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُدۡخَلَ جَنَّةَ نَعِيمٖ ﴿٣٨﴾ كَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ ﴿٣٩﴾ فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ ﴿٤٠﴾ عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرٗا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِينَ ﴿٤١﴾ فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ ﴿٤٢﴾ يَوۡمَ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعٗا كَأَنَّهُمۡ إِلَىٰ نُصُبٖ يُوفِضُونَ ﴿٤٣﴾ خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ ﴿٤٤﴾", "w": [["قِبَلك مهطعين", "نحوك، مديمي النظر إليك."], ["عزين", "جماعات حِلَقاً حِلَقاً، يقولون استهزاءً بالمؤمنين: لئن دخل هؤلاء الجنة لندخلنّها قبلهم."], ["إنا خلقناهم مما يعلمون", "من منيّ قذر، وإنما يُستوجب دخول الجنة بالطاعات المزكّية للنفس."], ["على أن نبدّل خيراً منهم", "إنا لقادرون على أن نهلكهم ونأتي بأناس خير منهم."], ["وما نحن بمسبوقين", "بعاجزين عن ذلك."], ["يوم يخرجون من الأجداث سراعاً", "من القبور، مسرعين إلى المحشر."], ["كأنهم إلى نُصُب يوفضون", "كأنهم في إسراعهم إلى شيء منصوب، كراية أو علم، يسرعون."], ["ترهقهم ذلّة", "تغشاهم ذلّة."], ["ذلك اليوم الذي كانوا يوعدون", "يوعدون بالعذاب فيه، وهو يوم القيامة."]], "m": "فما للذين كفروا من كفار مكة نحوك حيث كنت في المسجد الحرام مسرعين مديمي النظر إليك، عن يمينك وعن شمالك جماعات، حِلَقاً يستمعون إلى قراءتك بحثاً عن كلمة يشنّعون بها عليك، ويقولون استهزاءً بالمؤمنين: لئن دخل هؤلاء الجنة لندخلنّها قبلهم. فردّ تعالى عليهم: أيطمع كل امرئ منهم أن يدخل جنة نعيم؟ كلا، لن يكون ذلك وهم أنجاس الأرواح بالشرك والمعاصي، ولفت النظر إلى أصل الخلقة، المنيّ القذر، والقذر لا يدخل دار السلام، فمن أراد الجنة فليزكِّ نفسه بالإيمان والعمل الصالح. فلا، ليس الأمر كما يتصوّرون من أنهم لا يُبعثون، أقسم برب المشارق والمغارب، حيث الشمس تطلع كل يوم في مطلع وتغرب في آخر، إنا لقادرون على أن نهلكهم ونأتي بخير منهم، وما نحن بعاجزين عن ذلك، فكيف لا نعيدهم أحياء يوم القيامة؟ فذرهم يخوضوا في الباطل ويلعبوا حتى يلاقوا يومهم الذي يوعدون، وهو تهديد لهم: يوم يخرجون من القبور مسرعين كأنهم إلى شيء منصوب يسرعون، خاشعة أبصارهم ذليلة من الفزع، تغشاهم ذلّة عظيمة، ذلك اليوم الذي كانوا يوعدون بالعذاب فيه، وهو يوم القيامة الذي أنكروه وكذّبوا به.", "h": ["بيان الحال التي كان عليها الرسول ﷺ في مكة بين ظهراني قريش، وما كان يلاقي من أذاهم.", "بيان أن الجنة تُدخل بالطهارة الروحية من قذر الشرك والمعاصي، وإلا فأصل الناس واحد، المنيّ، باستثناء آدم وحواء وعيسى؛ فآدم أصله الطين، وحواء خُلقت من ضلع آدم، وعيسى كان بنفخ روح القدس في كُمّ درع مريم فكان بكلمة الله تعالى.", "الاستدلال بالنشأة الأولى على إمكان الثانية.", "تقرير عقيدة البعث والجزاء.", "بيان أن حياة أهل الكفر، مهما تراءى لهم ولغيرهم أنها حياة مدنية سعيدة، لم تعدُ كونها باطلاً ولهواً."], "k": "«أيطمع كل امرئ منهم أن يدخل جنة نعيم»… الطمع بلا عمل غرور؛ فهل عملي على قدر طمعي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 423;
insert into public.tdb_cards(topic, i, body) select 423, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٨", "q": "سَأَلَ سَآئِلُۢ بِعَذَابٖ وَاقِعٖ ﴿١﴾ لِّلۡكَٰفِرِينَ لَيۡسَ لَهُۥ دَافِعٞ ﴿٢﴾ مِّنَ ٱللَّهِ ذِي ٱلۡمَعَارِجِ ﴿٣﴾ تَعۡرُجُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيۡهِ فِي يَوۡمٖ كَانَ مِقۡدَارُهُۥ خَمۡسِينَ أَلۡفَ سَنَةٖ ﴿٤﴾ فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا ﴿٥﴾ إِنَّهُمۡ يَرَوۡنَهُۥ بَعِيدٗا ﴿٦﴾ وَنَرَىٰهُ قَرِيبٗا ﴿٧﴾ يَوۡمَ تَكُونُ ٱلسَّمَآءُ كَٱلۡمُهۡلِ ﴿٨﴾ وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ﴿٩﴾ وَلَا يَسۡـَٔلُ حَمِيمٌ حَمِيمٗا ﴿١٠﴾ يُبَصَّرُونَهُمۡۚ يَوَدُّ ٱلۡمُجۡرِمُ لَوۡ يَفۡتَدِي مِنۡ عَذَابِ يَوۡمِئِذِۭ بِبَنِيهِ ﴿١١﴾ وَصَٰحِبَتِهِۦ وَأَخِيهِ ﴿١٢﴾ وَفَصِيلَتِهِ ٱلَّتِي تُـٔۡوِيهِ ﴿١٣﴾ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ يُنجِيهِ ﴿١٤﴾ كَلَّآۖ إِنَّهَا لَظَىٰ ﴿١٥﴾ نَزَّاعَةٗ لِّلشَّوَىٰ ﴿١٦﴾ تَدۡعُواْ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ ﴿١٧﴾ وَجَمَعَ فَأَوۡعَىٰٓ ﴿١٨﴾", "w": [["سأل سائل بعذاب واقع", "دعا داعٍ بعذاب واقع."], ["ليس له دافع", "من الله، فهو واقع لا محالة."], ["ذي المعارج", "ذي العلو والدرجات ومصاعد الملائكة، وهي السماوات."], ["تعرج الملائكة والروح إليه", "تصعد الملائكة وجبريل إلى الله تعالى."], ["في يوم كان مقداره خمسين ألف سنة", "من منتهى أمره من أسفل الأرض السابعة إلى منتهى أمره فوق السماوات السبع، في يوم مقداره خمسون ألف سنة بالنسبة لصعود غير الملائكة."], ["إنهم يرونه بعيداً", "العذاب الذي يطالبون به لتكذيبهم بالبعث."], ["يوم تكون السماء كالمُهل", "كذائب النحاس."], ["وتكون الجبال كالعِهن", "كالصوف المصبوغ ألواناً في الخفة والطيران بالريح."], ["ولا يسأل حميم حميماً", "لا يسأل قريب قريبه لانشغال كلٍّ بحاله."], ["يُبصّرونهم", "يبصر الأقرباء بعضهم بعضاً ويتعارفون ولا يتكلمون."], ["وصاحبته", "زوجته."], ["وفصيلته التي تؤويه", "عشيرته التي تضمّه إليها نسباً وتحميه من الأذى."], ["إنها لظى نزّاعة للشوى", "إن جهنم هي لظى، نزّاعة لجلدة الرأس وأطراف البدن."], ["من أدبر وتولّى", "أدبر عن طاعة الله ورسوله، وتولّى عن الإيمان فأنكره."], ["وجمع فأوعى", "جمع المال وجعله في وعاء، ومنع حق الله فيه."]], "m": "نزلت هذه الآيات ردّاً على دعاء النضر بن الحارث ومن وافقه: اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم، فأخبر تعالى: سأل سائل بعذاب واقع للكافرين، ليس له من الله دافع، فهو واقع لا محالة، من الله ذي المعارج صاحب العلو ومصاعد الملائكة، تصعد الملائكة وجبريل إليه في يوم مقداره خمسون ألف سنة. فاصبر يا رسولنا صبراً جميلاً، إنهم يرون العذاب بعيداً لتكذيبهم بالبعث، ونراه قريباً. ثم بيّن وقت مجيئه: يوم تذوب السماء فتصير كذائب النحاس، وتكون الجبال كالصوف المصبوغ خفة وطيراناً بالريح، وهذا هو الانقلاب الكوني، ثم يعيد الله الخلق فإذا الناس في عرصات القيامة حفاة عراة، لا يسأل قريب قريبه لانشغال كلٍّ بنفسه، لا عن عدم معرفة، بل يُبصّرهم بهم فيعرف كل قريب قريبه، ولكن اشتغاله بنفسه يحول دون سؤاله، يودّ المجرم لو يفتدي من عذاب يومئذ ببنيه وزوجته وأخيه وعشيرته التي تؤويه ومن في الأرض جميعاً ثم ينجيه؛ فلنتصوّر عذاباً يودّ المجرم أن يفتدي منه بكل شيء، كيف يكون؟ كلا، لا قرابة تنفع ولا فداء يُقبل، إنها لظى، نزّاعة لجلدة الرأس ولكل عضو، تنادي: إليّ إليّ يا من أدبر عن طاعة الله ورسوله فلم يلتفت إليها، وتولّى عن الإيمان، وجمع الأموال فأوعاها ولم يؤدِّ الحقوق الواجبة فيها، إذ في المال حق غير الزكاة.", "h": ["حرمة سؤال العذاب، فإن عذاب الله لا يُطاق، ولكن تُسأل الرحمة والعافية.", "وجوب الصبر على الطاعة وعلى البلاء، فلا تسخّط ولا جزع.", "تقرير عقيدة البعث والجزاء.", "عظم هول الموقف يوم القيامة وصعوبة الحال.", "التنديد بالمعرضين عن طاعة الله ورسوله، الجامعين للأموال المشتغلين بها حتى سلبتهم الإيمان فأصبحوا يشكّون في الله وآياته ولقائه."], "k": "«يودّ المجرم لو يفتدي… ببنيه»… من أحبّهم اليوم قد يكون فداءً يومها؛ فلأعمل لنفسي الآن."}, {"lbl": "الآيات ١٩ – ٣٥", "q": "۞إِنَّ ٱلۡإِنسَٰنَ خُلِقَ هَلُوعًا ﴿١٩﴾ إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعٗا ﴿٢٠﴾ وَإِذَا مَسَّهُ ٱلۡخَيۡرُ مَنُوعًا ﴿٢١﴾ إِلَّا ٱلۡمُصَلِّينَ ﴿٢٢﴾ ٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَآئِمُونَ ﴿٢٣﴾ وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ ﴿٢٤﴾ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ ﴿٢٥﴾ وَٱلَّذِينَ يُصَدِّقُونَ بِيَوۡمِ ٱلدِّينِ ﴿٢٦﴾ وَٱلَّذِينَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ ﴿٢٧﴾ إِنَّ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡمُونٖ ﴿٢٨﴾ وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ ﴿٢٩﴾ إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ ﴿٣٠﴾ فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡعَادُونَ ﴿٣١﴾ وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ ﴿٣٢﴾ وَٱلَّذِينَ هُم بِشَهَٰدَٰتِهِمۡ قَآئِمُونَ ﴿٣٣﴾ وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظُونَ ﴿٣٤﴾ أُوْلَـٰٓئِكَ فِي جَنَّـٰتٖ مُّكۡرَمُونَ ﴿٣٥﴾", "w": [["إن الإنسان خُلق هلوعاً", "إذا مسّه الشر جزوعاً، وإذا مسّه الخير منوعاً، أي كثير الجزع سريعه، وكثير المنع حريصاً."], ["على صلاتهم دائمون", "لا يقطعونها أبداً ما داموا أحياء يعقلون."], ["حق معلوم", "نصيب معيّن عيّنه الشارع، وهو الزكاة."], ["للسائل والمحروم", "الطالب للصدقة، والذي لا يطلبها حياءً وتعفّفاً."], ["يصدّقون بيوم الدين", "يؤمنون بيوم القيامة للبعث والجزاء."], ["مشفقون", "خائفون، متوقّعون العذاب عند المعصية."], ["لفروجهم حافظون", "صائنون لها عن النظر إليها وعن الفاحشة."], ["أو ما ملكت أيمانهم", "من السراري من الجواري التي يملكونها."], ["فأولئك هم العادون", "المعتدون الظالمون المتجاوزون الحلال إلى الحرام."], ["لأماناتهم", "ما اؤتمنوا عليه من أمور الدين والدنيا."], ["راعون", "حافظون غير مفرّطين."], ["بشهاداتهم قائمون", "يقيمون شهاداتهم، لا يكتمونها ولا يحرّفونها."], ["على صلاتهم يحافظون", "يؤدّونها في أوقاتها في جماعات مع كامل الشروط والأركان والواجبات والسنن."]], "m": "إن هذا الإنسان خُلق هلوعاً، قابلاً لوصف الهلع فيه عند بلوغه سن التمييز، والهلع مرض نفسي عرضه جزعه الشديد متى مسّه الشر، ومنعه القوي للخير متى ظفر به. ثم ذكر تعالى ما يُعالج به هذا المرض، باستثنائه من يتّصفون بصفات هي عبادات شرعية من شأنها القضاء عليه: الأولى: إدامة الصلاة بالمواظبة عليها ليلاً ونهاراً، إيماناً واحتساباً وأداءً صحيحاً. الثانية: الاعتراف بما أوجب الله في المال من حق، وإعطاؤه بطيب نفس لمن سأل ولمن لم يسأل. الثالثة: التصديق الكامل بيوم الدين. الرابعة: الإشفاق من عذاب الله عند عروض خاطر المعصية، لأن عذاب ربهم غير مأمون. الخامسة: حفظ الفرج بستره عن أعين الناس ما عدا الزوج، وصيانته من فاحشة الزنا واللواط والاستمناء باليد المعروف اليوم بالعادة السرية، إلا على أزواجهم أو ما ملكت أيمانهم، فمن طلب ما وراء ذلك فأولئك هم المعتدون. السادسة: حفظ الأمانات والعهود، ومن أبرزها ما التزم به العبد من عبادة الله وطاعته وطاعة رسوله، زيادة على أمانات الناس وعهودهم. السابعة: إقامة الشهادة بالاعتدال فيها، فيؤدّيها ولا يكتمها. الثامنة: المحافظة على الصلوات الخمس مستوفاة الشروط والأركان، من الخشوع إلى الطمأنينة في الركوع والسجود. فهذه الوصفة الربانية متى استعملها المؤمن، تحت إشراف عالم رباني إن وجده، وإلا فتطبيقها بدون إشراف ينفع بإذن الله، برئ من ذلك المرض الخطير، وأصبح أهلاً لإكرام الله في الآخرة: أولئك في جنات مكرمون في جوار ربهم.", "h": ["بيان شر صفات الإنسان، وأنها الهلع.", "بيان الدواء لداء الهلع الذي لا فلاح معه ولا نجاح.", "انحصار العلاج في ثماني صفات، أو ثماني مركّبات دوائية.", "وجوب العمل بما اشتملت عليه الوصفة من واجبات.", "حرمة ما اشتملت عليه الوصفة من محرّمات."], "k": "«إذا مسّه الشر جزوعاً وإذا مسّه الخير منوعاً»… أعرف نفسي في هذين؛ فأي دواء من الثمانية أحتاجه أكثر؟"}, {"lbl": "الآيات ٣٦ – ٤٤", "q": "فَمَالِ ٱلَّذِينَ كَفَرُواْ قِبَلَكَ مُهۡطِعِينَ ﴿٣٦﴾ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ ﴿٣٧﴾ أَيَطۡمَعُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُدۡخَلَ جَنَّةَ نَعِيمٖ ﴿٣٨﴾ كَلَّآۖ إِنَّا خَلَقۡنَٰهُم مِّمَّا يَعۡلَمُونَ ﴿٣٩﴾ فَلَآ أُقۡسِمُ بِرَبِّ ٱلۡمَشَٰرِقِ وَٱلۡمَغَٰرِبِ إِنَّا لَقَٰدِرُونَ ﴿٤٠﴾ عَلَىٰٓ أَن نُّبَدِّلَ خَيۡرٗا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِينَ ﴿٤١﴾ فَذَرۡهُمۡ يَخُوضُواْ وَيَلۡعَبُواْ حَتَّىٰ يُلَٰقُواْ يَوۡمَهُمُ ٱلَّذِي يُوعَدُونَ ﴿٤٢﴾ يَوۡمَ يَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعٗا كَأَنَّهُمۡ إِلَىٰ نُصُبٖ يُوفِضُونَ ﴿٤٣﴾ خَٰشِعَةً أَبۡصَٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةٞۚ ذَٰلِكَ ٱلۡيَوۡمُ ٱلَّذِي كَانُواْ يُوعَدُونَ ﴿٤٤﴾", "w": [["قِبَلك مهطعين", "نحوك، مديمي النظر إليك."], ["عزين", "جماعات حِلَقاً حِلَقاً، يقولون استهزاءً بالمؤمنين: لئن دخل هؤلاء الجنة لندخلنّها قبلهم."], ["إنا خلقناهم مما يعلمون", "من منيّ قذر، وإنما يُستوجب دخول الجنة بالطاعات المزكّية للنفس."], ["على أن نبدّل خيراً منهم", "إنا لقادرون على أن نهلكهم ونأتي بأناس خير منهم."], ["وما نحن بمسبوقين", "بعاجزين عن ذلك."], ["يوم يخرجون من الأجداث سراعاً", "من القبور، مسرعين إلى المحشر."], ["كأنهم إلى نُصُب يوفضون", "كأنهم في إسراعهم إلى شيء منصوب، كراية أو علم، يسرعون."], ["ترهقهم ذلّة", "تغشاهم ذلّة."], ["ذلك اليوم الذي كانوا يوعدون", "يوعدون بالعذاب فيه، وهو يوم القيامة."]], "m": "فما للذين كفروا من كفار مكة نحوك حيث كنت في المسجد الحرام مسرعين مديمي النظر إليك، عن يمينك وعن شمالك جماعات، حِلَقاً يستمعون إلى قراءتك بحثاً عن كلمة يشنّعون بها عليك، ويقولون استهزاءً بالمؤمنين: لئن دخل هؤلاء الجنة لندخلنّها قبلهم. فردّ تعالى عليهم: أيطمع كل امرئ منهم أن يدخل جنة نعيم؟ كلا، لن يكون ذلك وهم أنجاس الأرواح بالشرك والمعاصي، ولفت النظر إلى أصل الخلقة، المنيّ القذر، والقذر لا يدخل دار السلام، فمن أراد الجنة فليزكِّ نفسه بالإيمان والعمل الصالح. فلا، ليس الأمر كما يتصوّرون من أنهم لا يُبعثون، أقسم برب المشارق والمغارب، حيث الشمس تطلع كل يوم في مطلع وتغرب في آخر، إنا لقادرون على أن نهلكهم ونأتي بخير منهم، وما نحن بعاجزين عن ذلك، فكيف لا نعيدهم أحياء يوم القيامة؟ فذرهم يخوضوا في الباطل ويلعبوا حتى يلاقوا يومهم الذي يوعدون، وهو تهديد لهم: يوم يخرجون من القبور مسرعين كأنهم إلى شيء منصوب يسرعون، خاشعة أبصارهم ذليلة من الفزع، تغشاهم ذلّة عظيمة، ذلك اليوم الذي كانوا يوعدون بالعذاب فيه، وهو يوم القيامة الذي أنكروه وكذّبوا به.", "h": ["بيان الحال التي كان عليها الرسول ﷺ في مكة بين ظهراني قريش، وما كان يلاقي من أذاهم.", "بيان أن الجنة تُدخل بالطهارة الروحية من قذر الشرك والمعاصي، وإلا فأصل الناس واحد، المنيّ، باستثناء آدم وحواء وعيسى؛ فآدم أصله الطين، وحواء خُلقت من ضلع آدم، وعيسى كان بنفخ روح القدس في كُمّ درع مريم فكان بكلمة الله تعالى.", "الاستدلال بالنشأة الأولى على إمكان الثانية.", "تقرير عقيدة البعث والجزاء.", "بيان أن حياة أهل الكفر، مهما تراءى لهم ولغيرهم أنها حياة مدنية سعيدة، لم تعدُ كونها باطلاً ولهواً."], "k": "«أيطمع كل امرئ منهم أن يدخل جنة نعيم»… الطمع بلا عمل غرور؛ فهل عملي على قدر طمعي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (424, 71, 1, 28, 'سورة نوح ١ – ٢٨', 'نوح: استغفروا ربكم إنه كان غفّاراً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 424) = $j$[{"lbl": "الآيات ١ – ٤", "q": "إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ ﴿١﴾ قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ﴿٢﴾ أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ ﴿٣﴾ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ ﴿٤﴾", "w": [["إنا أرسلنا نوحاً إلى قومه", "أهل الأرض كافة، والدليل إغراقهم أجمعين."], ["أن أنذر قومك", "بإنذار قومك."], ["إني لكم نذير مبين", "بيّن النذارة ظاهرها."], ["أن اعبدوا الله", "وحده، بفعل محابّه وترك مكارهه، ولا تشركوا به شيئاً."], ["واتقوه", "فلا تعصوه بترك عبادته ولا بالشرك به."], ["وأطيعون", "فيما آمركم به وأنهاكم عنه، لأني مبلّغ عن الله ربي وربكم."], ["يغفر لكم من ذنوبكم", "ذنوبكم التي هي الشرك والمعاصي."], ["ويؤخّركم إلى أجل مسمّى", "إلى نهاية آجالكم المسمّاة لكم في كتاب المقادير، فلا يعجّل عذابكم."], ["إن أجل الله إذا جاء لا يؤخّر", "إن أجل عذابكم إن لم تؤمنوا لا يؤخّر."], ["لو كنتم تعلمون", "لآمنتم."]], "m": "يخبر تعالى لافتاً نظر منكري رسالة نبيه محمد ﷺ من مشركي قريش أن محمداً ليس بأول رسول حتى تُنكر رسالته، كما أن السورة بجملتها تسلية لرسول الله ﷺ مما يلاقي من قومه، إذ نوح ﵇ قد لاقى ما هو أشد وأطول مدة. أرسلناه بإنذار قومه من قبل أن يأتيهم عذاب أليم: عذاب الدنيا بالاستئصال، وعذاب الآخرة بالدوام. فامتثل نوح أمر ربه وقال: يا قوم إني لكم مخوّف من عواقب كفركم وشرككم، أن اعبدوا الله وحده، واتقوه فلا تعصوه، وأطيعوني فيما آمركم به وأنهاكم عنه، فإني مبلّغ عن الله، ولا آمركم إلا بما يكمّلكم ويسعدكم. فإن تستجيبوا يغفر لكم من ذنوبكم ويؤخّركم إلى نهاية آجالكم فلا يعاجلكم بالعقوبة، إن أجل الله بعذابكم إذا جاء لا يؤخّر، لو علمتم ذلك لأنبتم إلى ربكم واستغفرتموه.", "h": ["تقرير النبوة المحمدية، إذ الذي أرسل نوحاً يرسل محمداً ﷺ ومن شاء إلى من شاء.", "تقرير التوحيد، إذ نوح أُرسل إلى قوم مشركين لإبطال الشرك وتحقيق التوحيد.", "تقرير معتقد القضاء والقدر، لقوله: «ويؤخّركم إلى أجل مسمّى» أي في كتاب المقادير."], "k": "«أن اعبدوا الله واتقوه وأطيعون»… ثلاث كلمات هي الدين كله؛ فأيها أضعف عندي؟"}, {"lbl": "الآيات ٥ – ٢٠", "q": "قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا ﴿٥﴾ فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا ﴿٦﴾ وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا ﴿٧﴾ ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا ﴿٨﴾ ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا ﴿٩﴾ فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا ﴿١٠﴾ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا ﴿١١﴾ وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّـٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا ﴿١٢﴾ مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا ﴿١٣﴾ وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا ﴿١٤﴾ أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا ﴿١٥﴾ وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا ﴿١٦﴾ وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا ﴿١٧﴾ ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا ﴿١٨﴾ وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا ﴿١٩﴾ لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا ﴿٢٠﴾", "w": [["ليلاً ونهاراً", "دائماً باستمرار."], ["إلا فراراً", "مني ومن الحق الذي أدعوهم إليه، وهو عبادة الله وحده."], ["جعلوا أصابعهم في آذانهم", "حتى لا يسمعوا ما أقول لهم."], ["واستغشوا ثيابهم", "تغطّوا بها حتى لا ينظروا إليّ ولا يروني."], ["وأصرّوا", "على باطلهم وما هم عليه من الشرك."], ["يرسل السماء عليكم مدراراً", "ينزل عليكم المطر متتابعاً كلما دعت الحاجة إليه."], ["ويجعل لكم جنات", "بساتين."], ["ما لكم لا ترجون لله وقاراً", "لا تخافون لله عظمته وكبرياءه وهو القاهر فوق عباده."], ["وقد خلقكم أطواراً", "حالاً بعد حال: نطفة ثم علقة ثم مضغة."], ["وجعل الشمس سراجاً", "مضيئة."], ["أنبتكم من الأرض نباتاً", "أنشأكم من تراب الأرض."], ["ثم يعيدكم فيها", "تُقبرون فيها."], ["ويخرجكم إخراجاً", "يوم القيامة."], ["سبلاً فجاجاً", "طرقاً واسعة."]], "m": "هذه الآيات لوحة مشرقة يهتدي بضوئها الدعاة إلى الله، إذ هي عرض حال قدّمه نوح لربه، هو خلاصة دعوة دامت قرابة تسعمائة وخمسين سنة: رب إني دعوت قومي ليلاً ونهاراً، إذ بعض الناس لا يمكن الاتصال بهم إلا ليلاً، فلم يزدهم دعائي إلا فراراً مني ومما أدعوهم إليه، وإني كلما دعوتهم ليستغفروك فتغفر لهم جعلوا أصابعهم في آذانهم، وتغطّوا بثيابهم حتى لا يروني كراهةً لي، وأصرّوا على الشرك عناداً، واستكبروا استكباراً عجيباً. ثم إني دعوتهم إلى توحيدك مجاهراً، ثم أعلنت لهم وأسررت لهم إسراراً، بحسب الجماعات والظروف، أطرق كل باب بحثاً عن استجابتهم، فقلت: استغفروا ربكم إنه كان غفّاراً، يرسل السماء عليكم بالمطر متتابعاً فلا يكون قحط، ويمددكم بأموال وبنين كما هي رغبتكم، ويجعل لكم بساتين ويجعل لكم أنهاراً. ثم قال منكراً عليهم عدم خوفهم: ما لكم لا تخافون عظمة الله وكبرياءه، وقد خلقكم أطواراً؟ ولفت نظرهم إلى مظاهر قدرته: ألم تروا كيف خلق الله سبع سماوات طباقاً، وجعل القمر فيهن نوراً، وجعل الشمس سراجاً وهّاجاً، والله أنبتكم من الأرض نباتاً، إذ أصلكم من تراب، ثم يعيدكم فيها بعد الموت، ويخرجكم يوم القيامة للحساب، والله جعل لكم الأرض بساطاً صالحة للعيش، لتسلكوا منها طرقاً واسعة. وهكذا تجوّل بهم نوح في معارض آيات الله الكونية، وكلها دالة على وجوده وقدرته وعلمه ورحمته، موجبة لعبادته وحده، وفي هذا درس عظيم للدعاة الهداة.", "h": ["رسم الطريق الصحيح للدعوة القائم على الصبر وتلوين الأسلوب.", "بيان كره المشركين للتوحيد والموحّدين، إنهم لبغضهم لنوح ودعوة التوحيد سدّوا آذانهم حتى لا يسمعوا، وغطّوا وجوههم حتى لا يروه، واستكبروا حتى لا يروا له فضلاً.", "استعمال الحكمة في الدعوة؛ فإن نوحاً لما رأى أن قومه يحبّون الدنيا أرشدهم إلى الاستغفار ليحصل لهم المال والولد.", "استنبط بعض الصالحين من هذه الآية أن من كانت له رغبة في مال أو ولد فليكثر من الاستغفار الليل والنهار ولا يملّ، يعطه الله تعالى مراده من المال والولد."], "k": "«استغفروا ربكم إنه كان غفّاراً يرسل السماء عليكم مدراراً»… حاجتي التي أنتظرها، هل جرّبت لها الاستغفار؟"}, {"lbl": "الآيات ٢١ – ٢٤", "q": "قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا ﴿٢١﴾ وَمَكَرُواْ مَكۡرٗا كُبَّارٗا ﴿٢٢﴾ وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا ﴿٢٣﴾ وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَٰلٗا ﴿٢٤﴾", "w": [["عصوني", "لم يطيعوني فيما دعوتهم إليه من عبادتك وحدك."], ["واتّبعوا", "اتّبع السفلة منهم والفقراء."], ["من لم يزده ماله وولده", "الرؤساء المنعَم عليهم."], ["إلا خساراً", "طغياناً وكفراً."], ["ومكروا مكراً كُبّاراً", "عظيماً جداً، بأن كذّبوا نوحاً وآذوه أذى شديداً."], ["وقالوا", "قال الرؤساء للسفلة منهم."], ["لا تذرنّ آلهتكم", "لا تتركنّ آلهتكم."], ["ولا تذرنّ ودّاً ولا سواعاً…", "ولا تتركنّ كذلك ودّاً ولا سواعاً ولا يغوث ويعوق ونسراً."], ["وقد أضلّوا كثيراً", "أضلّوا بالأصنام كثيراً من الناس حيث أمروا بعبادتها."]], "m": "بعد ذلك العرض الكريم الذي تقدّم به نوح ﵇ إلى ربه، تقدّم بشكوى مشفوعة بالدعاء على الظالمين فقال: رب إنهم عصوني، واتّبع السفلة الرؤساء الذين لم يزدهم مالهم وولدهم إلا طغياناً وكفراً، ومكروا مكراً عظيماً جداً، حيث كانوا يعرّضون بنوح وقد يضربونه وهو صابر محتسب، وقالوا لبعضهم متواصين بالباطل: لا تذرنّ آلهتكم، وسمّوا منها رؤساءها، وهم خمسة: ودّ وسواع ويغوث ويعوق ونسر، وقد أضلّوا كثيراً من عباد الله حيث ورثوا هذه الأصنام فيهم. ثم دعا عليهم: ولا تزد الظالمين إلا ضلالاً، قال هذا بعد أن أيس من إيمانهم لطول ما مكث بينهم يدعوهم وهم لا يزدادون إلا كفراً.", "h": ["مشروعية الشكوى إلى الله تعالى، ولكن بدون صخب ولا نصب.", "بيان أن السفلة والفقراء يتّبعون الرؤساء والأغنياء وأصحاب الحظ.", "بيان أن المكر من شأن الكافرين والظالمين.", "المشركون لضلالهم يطلقون لفظ الآلهة على من يعبدونهم من الأصنام والأوثان.", "مشروعية الدعاء على الظالمين عند اليأس من هدايتهم."], "k": "«من لم يزده ماله وولده إلا خساراً»… هل يزيدني مالي قرباً من الله أم بعداً؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا ﴿٢٥﴾ وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا ﴿٢٦﴾ إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا ﴿٢٧﴾ رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارَۢا ﴿٢٨﴾", "w": [["مما خطيئاتهم أُغرقوا", "بسبب خطيئاتهم أُغرقوا بالطوفان."], ["فأُدخلوا ناراً", "بعد موتهم أُدخلت أرواحهم النار."], ["دَيّاراً", "من يدور، يذهب ويجيء، أي لا تُبقِ منهم أحداً."], ["إنك إن تذرهم", "إن تبقِهم أحياء لم تهلكهم."]], "m": "يخبر تعالى عن نهاية قوم نوح بعد أن دعا عليهم لما علم بالوحي أنهم لا يؤمنون: بسبب خطيئاتهم التي هي الشرك والظلم والتكذيب والأذى لنوح أُغرقوا بالطوفان فلم يبقَ منهم أحد، فأُدخلوا ناراً، فبمجرّد ما يغرق الشخص وتخرج روحه يُدخل النار في البرزخ، فلم يجدوا لهم من دون الله أنصاراً، فمن ينصر من يريد الله هلاكه؟ ثم ذكر تعالى دعوة نوح التي كان بها الطوفان: رب لا تذر على الأرض من الكافرين ديّاراً، أي لا تُبقِ منهم أحداً، ثم علّل طلبه: إنك إن تذرهم يضلّوا عبادك عن صراطك، ولا يلدوا إلا فاجراً عن دينك كفّاراً بك وبرسولك، قال نوح هذا لطول التجارب التي عاشها مع قومه، إذ عاشرهم قرابة عشرة قرون. ثم دعا الله له ولوالديه ولمن دخل بيته مؤمناً وللمؤمنين والمؤمنات، وألا يزيد الظالمين إلا هلاكاً.", "h": ["هلاك قوم نوح كان بخطاياهم، فالخطايا إذاً موجبة للهلاك.", "تقرير عذاب القبر، فقوم نوح ما إن أُغرقوا حتى أُدخلوا ناراً.", "مشروعية الدعاء على الظلمة والكافرين والمجرمين.", "مشروعية الدعاء للمؤمنين والمؤمنات."], "k": "«رب اغفر لي ولوالديّ… وللمؤمنين والمؤمنات»… دعاء نبي بعد ألف سنة دعوة؛ فهل يتّسع دعائي لغيري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 424;
insert into public.tdb_cards(topic, i, body) select 424, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٤", "q": "إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ ﴿١﴾ قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ ﴿٢﴾ أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ ﴿٣﴾ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ ﴿٤﴾", "w": [["إنا أرسلنا نوحاً إلى قومه", "أهل الأرض كافة، والدليل إغراقهم أجمعين."], ["أن أنذر قومك", "بإنذار قومك."], ["إني لكم نذير مبين", "بيّن النذارة ظاهرها."], ["أن اعبدوا الله", "وحده، بفعل محابّه وترك مكارهه، ولا تشركوا به شيئاً."], ["واتقوه", "فلا تعصوه بترك عبادته ولا بالشرك به."], ["وأطيعون", "فيما آمركم به وأنهاكم عنه، لأني مبلّغ عن الله ربي وربكم."], ["يغفر لكم من ذنوبكم", "ذنوبكم التي هي الشرك والمعاصي."], ["ويؤخّركم إلى أجل مسمّى", "إلى نهاية آجالكم المسمّاة لكم في كتاب المقادير، فلا يعجّل عذابكم."], ["إن أجل الله إذا جاء لا يؤخّر", "إن أجل عذابكم إن لم تؤمنوا لا يؤخّر."], ["لو كنتم تعلمون", "لآمنتم."]], "m": "يخبر تعالى لافتاً نظر منكري رسالة نبيه محمد ﷺ من مشركي قريش أن محمداً ليس بأول رسول حتى تُنكر رسالته، كما أن السورة بجملتها تسلية لرسول الله ﷺ مما يلاقي من قومه، إذ نوح ﵇ قد لاقى ما هو أشد وأطول مدة. أرسلناه بإنذار قومه من قبل أن يأتيهم عذاب أليم: عذاب الدنيا بالاستئصال، وعذاب الآخرة بالدوام. فامتثل نوح أمر ربه وقال: يا قوم إني لكم مخوّف من عواقب كفركم وشرككم، أن اعبدوا الله وحده، واتقوه فلا تعصوه، وأطيعوني فيما آمركم به وأنهاكم عنه، فإني مبلّغ عن الله، ولا آمركم إلا بما يكمّلكم ويسعدكم. فإن تستجيبوا يغفر لكم من ذنوبكم ويؤخّركم إلى نهاية آجالكم فلا يعاجلكم بالعقوبة، إن أجل الله بعذابكم إذا جاء لا يؤخّر، لو علمتم ذلك لأنبتم إلى ربكم واستغفرتموه.", "h": ["تقرير النبوة المحمدية، إذ الذي أرسل نوحاً يرسل محمداً ﷺ ومن شاء إلى من شاء.", "تقرير التوحيد، إذ نوح أُرسل إلى قوم مشركين لإبطال الشرك وتحقيق التوحيد.", "تقرير معتقد القضاء والقدر، لقوله: «ويؤخّركم إلى أجل مسمّى» أي في كتاب المقادير."], "k": "«أن اعبدوا الله واتقوه وأطيعون»… ثلاث كلمات هي الدين كله؛ فأيها أضعف عندي؟"}, {"lbl": "الآيات ٥ – ٢٠", "q": "قَالَ رَبِّ إِنِّي دَعَوۡتُ قَوۡمِي لَيۡلٗا وَنَهَارٗا ﴿٥﴾ فَلَمۡ يَزِدۡهُمۡ دُعَآءِيٓ إِلَّا فِرَارٗا ﴿٦﴾ وَإِنِّي كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوٓاْ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡاْ ثِيَابَهُمۡ وَأَصَرُّواْ وَٱسۡتَكۡبَرُواْ ٱسۡتِكۡبَارٗا ﴿٧﴾ ثُمَّ إِنِّي دَعَوۡتُهُمۡ جِهَارٗا ﴿٨﴾ ثُمَّ إِنِّيٓ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارٗا ﴿٩﴾ فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا ﴿١٠﴾ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا ﴿١١﴾ وَيُمۡدِدۡكُم بِأَمۡوَٰلٖ وَبَنِينَ وَيَجۡعَل لَّكُمۡ جَنَّـٰتٖ وَيَجۡعَل لَّكُمۡ أَنۡهَٰرٗا ﴿١٢﴾ مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا ﴿١٣﴾ وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا ﴿١٤﴾ أَلَمۡ تَرَوۡاْ كَيۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَٰوَٰتٖ طِبَاقٗا ﴿١٥﴾ وَجَعَلَ ٱلۡقَمَرَ فِيهِنَّ نُورٗا وَجَعَلَ ٱلشَّمۡسَ سِرَاجٗا ﴿١٦﴾ وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتٗا ﴿١٧﴾ ثُمَّ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجٗا ﴿١٨﴾ وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطٗا ﴿١٩﴾ لِّتَسۡلُكُواْ مِنۡهَا سُبُلٗا فِجَاجٗا ﴿٢٠﴾", "w": [["ليلاً ونهاراً", "دائماً باستمرار."], ["إلا فراراً", "مني ومن الحق الذي أدعوهم إليه، وهو عبادة الله وحده."], ["جعلوا أصابعهم في آذانهم", "حتى لا يسمعوا ما أقول لهم."], ["واستغشوا ثيابهم", "تغطّوا بها حتى لا ينظروا إليّ ولا يروني."], ["وأصرّوا", "على باطلهم وما هم عليه من الشرك."], ["يرسل السماء عليكم مدراراً", "ينزل عليكم المطر متتابعاً كلما دعت الحاجة إليه."], ["ويجعل لكم جنات", "بساتين."], ["ما لكم لا ترجون لله وقاراً", "لا تخافون لله عظمته وكبرياءه وهو القاهر فوق عباده."], ["وقد خلقكم أطواراً", "حالاً بعد حال: نطفة ثم علقة ثم مضغة."], ["وجعل الشمس سراجاً", "مضيئة."], ["أنبتكم من الأرض نباتاً", "أنشأكم من تراب الأرض."], ["ثم يعيدكم فيها", "تُقبرون فيها."], ["ويخرجكم إخراجاً", "يوم القيامة."], ["سبلاً فجاجاً", "طرقاً واسعة."]], "m": "هذه الآيات لوحة مشرقة يهتدي بضوئها الدعاة إلى الله، إذ هي عرض حال قدّمه نوح لربه، هو خلاصة دعوة دامت قرابة تسعمائة وخمسين سنة: رب إني دعوت قومي ليلاً ونهاراً، إذ بعض الناس لا يمكن الاتصال بهم إلا ليلاً، فلم يزدهم دعائي إلا فراراً مني ومما أدعوهم إليه، وإني كلما دعوتهم ليستغفروك فتغفر لهم جعلوا أصابعهم في آذانهم، وتغطّوا بثيابهم حتى لا يروني كراهةً لي، وأصرّوا على الشرك عناداً، واستكبروا استكباراً عجيباً. ثم إني دعوتهم إلى توحيدك مجاهراً، ثم أعلنت لهم وأسررت لهم إسراراً، بحسب الجماعات والظروف، أطرق كل باب بحثاً عن استجابتهم، فقلت: استغفروا ربكم إنه كان غفّاراً، يرسل السماء عليكم بالمطر متتابعاً فلا يكون قحط، ويمددكم بأموال وبنين كما هي رغبتكم، ويجعل لكم بساتين ويجعل لكم أنهاراً. ثم قال منكراً عليهم عدم خوفهم: ما لكم لا تخافون عظمة الله وكبرياءه، وقد خلقكم أطواراً؟ ولفت نظرهم إلى مظاهر قدرته: ألم تروا كيف خلق الله سبع سماوات طباقاً، وجعل القمر فيهن نوراً، وجعل الشمس سراجاً وهّاجاً، والله أنبتكم من الأرض نباتاً، إذ أصلكم من تراب، ثم يعيدكم فيها بعد الموت، ويخرجكم يوم القيامة للحساب، والله جعل لكم الأرض بساطاً صالحة للعيش، لتسلكوا منها طرقاً واسعة. وهكذا تجوّل بهم نوح في معارض آيات الله الكونية، وكلها دالة على وجوده وقدرته وعلمه ورحمته، موجبة لعبادته وحده، وفي هذا درس عظيم للدعاة الهداة.", "h": ["رسم الطريق الصحيح للدعوة القائم على الصبر وتلوين الأسلوب.", "بيان كره المشركين للتوحيد والموحّدين، إنهم لبغضهم لنوح ودعوة التوحيد سدّوا آذانهم حتى لا يسمعوا، وغطّوا وجوههم حتى لا يروه، واستكبروا حتى لا يروا له فضلاً.", "استعمال الحكمة في الدعوة؛ فإن نوحاً لما رأى أن قومه يحبّون الدنيا أرشدهم إلى الاستغفار ليحصل لهم المال والولد.", "استنبط بعض الصالحين من هذه الآية أن من كانت له رغبة في مال أو ولد فليكثر من الاستغفار الليل والنهار ولا يملّ، يعطه الله تعالى مراده من المال والولد."], "k": "«استغفروا ربكم إنه كان غفّاراً يرسل السماء عليكم مدراراً»… حاجتي التي أنتظرها، هل جرّبت لها الاستغفار؟"}, {"lbl": "الآيات ٢١ – ٢٤", "q": "قَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا ﴿٢١﴾ وَمَكَرُواْ مَكۡرٗا كُبَّارٗا ﴿٢٢﴾ وَقَالُواْ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدّٗا وَلَا سُوَاعٗا وَلَا يَغُوثَ وَيَعُوقَ وَنَسۡرٗا ﴿٢٣﴾ وَقَدۡ أَضَلُّواْ كَثِيرٗاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَٰلٗا ﴿٢٤﴾", "w": [["عصوني", "لم يطيعوني فيما دعوتهم إليه من عبادتك وحدك."], ["واتّبعوا", "اتّبع السفلة منهم والفقراء."], ["من لم يزده ماله وولده", "الرؤساء المنعَم عليهم."], ["إلا خساراً", "طغياناً وكفراً."], ["ومكروا مكراً كُبّاراً", "عظيماً جداً، بأن كذّبوا نوحاً وآذوه أذى شديداً."], ["وقالوا", "قال الرؤساء للسفلة منهم."], ["لا تذرنّ آلهتكم", "لا تتركنّ آلهتكم."], ["ولا تذرنّ ودّاً ولا سواعاً…", "ولا تتركنّ كذلك ودّاً ولا سواعاً ولا يغوث ويعوق ونسراً."], ["وقد أضلّوا كثيراً", "أضلّوا بالأصنام كثيراً من الناس حيث أمروا بعبادتها."]], "m": "بعد ذلك العرض الكريم الذي تقدّم به نوح ﵇ إلى ربه، تقدّم بشكوى مشفوعة بالدعاء على الظالمين فقال: رب إنهم عصوني، واتّبع السفلة الرؤساء الذين لم يزدهم مالهم وولدهم إلا طغياناً وكفراً، ومكروا مكراً عظيماً جداً، حيث كانوا يعرّضون بنوح وقد يضربونه وهو صابر محتسب، وقالوا لبعضهم متواصين بالباطل: لا تذرنّ آلهتكم، وسمّوا منها رؤساءها، وهم خمسة: ودّ وسواع ويغوث ويعوق ونسر، وقد أضلّوا كثيراً من عباد الله حيث ورثوا هذه الأصنام فيهم. ثم دعا عليهم: ولا تزد الظالمين إلا ضلالاً، قال هذا بعد أن أيس من إيمانهم لطول ما مكث بينهم يدعوهم وهم لا يزدادون إلا كفراً.", "h": ["مشروعية الشكوى إلى الله تعالى، ولكن بدون صخب ولا نصب.", "بيان أن السفلة والفقراء يتّبعون الرؤساء والأغنياء وأصحاب الحظ.", "بيان أن المكر من شأن الكافرين والظالمين.", "المشركون لضلالهم يطلقون لفظ الآلهة على من يعبدونهم من الأصنام والأوثان.", "مشروعية الدعاء على الظالمين عند اليأس من هدايتهم."], "k": "«من لم يزده ماله وولده إلا خساراً»… هل يزيدني مالي قرباً من الله أم بعداً؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "مِّمَّا خَطِيٓـَٰٔتِهِمۡ أُغۡرِقُواْ فَأُدۡخِلُواْ نَارٗا فَلَمۡ يَجِدُواْ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارٗا ﴿٢٥﴾ وَقَالَ نُوحٞ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا ﴿٢٦﴾ إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا ﴿٢٧﴾ رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارَۢا ﴿٢٨﴾", "w": [["مما خطيئاتهم أُغرقوا", "بسبب خطيئاتهم أُغرقوا بالطوفان."], ["فأُدخلوا ناراً", "بعد موتهم أُدخلت أرواحهم النار."], ["دَيّاراً", "من يدور، يذهب ويجيء، أي لا تُبقِ منهم أحداً."], ["إنك إن تذرهم", "إن تبقِهم أحياء لم تهلكهم."]], "m": "يخبر تعالى عن نهاية قوم نوح بعد أن دعا عليهم لما علم بالوحي أنهم لا يؤمنون: بسبب خطيئاتهم التي هي الشرك والظلم والتكذيب والأذى لنوح أُغرقوا بالطوفان فلم يبقَ منهم أحد، فأُدخلوا ناراً، فبمجرّد ما يغرق الشخص وتخرج روحه يُدخل النار في البرزخ، فلم يجدوا لهم من دون الله أنصاراً، فمن ينصر من يريد الله هلاكه؟ ثم ذكر تعالى دعوة نوح التي كان بها الطوفان: رب لا تذر على الأرض من الكافرين ديّاراً، أي لا تُبقِ منهم أحداً، ثم علّل طلبه: إنك إن تذرهم يضلّوا عبادك عن صراطك، ولا يلدوا إلا فاجراً عن دينك كفّاراً بك وبرسولك، قال نوح هذا لطول التجارب التي عاشها مع قومه، إذ عاشرهم قرابة عشرة قرون. ثم دعا الله له ولوالديه ولمن دخل بيته مؤمناً وللمؤمنين والمؤمنات، وألا يزيد الظالمين إلا هلاكاً.", "h": ["هلاك قوم نوح كان بخطاياهم، فالخطايا إذاً موجبة للهلاك.", "تقرير عذاب القبر، فقوم نوح ما إن أُغرقوا حتى أُدخلوا ناراً.", "مشروعية الدعاء على الظلمة والكافرين والمجرمين.", "مشروعية الدعاء للمؤمنين والمؤمنات."], "k": "«رب اغفر لي ولوالديّ… وللمؤمنين والمؤمنات»… دعاء نبي بعد ألف سنة دعوة؛ فهل يتّسع دعائي لغيري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (425, 72, 1, 28, 'سورة الجن ١ – ٢٨', 'الجن: إنا سمعنا قرآناً عجباً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 425) = $j$[{"lbl": "الآيات ١ – ٧", "q": "قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا ﴿١﴾ يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا ﴿٢﴾ وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا ﴿٣﴾ وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا ﴿٤﴾ وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا ﴿٥﴾ وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا ﴿٦﴾ وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا ﴿٧﴾", "w": [["أنه استمع", "إلى قراءتي."], ["نفر من الجن", "عدد من الجن ما بين الثلاثة والعشرة."], ["إنا سمعنا قرآناً عجباً", "قالوا لبعضهم: قرآناً يُتعجّب منه لفصاحته وغزارة معانيه."], ["يهدي إلى الرشد", "الصواب في المعتقد والقول والعمل."], ["وأنه تعالى جدّ ربنا", "تنزّه جلال ربنا وعظمته عما نُسب إليه."], ["ما اتخذ صاحبة ولا ولداً", "لم يتخذ صاحبة، ولم يكن له ولد."], ["سفيهنا", "جاهلنا."], ["شططاً", "غلوّاً في الكذب بوصفه الله تعالى بالصاحبة والولد."], ["على الله كذباً", "حتى تبيّن لنا أنهم يكذبون على الله بنسبة الزوجة والولد إليه."], ["يعوذون", "يستعيذون."], ["فزادوهم رهقاً", "إثماً وطغياناً."], ["أن لن يبعث الله أحداً", "لن يبعث رسولاً إلى خلقه."]], "m": "يأمر تعالى رسوله ﷺ أن يعلن للناس أن الله أوحى إليه أن نفراً من الجن استمعوا إلى قراءته القرآن ببطن نخلة وهو يصلي بأصحابه صلاة الفجر عامداً إلى سوق عكاظ، وكان قد حيل بين الشياطين وخبر السماء حيث أُرسلت عليهم الشهب، فانطلقوا يضربون في مشارق الأرض ومغاربها يتعرّفون هذا الحدث، فتوجّه نفر منهم إلى تهامة فوجدوا الرسول ﷺ يصلي الصبح فاستمعوا إلى قراءته، فرجعوا إلى قومهم فقالوا: إنا سمعنا قرآناً يُتعجّب من فصاحته وغزارة معانيه، يهدي إلى الصواب في العقيدة والقول والعمل، فآمنّا به ولن نشرك بربنا أحداً. وفي هذا تعريض بسخف البشر الذين عاش الرسول بينهم إحدى عشرة سنة يقرأ عليهم القرآن بمكة وهم مكذّبون، والجن بمجرد أن سمعوه آمنوا به وحملوا رسالته إلى قومهم. وقالوا: وآمنّا بأنه تعالى جلّ أمر ربنا وسلطانه، ما اتخذ صاحبة ولا ولداً، وأنه كان يقول جاهلنا على الله غلوّاً في الكذب بوصفه بالصاحبة والولد تقليداً للمشركين، وإنا كنا نظن أن الإنس والجن لا يكذبون على الله، وقد علمنا الآن أنهم يكذبون عليه. وأنه كان رجال من الإنس، من العرب وغيرهم، إذا نزلوا منزلاً مخوفاً في وادٍ يستعيذون برجال من الجن، كأن يقول الرجل: أعوذ بسيد هذا الوادي من سفهاء قومه، فزاد الإنس الجن بهذا اللجوء إليهم إثماً وطغياناً، إذ ما كانوا يطمعون أن تعظّمهم الإنس هذا التعظيم. وأن الإنس ظنّوا كما ظننتم أن لن يبعث الله رسولاً ينذر الناس عذابه ويعلّمهم ما يكمّلهم ويسعدهم.", "h": ["تقرير النبوة المحمدية، وأن محمداً رسول للثقلين الإنس والجن معاً.", "بيان علوّ شأن القرآن وكماله، حيث شهدت الجن له بأنه عجب فوق مستوى كلام الخلق.", "تقرير التوحيد والتنديد بالشرك.", "تقرير أن الإنس كالجن قد يكذبون على الله، وما كان لهم ذلك.", "حرمة الاستعانة بالجن والاستعاذة بهم، لأن ذلك كالعبادة لهم."], "k": "«إنا سمعنا قرآناً عجباً… فآمنّا به»… سمعوه مرة فآمنوا؛ وأنا أسمعه كل يوم، فماذا يتحرك فيّ؟"}, {"lbl": "الآيات ٨ – ١٥", "q": "وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا ﴿٨﴾ وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا ﴿٩﴾ وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا ﴿١٠﴾ وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا ﴿١١﴾ وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا ﴿١٢﴾ وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا ﴿١٣﴾ وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَـٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا ﴿١٤﴾ وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا ﴿١٥﴾", "w": [["حرساً شديداً", "ملائكة أقوياء يحرسونها."], ["وشهباً", "نجوماً يُرمى بها الشياطين، أو يُؤخذ منها شهاب فيُرمى به."], ["مقاعد للسمع", "من أجل أن نسمع ما يحدث وما يكون في الكون."], ["شهاباً رصداً", "أُرصد وأُعدّ لرمي الشياطين وإبعادهم عن السمع."], ["رشداً", "خيراً وصلاحاً."], ["كنا طرائق قدداً", "مذاهب مختلفة، والطرائق جمع طريقة، والقدد الضروب المختلفة."], ["ولن نعجزه هرباً", "لا نفوته هاربين في الأرض أو في السماء."], ["لما سمعنا الهدى", "القرآن الداعي إلى الهدى."], ["بخساً ولا رهقاً", "نقصاً من حسناته، ولا إثماً يُحمل عليه ويُحاسب به."], ["ومنا القاسطون", "الجائرون عن قصد السبيل، وهو الإسلام."], ["تحرّوا رشداً", "تعمّدوا الرشد فطلبوه بعناية فحصلوا عليه."], ["فكانوا لجهنم حطباً", "وقوداً تتّقد بهم يوم القيامة."]], "m": "ما زال السياق فيما قالته الجن بعد سماعها القرآن: وإنا طلبنا السماء كعادتنا فوجدناها مُلئت ملائكة أقوياء يحرسونها، وشهباً نارية يُرمى بها كل مسترق للسمع منا، وإنا كنا نقعد منها أماكن معيّنة للاستماع من ملائكة السماء، فمن يستمع الآن يجد له شهاباً أُرصد له خاصة فيُرمى به فيحرقه أو يخبله. وإنا لا ندري أشرّ أُريد بمن في الأرض أم أراد بهم ربهم رشداً؛ وعجباً لهؤلاء المؤمنين من الجن كيف تأدّبوا مع الله فلم ينسبوا إليه الشر ونسبوا إليه الخير، قالوا هذا لما وجدوا السماء قد مُلئت حرساً، وسبب ذلك أن الله لما نبّأ رسوله محمداً ﷺ حمى السماء حتى لا يسترق الشياطين السمع ويشوّشوا على الناس فيصرفوهم عن الإيمان. وإنا منا الصالحون المستقيمون على الإيمان والطاعة، ومنا دون ذلك ضعف إيمان وقلة طاعة، كنا مذاهب وأهواء مختلفة. وإنا علمنا أن لن نعجز الله في الأرض إن أراد بنا سوءاً، ولن نعجزه هرباً إن طلبنا. وإنا لما سمعنا القرآن آمنّا به، فمن يؤمن بربه فلا يخاف نقصاً من حسناته يوم القيامة، ولا إثماً يُضاف إلى سيئاته وهو لم يرتكبه. وإنا منا المسلمون، ومنا الجائرون عن الإسلام، فمن انقاد لله بطاعته وخلص من الشرك فأولئك تعمّدوا الرشد وفازوا به، وأما الجائرون فكانوا لجهنم حطباً.", "h": ["وجود تجانس بين الجن والملائكة لقرب مادّتي الخلق من بعضهما، إذ الملائكة خُلقوا من مادة النور، والجن من مادة النار، ولذا يرونهم ويسمعون كلامهم ويفهمونه.", "من الجن أدباء صالحون مؤمنون مسلمون أصحاب لرسول الله ﷺ.", "ذمّ الطرق والأهواء والاختلافات.", "الإشادة بالعدل وتحرّي الحق والخير."], "k": "«أشرّ أُريد بمن في الأرض أم أراد بهم ربهم رشداً»… تأدّبوا فلم ينسبوا الشر إليه؛ فكيف أتكلم أنا عن أقداره؟"}, {"lbl": "الآيات ١٦ – ٢٤", "q": "وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا ﴿١٦﴾ لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا ﴿١٧﴾ وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا ﴿١٨﴾ وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا ﴿١٩﴾ قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا ﴿٢٠﴾ قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا ﴿٢١﴾ قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا ﴿٢٢﴾ إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا ﴿٢٣﴾ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا ﴿٢٤﴾", "w": [["على الطريقة", "الإسلام."], ["ماءً غدقاً", "مالاً كثيراً وخيرات كبيرة."], ["لنفتنهم فيه", "نختبرهم أيشكرون أم يكفرون."], ["عن ذكر ربه", "القرآن وشرائعه وأحكامه."], ["عذاباً صعداً", "شاقّاً."], ["فلا تدعوا مع الله أحداً", "فيها مع الله أحداً."], ["عبد الله يدعوه", "محمد ﷺ يدعو الله ببطن نخلة."], ["عليه لبداً", "يركب بعضهم بعضاً تزاحماً لأجل أن يسمعوا قراءته."], ["ضرّاً ولا رشداً", "غيّاً ولا خيراً."], ["ملتحداً", "ملتجأً ألجأ إليه فأحفظ نفسي."], ["إلا بلاغاً", "لا أملك إلا البلاغ إليكم."], ["وأقل عدداً", "أعواناً، المسلمون أم الكافرون."]], "m": "وأُوحي إليّ أن لو استقام هؤلاء المشركون من كفار قريش، وهم يشكون القحط، على الإيمان والتوحيد والطاعة، لأسقيناهم ماءً غدقاً فتكثر أموالهم وتتّسع أرزاقهم، لنختبرهم في ذلك الخير أيشكرون أم يكفرون، فإن شكروا زادهم، وإن كفروا سلبهم وعذّبهم. ومن يعرض عن القرآن وما يدعو إليه نُدخله عذاباً شاقّاً، في الدنيا بالذل والمهانة والفقر، وفي الآخرة في جهنم. ومما أُوحي إليّ أن المساجد لله، فإذا دخلتموها للعبادة فلا تدعوا فيها مع الله أحداً، إذ كيف البيت له وأنت فيه وتدعو معه غيره؟ زيادة على أن الشرك محرّم، فإنه من غير الأدب أن يكون المرء في بيت كريم ويدعو معه غيره. وأُوحي إليّ أنه لما قام عبد الله ورسوله محمد ﷺ يدعو ربه في الصلاة ببطن نخلة كاد الجن يكونون عليه كالشيء المتلبّد بعضه فوق بعض. قل إنما أدعو ربي ولا أشرك به أحداً: إجابة لقريش عندما قالوا له: لقد جئت بأمر عظيم وعاديت الناس كلهم، فارجع عن هذا ونحن نجيرك. وأُمر أن يقول لهم: إني لا أملك لكم ضلالاً ولا هداية، إنما ذلك لله وحده، إني لن يجيرني من الله أحد إن أنا عصيته وأطعتكم، ولن أجد من دونه ملتجأً، إلا بلاغاً من الله ورسالاته، أبلّغكم عنه ما أمرني به. ومن يعصِ الله بالشرك ورسوله بتكذيبه فإن له نار جهنم خالدين فيها أبداً، فإن استمرّوا على شركهم حتى إذا رأوا ما يوعدون من عذاب يوم القيامة فسيعلمون عندئذ من أضعف ناصراً وأقل أعواناً: المؤمنون أم المشركون.", "h": ["الاستقامة على منهج الله تعالى القائم على الإيمان والطاعة لله ورسوله تفضي بسالكها إلى الخير الكثير والسعادة الكاملة في الدنيا والآخرة.", "المال فتنة، وقلّ من ينجح فيها، قال عمر رضي الله عنه: أينما يكون الماء يكون المال، وأينما يكون المال تكون الفتنة.", "حرمة دعاء غير الله في المساجد وفي غيرها، إلا أنها في المساجد أشد قبحاً.", "الخير والغيّ والهدى والضلال لا يملكها إلا الله، فليُطلب ذلك منه لا من غيره.", "معصية الله والرسول موجبة لعذاب الدنيا والآخرة."], "k": "«وأن المساجد لله فلا تدعوا مع الله أحداً»… في بيته، هل قلبي معه وحده أم مشغول بغيره؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا ﴿٢٥﴾ عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا ﴿٢٦﴾ إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدٗا ﴿٢٧﴾ لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا ﴿٢٨﴾", "w": [["قل إن أدري", "قل: ما أدري."], ["ما توعدون", "من العذاب."], ["أمداً", "غاية وأجلاً لا يعلمه إلا هو."], ["فلا يُظهر", "لا يُطلع."], ["إلا من ارتضى من رسول", "فإنه يطلعه."], ["يسلك من بين يديه ومن خلفه رصداً", "ملائكة يحفظونه حتى يبلّغ الوحي للناس."], ["ليعلم", "ليعلم ظهوراً أن الرسل قد بلّغوا رسالات ربهم."], ["وأحصى كل شيء عدداً", "أحصى عدد كل شيء."]], "m": "أمر تعالى رسوله أن يقول للمشركين المطالبين بالعذاب استخفافاً وتكذيباً: ما أدري أقريب ما توعدون من العذاب فيحلّ بكم عاجلاً، أم يجعل له ربي أجلاً بعيداً يعلمه هو ولا يعلمه غيره؟ هو عالم الغيب وحده، فلا يُطلع على غيبه أحداً من عباده، إلا من ارتضى من رسول أن يبلّغ عنه، فإنه يطلعه مع الاحتياط الكافي حتى لا يتسرّب الخبر إلى غيره، فإنه يسلك من بين يدي الرسول المرتضى ومن خلفه حرساً من الملائكة، حتى إنه إذا جاءه الوحي كان معه ملائكة يحمونه من الشياطين حتى لا يسمعوا خبر السماء فيبلّغوه أولياءهم من الإنس فتكون فتنة، ليعلم أن الرسل قبله قد بلّغت رسالات ربها لما أحاطها تعالى به من العناية، وأحاط الله بما لدى الملائكة والرسل علماً، وأحصى عدد كل شيء، فلا يخفى عليه شيء في الأرض ولا في السماء.", "h": ["استئثار الله تعالى بعلم الغيب، فلا يعلم الغيب إلا الله.", "قد يُطلع الله تعالى من ارتضى من الرسل على غيب خاص، ويتم ذلك بعد حماية كاملة من الشياطين كيلا ينقلوه إلى أوليائهم فيفتنوا به الناس.", "بيان إحاطة علم الله بكل شيء، وإحصائه تعالى لكل شيء عدداً."], "k": "«عالم الغيب فلا يُظهر على غيبه أحداً»… الغيب له وحده؛ فهل أطمئن لمن يدّعي معرفة ما سيكون؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 425;
insert into public.tdb_cards(topic, i, body) select 425, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "قُلۡ أُوحِيَ إِلَيَّ أَنَّهُ ٱسۡتَمَعَ نَفَرٞ مِّنَ ٱلۡجِنِّ فَقَالُوٓاْ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبٗا ﴿١﴾ يَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا ﴿٢﴾ وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَٰحِبَةٗ وَلَا وَلَدٗا ﴿٣﴾ وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطٗا ﴿٤﴾ وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا ﴿٥﴾ وَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا ﴿٦﴾ وَأَنَّهُمۡ ظَنُّواْ كَمَا ظَنَنتُمۡ أَن لَّن يَبۡعَثَ ٱللَّهُ أَحَدٗا ﴿٧﴾", "w": [["أنه استمع", "إلى قراءتي."], ["نفر من الجن", "عدد من الجن ما بين الثلاثة والعشرة."], ["إنا سمعنا قرآناً عجباً", "قالوا لبعضهم: قرآناً يُتعجّب منه لفصاحته وغزارة معانيه."], ["يهدي إلى الرشد", "الصواب في المعتقد والقول والعمل."], ["وأنه تعالى جدّ ربنا", "تنزّه جلال ربنا وعظمته عما نُسب إليه."], ["ما اتخذ صاحبة ولا ولداً", "لم يتخذ صاحبة، ولم يكن له ولد."], ["سفيهنا", "جاهلنا."], ["شططاً", "غلوّاً في الكذب بوصفه الله تعالى بالصاحبة والولد."], ["على الله كذباً", "حتى تبيّن لنا أنهم يكذبون على الله بنسبة الزوجة والولد إليه."], ["يعوذون", "يستعيذون."], ["فزادوهم رهقاً", "إثماً وطغياناً."], ["أن لن يبعث الله أحداً", "لن يبعث رسولاً إلى خلقه."]], "m": "يأمر تعالى رسوله ﷺ أن يعلن للناس أن الله أوحى إليه أن نفراً من الجن استمعوا إلى قراءته القرآن ببطن نخلة وهو يصلي بأصحابه صلاة الفجر عامداً إلى سوق عكاظ، وكان قد حيل بين الشياطين وخبر السماء حيث أُرسلت عليهم الشهب، فانطلقوا يضربون في مشارق الأرض ومغاربها يتعرّفون هذا الحدث، فتوجّه نفر منهم إلى تهامة فوجدوا الرسول ﷺ يصلي الصبح فاستمعوا إلى قراءته، فرجعوا إلى قومهم فقالوا: إنا سمعنا قرآناً يُتعجّب من فصاحته وغزارة معانيه، يهدي إلى الصواب في العقيدة والقول والعمل، فآمنّا به ولن نشرك بربنا أحداً. وفي هذا تعريض بسخف البشر الذين عاش الرسول بينهم إحدى عشرة سنة يقرأ عليهم القرآن بمكة وهم مكذّبون، والجن بمجرد أن سمعوه آمنوا به وحملوا رسالته إلى قومهم. وقالوا: وآمنّا بأنه تعالى جلّ أمر ربنا وسلطانه، ما اتخذ صاحبة ولا ولداً، وأنه كان يقول جاهلنا على الله غلوّاً في الكذب بوصفه بالصاحبة والولد تقليداً للمشركين، وإنا كنا نظن أن الإنس والجن لا يكذبون على الله، وقد علمنا الآن أنهم يكذبون عليه. وأنه كان رجال من الإنس، من العرب وغيرهم، إذا نزلوا منزلاً مخوفاً في وادٍ يستعيذون برجال من الجن، كأن يقول الرجل: أعوذ بسيد هذا الوادي من سفهاء قومه، فزاد الإنس الجن بهذا اللجوء إليهم إثماً وطغياناً، إذ ما كانوا يطمعون أن تعظّمهم الإنس هذا التعظيم. وأن الإنس ظنّوا كما ظننتم أن لن يبعث الله رسولاً ينذر الناس عذابه ويعلّمهم ما يكمّلهم ويسعدهم.", "h": ["تقرير النبوة المحمدية، وأن محمداً رسول للثقلين الإنس والجن معاً.", "بيان علوّ شأن القرآن وكماله، حيث شهدت الجن له بأنه عجب فوق مستوى كلام الخلق.", "تقرير التوحيد والتنديد بالشرك.", "تقرير أن الإنس كالجن قد يكذبون على الله، وما كان لهم ذلك.", "حرمة الاستعانة بالجن والاستعاذة بهم، لأن ذلك كالعبادة لهم."], "k": "«إنا سمعنا قرآناً عجباً… فآمنّا به»… سمعوه مرة فآمنوا؛ وأنا أسمعه كل يوم، فماذا يتحرك فيّ؟"}, {"lbl": "الآيات ٨ – ١٥", "q": "وَأَنَّا لَمَسۡنَا ٱلسَّمَآءَ فَوَجَدۡنَٰهَا مُلِئَتۡ حَرَسٗا شَدِيدٗا وَشُهُبٗا ﴿٨﴾ وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَٰعِدَ لِلسَّمۡعِۖ فَمَن يَسۡتَمِعِ ٱلۡأٓنَ يَجِدۡ لَهُۥ شِهَابٗا رَّصَدٗا ﴿٩﴾ وَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا ﴿١٠﴾ وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا ﴿١١﴾ وَأَنَّا ظَنَنَّآ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِي ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبٗا ﴿١٢﴾ وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا ﴿١٣﴾ وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُوْلَـٰٓئِكَ تَحَرَّوۡاْ رَشَدٗا ﴿١٤﴾ وَأَمَّا ٱلۡقَٰسِطُونَ فَكَانُواْ لِجَهَنَّمَ حَطَبٗا ﴿١٥﴾", "w": [["حرساً شديداً", "ملائكة أقوياء يحرسونها."], ["وشهباً", "نجوماً يُرمى بها الشياطين، أو يُؤخذ منها شهاب فيُرمى به."], ["مقاعد للسمع", "من أجل أن نسمع ما يحدث وما يكون في الكون."], ["شهاباً رصداً", "أُرصد وأُعدّ لرمي الشياطين وإبعادهم عن السمع."], ["رشداً", "خيراً وصلاحاً."], ["كنا طرائق قدداً", "مذاهب مختلفة، والطرائق جمع طريقة، والقدد الضروب المختلفة."], ["ولن نعجزه هرباً", "لا نفوته هاربين في الأرض أو في السماء."], ["لما سمعنا الهدى", "القرآن الداعي إلى الهدى."], ["بخساً ولا رهقاً", "نقصاً من حسناته، ولا إثماً يُحمل عليه ويُحاسب به."], ["ومنا القاسطون", "الجائرون عن قصد السبيل، وهو الإسلام."], ["تحرّوا رشداً", "تعمّدوا الرشد فطلبوه بعناية فحصلوا عليه."], ["فكانوا لجهنم حطباً", "وقوداً تتّقد بهم يوم القيامة."]], "m": "ما زال السياق فيما قالته الجن بعد سماعها القرآن: وإنا طلبنا السماء كعادتنا فوجدناها مُلئت ملائكة أقوياء يحرسونها، وشهباً نارية يُرمى بها كل مسترق للسمع منا، وإنا كنا نقعد منها أماكن معيّنة للاستماع من ملائكة السماء، فمن يستمع الآن يجد له شهاباً أُرصد له خاصة فيُرمى به فيحرقه أو يخبله. وإنا لا ندري أشرّ أُريد بمن في الأرض أم أراد بهم ربهم رشداً؛ وعجباً لهؤلاء المؤمنين من الجن كيف تأدّبوا مع الله فلم ينسبوا إليه الشر ونسبوا إليه الخير، قالوا هذا لما وجدوا السماء قد مُلئت حرساً، وسبب ذلك أن الله لما نبّأ رسوله محمداً ﷺ حمى السماء حتى لا يسترق الشياطين السمع ويشوّشوا على الناس فيصرفوهم عن الإيمان. وإنا منا الصالحون المستقيمون على الإيمان والطاعة، ومنا دون ذلك ضعف إيمان وقلة طاعة، كنا مذاهب وأهواء مختلفة. وإنا علمنا أن لن نعجز الله في الأرض إن أراد بنا سوءاً، ولن نعجزه هرباً إن طلبنا. وإنا لما سمعنا القرآن آمنّا به، فمن يؤمن بربه فلا يخاف نقصاً من حسناته يوم القيامة، ولا إثماً يُضاف إلى سيئاته وهو لم يرتكبه. وإنا منا المسلمون، ومنا الجائرون عن الإسلام، فمن انقاد لله بطاعته وخلص من الشرك فأولئك تعمّدوا الرشد وفازوا به، وأما الجائرون فكانوا لجهنم حطباً.", "h": ["وجود تجانس بين الجن والملائكة لقرب مادّتي الخلق من بعضهما، إذ الملائكة خُلقوا من مادة النور، والجن من مادة النار، ولذا يرونهم ويسمعون كلامهم ويفهمونه.", "من الجن أدباء صالحون مؤمنون مسلمون أصحاب لرسول الله ﷺ.", "ذمّ الطرق والأهواء والاختلافات.", "الإشادة بالعدل وتحرّي الحق والخير."], "k": "«أشرّ أُريد بمن في الأرض أم أراد بهم ربهم رشداً»… تأدّبوا فلم ينسبوا الشر إليه؛ فكيف أتكلم أنا عن أقداره؟"}, {"lbl": "الآيات ١٦ – ٢٤", "q": "وَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا ﴿١٦﴾ لِّنَفۡتِنَهُمۡ فِيهِۚ وَمَن يُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ يَسۡلُكۡهُ عَذَابٗا صَعَدٗا ﴿١٧﴾ وَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا ﴿١٨﴾ وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ يَدۡعُوهُ كَادُواْ يَكُونُونَ عَلَيۡهِ لِبَدٗا ﴿١٩﴾ قُلۡ إِنَّمَآ أَدۡعُواْ رَبِّي وَلَآ أُشۡرِكُ بِهِۦٓ أَحَدٗا ﴿٢٠﴾ قُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا ﴿٢١﴾ قُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا ﴿٢٢﴾ إِلَّا بَلَٰغٗا مِّنَ ٱللَّهِ وَرِسَٰلَٰتِهِۦۚ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدًا ﴿٢٣﴾ حَتَّىٰٓ إِذَا رَأَوۡاْ مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرٗا وَأَقَلُّ عَدَدٗا ﴿٢٤﴾", "w": [["على الطريقة", "الإسلام."], ["ماءً غدقاً", "مالاً كثيراً وخيرات كبيرة."], ["لنفتنهم فيه", "نختبرهم أيشكرون أم يكفرون."], ["عن ذكر ربه", "القرآن وشرائعه وأحكامه."], ["عذاباً صعداً", "شاقّاً."], ["فلا تدعوا مع الله أحداً", "فيها مع الله أحداً."], ["عبد الله يدعوه", "محمد ﷺ يدعو الله ببطن نخلة."], ["عليه لبداً", "يركب بعضهم بعضاً تزاحماً لأجل أن يسمعوا قراءته."], ["ضرّاً ولا رشداً", "غيّاً ولا خيراً."], ["ملتحداً", "ملتجأً ألجأ إليه فأحفظ نفسي."], ["إلا بلاغاً", "لا أملك إلا البلاغ إليكم."], ["وأقل عدداً", "أعواناً، المسلمون أم الكافرون."]], "m": "وأُوحي إليّ أن لو استقام هؤلاء المشركون من كفار قريش، وهم يشكون القحط، على الإيمان والتوحيد والطاعة، لأسقيناهم ماءً غدقاً فتكثر أموالهم وتتّسع أرزاقهم، لنختبرهم في ذلك الخير أيشكرون أم يكفرون، فإن شكروا زادهم، وإن كفروا سلبهم وعذّبهم. ومن يعرض عن القرآن وما يدعو إليه نُدخله عذاباً شاقّاً، في الدنيا بالذل والمهانة والفقر، وفي الآخرة في جهنم. ومما أُوحي إليّ أن المساجد لله، فإذا دخلتموها للعبادة فلا تدعوا فيها مع الله أحداً، إذ كيف البيت له وأنت فيه وتدعو معه غيره؟ زيادة على أن الشرك محرّم، فإنه من غير الأدب أن يكون المرء في بيت كريم ويدعو معه غيره. وأُوحي إليّ أنه لما قام عبد الله ورسوله محمد ﷺ يدعو ربه في الصلاة ببطن نخلة كاد الجن يكونون عليه كالشيء المتلبّد بعضه فوق بعض. قل إنما أدعو ربي ولا أشرك به أحداً: إجابة لقريش عندما قالوا له: لقد جئت بأمر عظيم وعاديت الناس كلهم، فارجع عن هذا ونحن نجيرك. وأُمر أن يقول لهم: إني لا أملك لكم ضلالاً ولا هداية، إنما ذلك لله وحده، إني لن يجيرني من الله أحد إن أنا عصيته وأطعتكم، ولن أجد من دونه ملتجأً، إلا بلاغاً من الله ورسالاته، أبلّغكم عنه ما أمرني به. ومن يعصِ الله بالشرك ورسوله بتكذيبه فإن له نار جهنم خالدين فيها أبداً، فإن استمرّوا على شركهم حتى إذا رأوا ما يوعدون من عذاب يوم القيامة فسيعلمون عندئذ من أضعف ناصراً وأقل أعواناً: المؤمنون أم المشركون.", "h": ["الاستقامة على منهج الله تعالى القائم على الإيمان والطاعة لله ورسوله تفضي بسالكها إلى الخير الكثير والسعادة الكاملة في الدنيا والآخرة.", "المال فتنة، وقلّ من ينجح فيها، قال عمر رضي الله عنه: أينما يكون الماء يكون المال، وأينما يكون المال تكون الفتنة.", "حرمة دعاء غير الله في المساجد وفي غيرها، إلا أنها في المساجد أشد قبحاً.", "الخير والغيّ والهدى والضلال لا يملكها إلا الله، فليُطلب ذلك منه لا من غيره.", "معصية الله والرسول موجبة لعذاب الدنيا والآخرة."], "k": "«وأن المساجد لله فلا تدعوا مع الله أحداً»… في بيته، هل قلبي معه وحده أم مشغول بغيره؟"}, {"lbl": "الآيات ٢٥ – ٢٨", "q": "قُلۡ إِنۡ أَدۡرِيٓ أَقَرِيبٞ مَّا تُوعَدُونَ أَمۡ يَجۡعَلُ لَهُۥ رَبِّيٓ أَمَدًا ﴿٢٥﴾ عَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا ﴿٢٦﴾ إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ فَإِنَّهُۥ يَسۡلُكُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدٗا ﴿٢٧﴾ لِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا ﴿٢٨﴾", "w": [["قل إن أدري", "قل: ما أدري."], ["ما توعدون", "من العذاب."], ["أمداً", "غاية وأجلاً لا يعلمه إلا هو."], ["فلا يُظهر", "لا يُطلع."], ["إلا من ارتضى من رسول", "فإنه يطلعه."], ["يسلك من بين يديه ومن خلفه رصداً", "ملائكة يحفظونه حتى يبلّغ الوحي للناس."], ["ليعلم", "ليعلم ظهوراً أن الرسل قد بلّغوا رسالات ربهم."], ["وأحصى كل شيء عدداً", "أحصى عدد كل شيء."]], "m": "أمر تعالى رسوله أن يقول للمشركين المطالبين بالعذاب استخفافاً وتكذيباً: ما أدري أقريب ما توعدون من العذاب فيحلّ بكم عاجلاً، أم يجعل له ربي أجلاً بعيداً يعلمه هو ولا يعلمه غيره؟ هو عالم الغيب وحده، فلا يُطلع على غيبه أحداً من عباده، إلا من ارتضى من رسول أن يبلّغ عنه، فإنه يطلعه مع الاحتياط الكافي حتى لا يتسرّب الخبر إلى غيره، فإنه يسلك من بين يدي الرسول المرتضى ومن خلفه حرساً من الملائكة، حتى إنه إذا جاءه الوحي كان معه ملائكة يحمونه من الشياطين حتى لا يسمعوا خبر السماء فيبلّغوه أولياءهم من الإنس فتكون فتنة، ليعلم أن الرسل قبله قد بلّغت رسالات ربها لما أحاطها تعالى به من العناية، وأحاط الله بما لدى الملائكة والرسل علماً، وأحصى عدد كل شيء، فلا يخفى عليه شيء في الأرض ولا في السماء.", "h": ["استئثار الله تعالى بعلم الغيب، فلا يعلم الغيب إلا الله.", "قد يُطلع الله تعالى من ارتضى من الرسل على غيب خاص، ويتم ذلك بعد حماية كاملة من الشياطين كيلا ينقلوه إلى أوليائهم فيفتنوا به الناس.", "بيان إحاطة علم الله بكل شيء، وإحصائه تعالى لكل شيء عدداً."], "k": "«عالم الغيب فلا يُظهر على غيبه أحداً»… الغيب له وحده؛ فهل أطمئن لمن يدّعي معرفة ما سيكون؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (426, 73, 1, 20, 'سورة المزمل ١ – ٢٠', 'المزمل: قم الليل إلا قليلاً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 426) = $j$[{"lbl": "الآيات ١ – ٩", "q": "يَـٰٓأَيُّهَا ٱلۡمُزَّمِّلُ ﴿١﴾ قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا ﴿٢﴾ نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا ﴿٣﴾ أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا ﴿٤﴾ إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا ﴿٥﴾ إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا ﴿٦﴾ إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا ﴿٧﴾ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا ﴿٨﴾ رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا ﴿٩﴾", "w": [["يا أيها المزّمّل", "المتلفّف بثيابه، أي النبي ﷺ."], ["قم الليل", "صلِّ."], ["إلا قليلاً نصفه", "نصف الليل."], ["أو انقص منه قليلاً", "انقص من النصف إلى الثلث."], ["أو زد عليه", "إلى الثلثين، فأنت مخيّر في أيّها تفعل."], ["ورتّل القرآن ترتيلاً", "ترسّل في قراءته وبيّن حروفه."], ["إنا سنلقي عليك قولاً", "قرآناً."], ["ثقيلاً", "محمله ثقيل، والعمل به ثقيل لما يحوي من التكاليف."], ["إن ناشئة الليل", "ساعات الليل من صلاة العشاء فما فوق، كل ساعة تُسمّى ناشئة."], ["هي أشد وطئاً", "أقوى موافقة للسمع مع القلب على تفهّم القرآن فيها."], ["وأقوم قيلاً", "أبين قولاً وأصوب قراءة من قراءة النهار لسكون الأصوات."], ["واذكر اسم ربك", "دُم على ذكره ليلاً ونهاراً على أي وجه من تسبيح وتهليل."], ["وتبتّل إليه تبتيلاً", "انقطع إليه في العبادة وفي طلب الحاجة وفي كل ما يهمّك."], ["لا إله إلا هو", "لا معبود بحق سواه."], ["فاتّخذه وكيلاً", "فوّض جميع أمورك إليه فإنه يكفيك."]], "m": "نادى الرب تبارك وتعالى نبيه محمداً ﷺ مذكّراً إياه بتلك الساعة السعيدة التي فاجأه فيها الوحي لأول مرة، فرجع بها ترجف بوادره فانتهى إلى خديجة وهو يقول: زمّلوني دثّروني؛ فالمزّمّل هو المتلفّف في ثيابه، ليقول له: قم الليل إلا قليلاً، صلِّ نصفه أو انقص منه قليلاً إلى الثلث، أو زد عليه إلى الثلثين، فامتثل الرسول أمر ربه فقام مع أصحابه حتى تورّمت أقدامهم، ثم خفّف الله عنهم ونزل آخر هذه السورة بالرخصة في ترك القيام الواجب وبقي الندب والاستحباب. ورتّل القرآن ترتيلاً: يرشده إلى أحسن التلاوة وهي الترسّل وعدم السرعة حتى يبيّن الكلمات ويتدبّر القلب معانيها. إنا سنلقي عليك قولاً ثقيلاً هو القرآن، فإنه ثقيل مهيب ذو تكاليف ثقيلة، أعلمه ليوطّن نفسه على العمل ويهيّئها لحمل الشريعة علماً وعملاً ودعوة. إن ساعات الليل من بعد صلاة العشاء إلى آخره القيام فيها يجعل السمع يواطئ القلب على فهم معاني القرآن، وأبين قولاً وأصوب قراءة من قراءة النهار. إن لك في النهار أعمالاً تشغلك عن قراءة القرآن، فلذا أرشده إلى قيام الليل لتفرّغه من عمل النهار. واذكر اسم ربك داوماً على أي وجه من تسبيح وتحميد وتكبير وتهليل، وانقطع إليه في العبادة إخلاصاً له وفي طلب حوائجك وكل ما يهمّك، هو رب المشرق والمغرب لا إله إلا هو، فاتّخذه وكيلاً في كل ما يهمّك فإنه يكفيك.", "h": ["الندب إلى قيام الليل، وأنه دأب الصالحين وطريق المتقرّبين.", "الندب إلى ترتيل القرآن وترك العجلة في تلاوته.", "صلاة الليل أفضل من صلاة النهار لتواطؤ السمع والقلب فيها على فهم القرآن.", "الندب إلى ذكر الله تعالى بأي وجه من صلاة وتسبيح وطلب علم ودعاء وغير ذلك."], "k": "«إن ناشئة الليل هي أشد وطئاً وأقوم قيلاً»… ركعتان في الليل بقلب حاضر؛ متى آخر مرة جرّبتهما؟"}, {"lbl": "الآيات ١٠ – ١٩", "q": "وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا ﴿١٠﴾ وَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا ﴿١١﴾ إِنَّ لَدَيۡنَآ أَنكَالٗا وَجَحِيمٗا ﴿١٢﴾ وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا ﴿١٣﴾ يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِيبٗا مَّهِيلًا ﴿١٤﴾ إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا ﴿١٥﴾ فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَٰهُ أَخۡذٗا وَبِيلٗا ﴿١٦﴾ فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمٗا يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا ﴿١٧﴾ ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا ﴿١٨﴾ إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا ﴿١٩﴾", "w": [["واصبر على ما يقولون", "على ما يقوله لك كفار مكة من أذى، كقولهم: شاعر وساحر وكاذب."], ["واهجرهم هجراً جميلاً", "هجراً لا عتاب معه."], ["وذرني", "اتركني."], ["والمكذّبين", "صناديد قريش، فإني أكفيكهم."], ["أولي النعمة", "أهل التنعّم والترف."], ["ومهّلهم قليلاً", "انتظرهم قليلاً من الزمن حتى يهلكوا ببدر."], ["إن لدينا أنكالاً", "قيوداً من حديد."], ["وطعاماً ذا غُصّة", "يغصّ في الحلق، هو الزقوم والضريع."], ["يوم ترجف الأرض", "تتزلزل."], ["كثيباً مهيلاً", "رملاً مجتمعاً سائلاً بعد اجتماعه."], ["فأخذناه أخذاً وبيلاً", "ثقيلاً شديداً غليظاً."], ["فكيف تتّقون يوماً", "عذاب يوم يجعل الولدان لشدة هوله شيباً."], ["السماء منفطر به", "ذات انفطار وانشقاق بسبب هول ذلك اليوم."], ["كان وعده مفعولاً", "وعده تعالى بمجيء ذلك اليوم كائن لا محالة."], ["إن هذه تذكرة", "إن هذه الآيات المخوّفة عظة للناس."], ["اتّخذ إلى ربه سبيلاً", "طريقاً بالإيمان والطاعة إلى النجاة من النار ودخول الجنة."]], "m": "ما زال السياق في تربية الرسول ﷺ وأمّته بأنواع التربية الربانية: واصبر على ما يقوله كفار قريش من كلام يؤذونك به، كقولهم: ساحر وشاعر وكاهن ومجنون، واهجرهم هجراً جميلاً، وهو الذي لا عتاب معه، وذرني والمكذّبين من صناديد قريش أهل النعم والترف، وانظرهم ولا تستعجل فإني كافيكهم، ولم يمضِ إلا زمن يسير حتى هلكوا في بدر. إن عندنا للمكذّبين في الآخرة قيوداً من حديد، وناراً مستعرة، وطعاماً هو الزقوم والضريع يغصّ في حلق آكله، وعذاباً موجعاً، يوم تتحرّك الأرض والجبال وتضطرب، وكانت الجبال رملاً سائلاً بعد اجتماعه. إنا أرسلنا إليكم يا أهل مكة وكل من وراءها رسولاً شاهداً عليكم بما تعملون، كما أرسلنا إلى فرعون موسى ﵇، فعصى فرعون الرسول فأخذناه أخذاً غليظاً شديداً. فكيف تتّقون إن كفرتم عذاب يوم يجعل الولدان شيباً لهوله؟ وحسبه أن السماء منشقّة بسبب أهواله، وذلك يوم يقول الرب تعالى لآدم: يا آدم ابعث بعث النار، من كل ألف تسعمائة وتسعة وتسعين، هنا يشتد البلاء ويعظم الكرب. كان وعده بمجيء هذا اليوم كائناً لا محالة. إن هذه الآيات المشتملة على ذكر القيامة وأهوالها تذكرة وعظة، فمن شاء اتّخذ إلى ربه سبيلاً، وهي الإيمان والعمل الصالح بعد التخلّي عن الشرك والمعاصي.", "h": ["وجوب الصبر على الطاعة وعن المعصية.", "الهجر الجميل هو الذي لا عتاب فيه.", "تقرير البعث والجزاء."], "k": "«واهجرهم هجراً جميلاً»… حين أبتعد عن أحد، هل أبتعد بلا عتاب ولا أذى؟"}, {"lbl": "الآية ٢٠", "q": "۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ ﴿٢٠﴾", "w": [["أنك تقوم", "للتهجّد."], ["وطائفة من الذين معك", "وطائفة من أصحابك تقوم كذلك."], ["والله يقدّر الليل والنهار", "يحصيهما ويعلم ما يمضي من ساعات كل منهما وما يبقى."], ["علم أن لن تُحصوه", "الليل، فلا تطيقون قيامه كله لأنه يشق عليكم."], ["فتاب عليكم", "رجع بكم إلى التخفيف في قيام الليل."], ["فاقرؤوا ما تيسّر", "صلّوا من الليل ما سهل عليكم ولو ركعتين."], ["وأقيموا الصلاة", "المفروضة."], ["وآتوا الزكاة", "المفروضة."], ["وأقرضوا الله قرضاً حسناً", "تصدّقوا بفضول أموالكم طيبة بها نفوسكم."], ["وما تقدّموا لأنفسكم من خير", "من نوافل العبادة من صلاة وصدقة وصيام وحج وغيرها."]], "m": "كان الرسول ﷺ وأصحابه يقومون أدنى من ثلثي الليل، ويقومون أحياناً النصف والثلث، كما في أول السورة، وهو معنى قوله: إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك. والله يحصي ساعات الليل والنهار، علم أن لن تطيقوا ضبط ساعاته، فيشق عليكم قيام أكثره تحرّياً لما هو المطلوب، فتاب عليكم، وبهذا نُسخ قيام الليل الواجب وبقي المستحب ولو بركعتين في أي جزء من الليل، فاقرؤوا ما تيسّر من القرآن، أي صلّوا ما تيسّر. ثم ذكر أعذاراً ثلاثة: المرض، والضرب في الأرض للتجارة، والجهاد في سبيل الله، وكلها يشق معها قيام الليل، فرحمة بالمؤمنين نسخ هذا الحكم الشاق، وكرّر: فاقرؤوا ما تيسّر منه، تأكيداً لنسخ قيام الليل الذي كان واجباً وأصبح مندوباً. وأقيموا الصلاة وآتوا الزكاة المفروضتين، وأنفقوا في سبيل الله، وما تقدّموا لأنفسكم من نوافل الصلاة والصدقات والحج وسائر العبادات تجدوه عند الله يوم القيامة هو خيراً وأعظم أجراً، واستغفروا الله من كل ما يفرط منكم من تقصير، إن الله غفور لمن تاب، رحيم به فلا يؤاخذه بذنب قد تاب منه.", "h": ["بيان ما كان الرسول ﷺ وأصحابه يقومونه من الليل تهجّداً.", "نسخ واجب قيام الليل، وبقاء استحبابه وندبه.", "وجوب إقام الصلاة وإيتاء الزكاة.", "الترغيب في التطوّع من سائر العبادات.", "وجوب الاستغفار عند الذنب، وندبه واستحبابه في سائر الأوقات لما يحصل من التقصير."], "k": "«وما تقدّموا لأنفسكم من خير تجدوه عند الله»… كل خير صغير محفوظ هناك؛ فماذا أودعت اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 426;
insert into public.tdb_cards(topic, i, body) select 426, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٩", "q": "يَـٰٓأَيُّهَا ٱلۡمُزَّمِّلُ ﴿١﴾ قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا ﴿٢﴾ نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا ﴿٣﴾ أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا ﴿٤﴾ إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا ﴿٥﴾ إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا ﴿٦﴾ إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا ﴿٧﴾ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا ﴿٨﴾ رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا ﴿٩﴾", "w": [["يا أيها المزّمّل", "المتلفّف بثيابه، أي النبي ﷺ."], ["قم الليل", "صلِّ."], ["إلا قليلاً نصفه", "نصف الليل."], ["أو انقص منه قليلاً", "انقص من النصف إلى الثلث."], ["أو زد عليه", "إلى الثلثين، فأنت مخيّر في أيّها تفعل."], ["ورتّل القرآن ترتيلاً", "ترسّل في قراءته وبيّن حروفه."], ["إنا سنلقي عليك قولاً", "قرآناً."], ["ثقيلاً", "محمله ثقيل، والعمل به ثقيل لما يحوي من التكاليف."], ["إن ناشئة الليل", "ساعات الليل من صلاة العشاء فما فوق، كل ساعة تُسمّى ناشئة."], ["هي أشد وطئاً", "أقوى موافقة للسمع مع القلب على تفهّم القرآن فيها."], ["وأقوم قيلاً", "أبين قولاً وأصوب قراءة من قراءة النهار لسكون الأصوات."], ["واذكر اسم ربك", "دُم على ذكره ليلاً ونهاراً على أي وجه من تسبيح وتهليل."], ["وتبتّل إليه تبتيلاً", "انقطع إليه في العبادة وفي طلب الحاجة وفي كل ما يهمّك."], ["لا إله إلا هو", "لا معبود بحق سواه."], ["فاتّخذه وكيلاً", "فوّض جميع أمورك إليه فإنه يكفيك."]], "m": "نادى الرب تبارك وتعالى نبيه محمداً ﷺ مذكّراً إياه بتلك الساعة السعيدة التي فاجأه فيها الوحي لأول مرة، فرجع بها ترجف بوادره فانتهى إلى خديجة وهو يقول: زمّلوني دثّروني؛ فالمزّمّل هو المتلفّف في ثيابه، ليقول له: قم الليل إلا قليلاً، صلِّ نصفه أو انقص منه قليلاً إلى الثلث، أو زد عليه إلى الثلثين، فامتثل الرسول أمر ربه فقام مع أصحابه حتى تورّمت أقدامهم، ثم خفّف الله عنهم ونزل آخر هذه السورة بالرخصة في ترك القيام الواجب وبقي الندب والاستحباب. ورتّل القرآن ترتيلاً: يرشده إلى أحسن التلاوة وهي الترسّل وعدم السرعة حتى يبيّن الكلمات ويتدبّر القلب معانيها. إنا سنلقي عليك قولاً ثقيلاً هو القرآن، فإنه ثقيل مهيب ذو تكاليف ثقيلة، أعلمه ليوطّن نفسه على العمل ويهيّئها لحمل الشريعة علماً وعملاً ودعوة. إن ساعات الليل من بعد صلاة العشاء إلى آخره القيام فيها يجعل السمع يواطئ القلب على فهم معاني القرآن، وأبين قولاً وأصوب قراءة من قراءة النهار. إن لك في النهار أعمالاً تشغلك عن قراءة القرآن، فلذا أرشده إلى قيام الليل لتفرّغه من عمل النهار. واذكر اسم ربك داوماً على أي وجه من تسبيح وتحميد وتكبير وتهليل، وانقطع إليه في العبادة إخلاصاً له وفي طلب حوائجك وكل ما يهمّك، هو رب المشرق والمغرب لا إله إلا هو، فاتّخذه وكيلاً في كل ما يهمّك فإنه يكفيك.", "h": ["الندب إلى قيام الليل، وأنه دأب الصالحين وطريق المتقرّبين.", "الندب إلى ترتيل القرآن وترك العجلة في تلاوته.", "صلاة الليل أفضل من صلاة النهار لتواطؤ السمع والقلب فيها على فهم القرآن.", "الندب إلى ذكر الله تعالى بأي وجه من صلاة وتسبيح وطلب علم ودعاء وغير ذلك."], "k": "«إن ناشئة الليل هي أشد وطئاً وأقوم قيلاً»… ركعتان في الليل بقلب حاضر؛ متى آخر مرة جرّبتهما؟"}, {"lbl": "الآيات ١٠ – ١٩", "q": "وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا ﴿١٠﴾ وَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا ﴿١١﴾ إِنَّ لَدَيۡنَآ أَنكَالٗا وَجَحِيمٗا ﴿١٢﴾ وَطَعَامٗا ذَا غُصَّةٖ وَعَذَابًا أَلِيمٗا ﴿١٣﴾ يَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِيبٗا مَّهِيلًا ﴿١٤﴾ إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا ﴿١٥﴾ فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَٰهُ أَخۡذٗا وَبِيلٗا ﴿١٦﴾ فَكَيۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ يَوۡمٗا يَجۡعَلُ ٱلۡوِلۡدَٰنَ شِيبًا ﴿١٧﴾ ٱلسَّمَآءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا ﴿١٨﴾ إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا ﴿١٩﴾", "w": [["واصبر على ما يقولون", "على ما يقوله لك كفار مكة من أذى، كقولهم: شاعر وساحر وكاذب."], ["واهجرهم هجراً جميلاً", "هجراً لا عتاب معه."], ["وذرني", "اتركني."], ["والمكذّبين", "صناديد قريش، فإني أكفيكهم."], ["أولي النعمة", "أهل التنعّم والترف."], ["ومهّلهم قليلاً", "انتظرهم قليلاً من الزمن حتى يهلكوا ببدر."], ["إن لدينا أنكالاً", "قيوداً من حديد."], ["وطعاماً ذا غُصّة", "يغصّ في الحلق، هو الزقوم والضريع."], ["يوم ترجف الأرض", "تتزلزل."], ["كثيباً مهيلاً", "رملاً مجتمعاً سائلاً بعد اجتماعه."], ["فأخذناه أخذاً وبيلاً", "ثقيلاً شديداً غليظاً."], ["فكيف تتّقون يوماً", "عذاب يوم يجعل الولدان لشدة هوله شيباً."], ["السماء منفطر به", "ذات انفطار وانشقاق بسبب هول ذلك اليوم."], ["كان وعده مفعولاً", "وعده تعالى بمجيء ذلك اليوم كائن لا محالة."], ["إن هذه تذكرة", "إن هذه الآيات المخوّفة عظة للناس."], ["اتّخذ إلى ربه سبيلاً", "طريقاً بالإيمان والطاعة إلى النجاة من النار ودخول الجنة."]], "m": "ما زال السياق في تربية الرسول ﷺ وأمّته بأنواع التربية الربانية: واصبر على ما يقوله كفار قريش من كلام يؤذونك به، كقولهم: ساحر وشاعر وكاهن ومجنون، واهجرهم هجراً جميلاً، وهو الذي لا عتاب معه، وذرني والمكذّبين من صناديد قريش أهل النعم والترف، وانظرهم ولا تستعجل فإني كافيكهم، ولم يمضِ إلا زمن يسير حتى هلكوا في بدر. إن عندنا للمكذّبين في الآخرة قيوداً من حديد، وناراً مستعرة، وطعاماً هو الزقوم والضريع يغصّ في حلق آكله، وعذاباً موجعاً، يوم تتحرّك الأرض والجبال وتضطرب، وكانت الجبال رملاً سائلاً بعد اجتماعه. إنا أرسلنا إليكم يا أهل مكة وكل من وراءها رسولاً شاهداً عليكم بما تعملون، كما أرسلنا إلى فرعون موسى ﵇، فعصى فرعون الرسول فأخذناه أخذاً غليظاً شديداً. فكيف تتّقون إن كفرتم عذاب يوم يجعل الولدان شيباً لهوله؟ وحسبه أن السماء منشقّة بسبب أهواله، وذلك يوم يقول الرب تعالى لآدم: يا آدم ابعث بعث النار، من كل ألف تسعمائة وتسعة وتسعين، هنا يشتد البلاء ويعظم الكرب. كان وعده بمجيء هذا اليوم كائناً لا محالة. إن هذه الآيات المشتملة على ذكر القيامة وأهوالها تذكرة وعظة، فمن شاء اتّخذ إلى ربه سبيلاً، وهي الإيمان والعمل الصالح بعد التخلّي عن الشرك والمعاصي.", "h": ["وجوب الصبر على الطاعة وعن المعصية.", "الهجر الجميل هو الذي لا عتاب فيه.", "تقرير البعث والجزاء."], "k": "«واهجرهم هجراً جميلاً»… حين أبتعد عن أحد، هل أبتعد بلا عتاب ولا أذى؟"}, {"lbl": "الآية ٢٠", "q": "۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ ﴿٢٠﴾", "w": [["أنك تقوم", "للتهجّد."], ["وطائفة من الذين معك", "وطائفة من أصحابك تقوم كذلك."], ["والله يقدّر الليل والنهار", "يحصيهما ويعلم ما يمضي من ساعات كل منهما وما يبقى."], ["علم أن لن تُحصوه", "الليل، فلا تطيقون قيامه كله لأنه يشق عليكم."], ["فتاب عليكم", "رجع بكم إلى التخفيف في قيام الليل."], ["فاقرؤوا ما تيسّر", "صلّوا من الليل ما سهل عليكم ولو ركعتين."], ["وأقيموا الصلاة", "المفروضة."], ["وآتوا الزكاة", "المفروضة."], ["وأقرضوا الله قرضاً حسناً", "تصدّقوا بفضول أموالكم طيبة بها نفوسكم."], ["وما تقدّموا لأنفسكم من خير", "من نوافل العبادة من صلاة وصدقة وصيام وحج وغيرها."]], "m": "كان الرسول ﷺ وأصحابه يقومون أدنى من ثلثي الليل، ويقومون أحياناً النصف والثلث، كما في أول السورة، وهو معنى قوله: إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك. والله يحصي ساعات الليل والنهار، علم أن لن تطيقوا ضبط ساعاته، فيشق عليكم قيام أكثره تحرّياً لما هو المطلوب، فتاب عليكم، وبهذا نُسخ قيام الليل الواجب وبقي المستحب ولو بركعتين في أي جزء من الليل، فاقرؤوا ما تيسّر من القرآن، أي صلّوا ما تيسّر. ثم ذكر أعذاراً ثلاثة: المرض، والضرب في الأرض للتجارة، والجهاد في سبيل الله، وكلها يشق معها قيام الليل، فرحمة بالمؤمنين نسخ هذا الحكم الشاق، وكرّر: فاقرؤوا ما تيسّر منه، تأكيداً لنسخ قيام الليل الذي كان واجباً وأصبح مندوباً. وأقيموا الصلاة وآتوا الزكاة المفروضتين، وأنفقوا في سبيل الله، وما تقدّموا لأنفسكم من نوافل الصلاة والصدقات والحج وسائر العبادات تجدوه عند الله يوم القيامة هو خيراً وأعظم أجراً، واستغفروا الله من كل ما يفرط منكم من تقصير، إن الله غفور لمن تاب، رحيم به فلا يؤاخذه بذنب قد تاب منه.", "h": ["بيان ما كان الرسول ﷺ وأصحابه يقومونه من الليل تهجّداً.", "نسخ واجب قيام الليل، وبقاء استحبابه وندبه.", "وجوب إقام الصلاة وإيتاء الزكاة.", "الترغيب في التطوّع من سائر العبادات.", "وجوب الاستغفار عند الذنب، وندبه واستحبابه في سائر الأوقات لما يحصل من التقصير."], "k": "«وما تقدّموا لأنفسكم من خير تجدوه عند الله»… كل خير صغير محفوظ هناك؛ فماذا أودعت اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (427, 74, 1, 30, 'سورة المدثر ١ – ٣٠', 'المدثر: قم فأنذر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 427) = $j$[{"lbl": "الآيات ١ – ١٠", "q": "يَـٰٓأَيُّهَا ٱلۡمُدَّثِّرُ ﴿١﴾ قُمۡ فَأَنذِرۡ ﴿٢﴾ وَرَبَّكَ فَكَبِّرۡ ﴿٣﴾ وَثِيَابَكَ فَطَهِّرۡ ﴿٤﴾ وَٱلرُّجۡزَ فَٱهۡجُرۡ ﴿٥﴾ وَلَا تَمۡنُن تَسۡتَكۡثِرُ ﴿٦﴾ وَلِرَبِّكَ فَٱصۡبِرۡ ﴿٧﴾ فَإِذَا نُقِرَ فِي ٱلنَّاقُورِ ﴿٨﴾ فَذَٰلِكَ يَوۡمَئِذٖ يَوۡمٌ عَسِيرٌ ﴿٩﴾ عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرٖ ﴿١٠﴾", "w": [["يا أيها المدّثّر", "المتلفّف في ثيابه، وهو النبي ﷺ."], ["قم فأنذر", "خوّف أهل مكة النار إن لم يؤمنوا ويوحّدوا."], ["وربك فكبّر", "عظّم ربك عن إشراك المشركين."], ["وثيابك فطهّر", "طهّر ثيابك من النجاسات."], ["والرجز فاهجر", "أدم هجرانك للأوثان."], ["ولا تمنن تستكثر", "لا تمنن على ربك ما تقوم به من أعمال لأجله طاعة له."], ["فإذا نُقر في الناقور", "نُفخ في الصور النفخة الثانية."]], "m": "روى الزهري أنه فتر الوحي عن رسول الله ﷺ فترة فحزن حزناً، وكان ﷺ يحدّث فيقول: «بينما أنا أمشي يوماً إذ رأيت الملك الذي كان يأتيني بحراء على كرسي بين السماء والأرض، فجئثت منه رعباً، فرجعت إلى خديجة فقلت: زمّلوني»، فدثّروه، فأنزل الله: يا أيها المدّثّر قم فأنذر وربك فكبّر وثيابك فطهّر. فهذا النداء كان بعد فترة الوحي الأولى، ناداه بهذا اللقب الجميل تكريماً وتلطّفاً معه ليقوم بأعباء الدعوة، وما أشد ثقلها. يا أيها المدّثّر في ثيابه، قم فأنذر، لم يبقَ لك مجال للنوم والراحة، فأنذر قومك في مكة وكل الثقلين من ورائها عذاب النار المترتّب على الكفر والشرك. وربك فعظّمه تعظيماً يليق بجلاله، فإنه الأكبر الذي لا أكبر منه، فأعلن ذلك بلسانك قائلاً: الله أكبر، وبحالك فلا تذل إلا له ولا ترغب إلا فيه، وبأعمالك فلا تأتِ منها إلا ما أذن لك فيه. وثيابك فطهّرها من النجاسات مخالفاً ما عليه قومك، إذ يجرّون ثيابهم ولا يتنزّهون من أبوالهم. والأصنام التي يعبدها قومك فاهجرها ودُم على هجرانها. ولا تمنن على ربك بما تقوم به من أعمال تستكثرها، ولا تطلب على دعوتك أجراً، ولا تمنن عطاءً أعطيته لغيرك تستكثر به، إن ذلك منافٍ لأجمل الأخلاق. ولربك وحده فاصبر على كل ما تلقاه في سبيل إبلاغ رسالتك. فإذا نُقر في الناقور، وهو البوق الذي ينفخ فيه إسرافيل النفخة الثانية نفخة البعث، فذلك يومئذ يوم عسير صعب شديد على الكافرين غير يسير، فذكّر به من تدعوهم، فإن التذكير به نافع، إذ الإيمان بالله واليوم الآخر محور العقيدة، وعليهما مدار الإصلاح والهداية.", "h": ["الجدّ طابع المسلم، فلا كسل ولا خمول ولا لهو ولا لعب، ومن فارق هذه فليتّهم نفسه.", "وجوب تعظيم أسماء الله وصفاته، وتعظيم كلامه وكتابه، وتعظيم شعائره.", "وجوب الطهارة للمؤمن بدناً وثوباً ومسجداً، أكلاً وشرباً وفراشاً، ونفساً وروحاً.", "حرمة العُجب، فلا يعجب المؤمن بعمله ولا يزكّي به نفسه ولو صام الدهر.", "وجوب الصبر على الطاعات فعلاً، وعلى المعاصي تركاً، وعلى البلاء تسليماً ورضاً."], "k": "«ولا تمنن تستكثر»… أحياناً أرى عملي كثيراً؛ فهل أنسى أن كل خير مني هو من فضله أصلاً؟"}, {"lbl": "الآيات ١١ – ٣٠", "q": "ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدٗا ﴿١١﴾ وَجَعَلۡتُ لَهُۥ مَالٗا مَّمۡدُودٗا ﴿١٢﴾ وَبَنِينَ شُهُودٗا ﴿١٣﴾ وَمَهَّدتُّ لَهُۥ تَمۡهِيدٗا ﴿١٤﴾ ثُمَّ يَطۡمَعُ أَنۡ أَزِيدَ ﴿١٥﴾ كَلَّآۖ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيدٗا ﴿١٦﴾ سَأُرۡهِقُهُۥ صَعُودًا ﴿١٧﴾ إِنَّهُۥ فَكَّرَ وَقَدَّرَ ﴿١٨﴾ فَقُتِلَ كَيۡفَ قَدَّرَ ﴿١٩﴾ ثُمَّ قُتِلَ كَيۡفَ قَدَّرَ ﴿٢٠﴾ ثُمَّ نَظَرَ ﴿٢١﴾ ثُمَّ عَبَسَ وَبَسَرَ ﴿٢٢﴾ ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ ﴿٢٣﴾ فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ يُؤۡثَرُ ﴿٢٤﴾ إِنۡ هَٰذَآ إِلَّا قَوۡلُ ٱلۡبَشَرِ ﴿٢٥﴾ سَأُصۡلِيهِ سَقَرَ ﴿٢٦﴾ وَمَآ أَدۡرَىٰكَ مَا سَقَرُ ﴿٢٧﴾ لَا تُبۡقِي وَلَا تَذَرُ ﴿٢٨﴾ لَوَّاحَةٞ لِّلۡبَشَرِ ﴿٢٩﴾ عَلَيۡهَا تِسۡعَةَ عَشَرَ ﴿٣٠﴾", "w": [["ذرني ومن خلقت وحيداً", "اتركني ومن خلقته منفرداً بلا مال ولا ولد، فأنا أكفيكه."], ["وبنين شهوداً", "يشهدون المحافل وتُسمع شهادتهم، حاضرون معه أغلب الوقت."], ["ومهّدت له تمهيداً", "بسطت له في العيش والعمر والولد والجاه حتى كان يُلقّب بريحانة قريش."], ["عنيداً", "معانداً، وهو الوليد بن المغيرة المخزومي."], ["سأرهقه صعوداً", "سأكلّفه يوم القيامة صعود جبل من نار، كلما صعد فيه هوى."], ["إنه فكّر وقدّر", "فيما يقول في القرآن الذي سمعه من النبي ﷺ، وقدّر في نفسه."], ["ثم نظر ثم عبس وبسر", "تروّى في ذلك، ثم قبض ما بين عينيه، ثم كلح وجهه."], ["ثم أدبر واستكبر", "أدبر عن الإيمان، واستكبر عن اتّباع الرسول ﷺ."], ["سحر يؤثر", "يُنقل عن السحرة."], ["سأصليه سقر", "سأدخله جهنم، وسقر اسم لها."], ["لا تبقي ولا تذر", "لا تترك شيئاً من اللحم ولا العصب إلا أهلكته، ثم يعود كما كان لإدامة العذاب."], ["لوّاحة للبشر", "محرقة مسوّدة لظاهر جلد الإنسان، وهو بشرته."], ["عليها تسعة عشر", "ملكاً، وهم خزنتها."]], "m": "لقد تحمّل رسول الله ﷺ عبء الدعوة وشرع في إنذار قومه، فأعلمهم أنه لا إله إلا الله وأنه رسول الله، فتصدّى له طاغية من أعظم الطغاة ساد الوادي مالاً وولداً وجاهاً حتى لُقّب بريحانة قريش، هو الوليد بن المغيرة، صاحب عشرة رجال من صلبه وآلاف الدنانير من الذهب، فقال له ربه: دعني والذي خلقته وحيداً بلا مال ولا ولد، وجعلت له مالاً ممدوداً واسعاً تمدّه به الزراعة والتجارة، وبنين حاضرين لا يغيبون، يشهدون المحافل، ومهّدت له في العيش والعمر والجاه، ثم يطمع أن أزيده؟ كلا، لن أزيده بعد اليوم، إنه كان لآياتنا القرآنية معانداً يحاول إبطالها، سأكلّفه عذاباً شاقّاً لا قبل له به، وهو جبل من نار يُكلّف صعوده. إنه فكّر فيما يقول في القرآن لما طلبت منه قريش أن يقول فيه، وقدّر في نفسه، فقُتل كيف قدّر، أي لُعن، ثم قُتل كيف قدّر، ثم تروّى، ثم قطّب ما بين عينيه، وكلح وجهه، ثم أدبر عن الإيمان واستكبر، فقال نتيجة تفكيره: ما هذا القرآن إلا سحر يُنقل عن السحرة، ما هذا إلا قول البشر. قال تعالى متوعّداً إياه: سأدخله سقر، وما أدراك ما سقر؟ إنها عظيمة، لا تُبقي لحماً ولا تذر عصباً، تحرق الجلود وتسوّدها، عليها تسعة عشر ملكاً هم خزنتها. ولنزول هذه الآيات سبب: أن قريشاً اتّهمت الوليد بأنه مال إلى دين محمد، فأنكر وحلف، فطلبوا إليه أن يقول في القرآن كلمة يصرف بها العرب عنه، فذهب إلى رسول الله ﷺ وهو يصلي فاستمع إليه، وقد وصف القرآن من قبل بقوله: والله إن لقوله لحلاوة، وإنه ليعلو ولا يُعلى، فقالوا: والله لا يرضى عنك قومك حتى تقول فيه، فقال: دعوني حتى أفكّر، ففكّر وقال ما تقدّم، فنزلت هذه الآيات.", "h": ["المال والبنون والجاه من عوامل الطغيان، إلا أن يسلّم الله عبده من فتنتها.", "من أكفر الناس من يعاند في آيات الله، يريد صرف الناس عنها وإبطال هدايتها.", "بيان ما ظفر به طاغية قريش الوليد بن المغيرة من لعنة وعذاب شديد.", "تقرير الوحي، وإثبات النبوة المحمدية.", "تقرير البعث والجزاء."], "k": "«إنه فكّر وقدّر»… فكّر طويلاً ثم اختار الكبر؛ فهل يقودني تفكيري إلى الحق أم إلى ما أشتهي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 427;
insert into public.tdb_cards(topic, i, body) select 427, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٠", "q": "يَـٰٓأَيُّهَا ٱلۡمُدَّثِّرُ ﴿١﴾ قُمۡ فَأَنذِرۡ ﴿٢﴾ وَرَبَّكَ فَكَبِّرۡ ﴿٣﴾ وَثِيَابَكَ فَطَهِّرۡ ﴿٤﴾ وَٱلرُّجۡزَ فَٱهۡجُرۡ ﴿٥﴾ وَلَا تَمۡنُن تَسۡتَكۡثِرُ ﴿٦﴾ وَلِرَبِّكَ فَٱصۡبِرۡ ﴿٧﴾ فَإِذَا نُقِرَ فِي ٱلنَّاقُورِ ﴿٨﴾ فَذَٰلِكَ يَوۡمَئِذٖ يَوۡمٌ عَسِيرٌ ﴿٩﴾ عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرٖ ﴿١٠﴾", "w": [["يا أيها المدّثّر", "المتلفّف في ثيابه، وهو النبي ﷺ."], ["قم فأنذر", "خوّف أهل مكة النار إن لم يؤمنوا ويوحّدوا."], ["وربك فكبّر", "عظّم ربك عن إشراك المشركين."], ["وثيابك فطهّر", "طهّر ثيابك من النجاسات."], ["والرجز فاهجر", "أدم هجرانك للأوثان."], ["ولا تمنن تستكثر", "لا تمنن على ربك ما تقوم به من أعمال لأجله طاعة له."], ["فإذا نُقر في الناقور", "نُفخ في الصور النفخة الثانية."]], "m": "روى الزهري أنه فتر الوحي عن رسول الله ﷺ فترة فحزن حزناً، وكان ﷺ يحدّث فيقول: «بينما أنا أمشي يوماً إذ رأيت الملك الذي كان يأتيني بحراء على كرسي بين السماء والأرض، فجئثت منه رعباً، فرجعت إلى خديجة فقلت: زمّلوني»، فدثّروه، فأنزل الله: يا أيها المدّثّر قم فأنذر وربك فكبّر وثيابك فطهّر. فهذا النداء كان بعد فترة الوحي الأولى، ناداه بهذا اللقب الجميل تكريماً وتلطّفاً معه ليقوم بأعباء الدعوة، وما أشد ثقلها. يا أيها المدّثّر في ثيابه، قم فأنذر، لم يبقَ لك مجال للنوم والراحة، فأنذر قومك في مكة وكل الثقلين من ورائها عذاب النار المترتّب على الكفر والشرك. وربك فعظّمه تعظيماً يليق بجلاله، فإنه الأكبر الذي لا أكبر منه، فأعلن ذلك بلسانك قائلاً: الله أكبر، وبحالك فلا تذل إلا له ولا ترغب إلا فيه، وبأعمالك فلا تأتِ منها إلا ما أذن لك فيه. وثيابك فطهّرها من النجاسات مخالفاً ما عليه قومك، إذ يجرّون ثيابهم ولا يتنزّهون من أبوالهم. والأصنام التي يعبدها قومك فاهجرها ودُم على هجرانها. ولا تمنن على ربك بما تقوم به من أعمال تستكثرها، ولا تطلب على دعوتك أجراً، ولا تمنن عطاءً أعطيته لغيرك تستكثر به، إن ذلك منافٍ لأجمل الأخلاق. ولربك وحده فاصبر على كل ما تلقاه في سبيل إبلاغ رسالتك. فإذا نُقر في الناقور، وهو البوق الذي ينفخ فيه إسرافيل النفخة الثانية نفخة البعث، فذلك يومئذ يوم عسير صعب شديد على الكافرين غير يسير، فذكّر به من تدعوهم، فإن التذكير به نافع، إذ الإيمان بالله واليوم الآخر محور العقيدة، وعليهما مدار الإصلاح والهداية.", "h": ["الجدّ طابع المسلم، فلا كسل ولا خمول ولا لهو ولا لعب، ومن فارق هذه فليتّهم نفسه.", "وجوب تعظيم أسماء الله وصفاته، وتعظيم كلامه وكتابه، وتعظيم شعائره.", "وجوب الطهارة للمؤمن بدناً وثوباً ومسجداً، أكلاً وشرباً وفراشاً، ونفساً وروحاً.", "حرمة العُجب، فلا يعجب المؤمن بعمله ولا يزكّي به نفسه ولو صام الدهر.", "وجوب الصبر على الطاعات فعلاً، وعلى المعاصي تركاً، وعلى البلاء تسليماً ورضاً."], "k": "«ولا تمنن تستكثر»… أحياناً أرى عملي كثيراً؛ فهل أنسى أن كل خير مني هو من فضله أصلاً؟"}, {"lbl": "الآيات ١١ – ٣٠", "q": "ذَرۡنِي وَمَنۡ خَلَقۡتُ وَحِيدٗا ﴿١١﴾ وَجَعَلۡتُ لَهُۥ مَالٗا مَّمۡدُودٗا ﴿١٢﴾ وَبَنِينَ شُهُودٗا ﴿١٣﴾ وَمَهَّدتُّ لَهُۥ تَمۡهِيدٗا ﴿١٤﴾ ثُمَّ يَطۡمَعُ أَنۡ أَزِيدَ ﴿١٥﴾ كَلَّآۖ إِنَّهُۥ كَانَ لِأٓيَٰتِنَا عَنِيدٗا ﴿١٦﴾ سَأُرۡهِقُهُۥ صَعُودًا ﴿١٧﴾ إِنَّهُۥ فَكَّرَ وَقَدَّرَ ﴿١٨﴾ فَقُتِلَ كَيۡفَ قَدَّرَ ﴿١٩﴾ ثُمَّ قُتِلَ كَيۡفَ قَدَّرَ ﴿٢٠﴾ ثُمَّ نَظَرَ ﴿٢١﴾ ثُمَّ عَبَسَ وَبَسَرَ ﴿٢٢﴾ ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ ﴿٢٣﴾ فَقَالَ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ يُؤۡثَرُ ﴿٢٤﴾ إِنۡ هَٰذَآ إِلَّا قَوۡلُ ٱلۡبَشَرِ ﴿٢٥﴾ سَأُصۡلِيهِ سَقَرَ ﴿٢٦﴾ وَمَآ أَدۡرَىٰكَ مَا سَقَرُ ﴿٢٧﴾ لَا تُبۡقِي وَلَا تَذَرُ ﴿٢٨﴾ لَوَّاحَةٞ لِّلۡبَشَرِ ﴿٢٩﴾ عَلَيۡهَا تِسۡعَةَ عَشَرَ ﴿٣٠﴾", "w": [["ذرني ومن خلقت وحيداً", "اتركني ومن خلقته منفرداً بلا مال ولا ولد، فأنا أكفيكه."], ["وبنين شهوداً", "يشهدون المحافل وتُسمع شهادتهم، حاضرون معه أغلب الوقت."], ["ومهّدت له تمهيداً", "بسطت له في العيش والعمر والولد والجاه حتى كان يُلقّب بريحانة قريش."], ["عنيداً", "معانداً، وهو الوليد بن المغيرة المخزومي."], ["سأرهقه صعوداً", "سأكلّفه يوم القيامة صعود جبل من نار، كلما صعد فيه هوى."], ["إنه فكّر وقدّر", "فيما يقول في القرآن الذي سمعه من النبي ﷺ، وقدّر في نفسه."], ["ثم نظر ثم عبس وبسر", "تروّى في ذلك، ثم قبض ما بين عينيه، ثم كلح وجهه."], ["ثم أدبر واستكبر", "أدبر عن الإيمان، واستكبر عن اتّباع الرسول ﷺ."], ["سحر يؤثر", "يُنقل عن السحرة."], ["سأصليه سقر", "سأدخله جهنم، وسقر اسم لها."], ["لا تبقي ولا تذر", "لا تترك شيئاً من اللحم ولا العصب إلا أهلكته، ثم يعود كما كان لإدامة العذاب."], ["لوّاحة للبشر", "محرقة مسوّدة لظاهر جلد الإنسان، وهو بشرته."], ["عليها تسعة عشر", "ملكاً، وهم خزنتها."]], "m": "لقد تحمّل رسول الله ﷺ عبء الدعوة وشرع في إنذار قومه، فأعلمهم أنه لا إله إلا الله وأنه رسول الله، فتصدّى له طاغية من أعظم الطغاة ساد الوادي مالاً وولداً وجاهاً حتى لُقّب بريحانة قريش، هو الوليد بن المغيرة، صاحب عشرة رجال من صلبه وآلاف الدنانير من الذهب، فقال له ربه: دعني والذي خلقته وحيداً بلا مال ولا ولد، وجعلت له مالاً ممدوداً واسعاً تمدّه به الزراعة والتجارة، وبنين حاضرين لا يغيبون، يشهدون المحافل، ومهّدت له في العيش والعمر والجاه، ثم يطمع أن أزيده؟ كلا، لن أزيده بعد اليوم، إنه كان لآياتنا القرآنية معانداً يحاول إبطالها، سأكلّفه عذاباً شاقّاً لا قبل له به، وهو جبل من نار يُكلّف صعوده. إنه فكّر فيما يقول في القرآن لما طلبت منه قريش أن يقول فيه، وقدّر في نفسه، فقُتل كيف قدّر، أي لُعن، ثم قُتل كيف قدّر، ثم تروّى، ثم قطّب ما بين عينيه، وكلح وجهه، ثم أدبر عن الإيمان واستكبر، فقال نتيجة تفكيره: ما هذا القرآن إلا سحر يُنقل عن السحرة، ما هذا إلا قول البشر. قال تعالى متوعّداً إياه: سأدخله سقر، وما أدراك ما سقر؟ إنها عظيمة، لا تُبقي لحماً ولا تذر عصباً، تحرق الجلود وتسوّدها، عليها تسعة عشر ملكاً هم خزنتها. ولنزول هذه الآيات سبب: أن قريشاً اتّهمت الوليد بأنه مال إلى دين محمد، فأنكر وحلف، فطلبوا إليه أن يقول في القرآن كلمة يصرف بها العرب عنه، فذهب إلى رسول الله ﷺ وهو يصلي فاستمع إليه، وقد وصف القرآن من قبل بقوله: والله إن لقوله لحلاوة، وإنه ليعلو ولا يُعلى، فقالوا: والله لا يرضى عنك قومك حتى تقول فيه، فقال: دعوني حتى أفكّر، ففكّر وقال ما تقدّم، فنزلت هذه الآيات.", "h": ["المال والبنون والجاه من عوامل الطغيان، إلا أن يسلّم الله عبده من فتنتها.", "من أكفر الناس من يعاند في آيات الله، يريد صرف الناس عنها وإبطال هدايتها.", "بيان ما ظفر به طاغية قريش الوليد بن المغيرة من لعنة وعذاب شديد.", "تقرير الوحي، وإثبات النبوة المحمدية.", "تقرير البعث والجزاء."], "k": "«إنه فكّر وقدّر»… فكّر طويلاً ثم اختار الكبر؛ فهل يقودني تفكيري إلى الحق أم إلى ما أشتهي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (428, 74, 31, 56, 'سورة المدثر ٣١ – ٥٦', 'المدثر: كل نفس بما كسبت رهينة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 428) = $j$[{"lbl": "الآيات ٣١ – ٣٧", "q": "وَمَا جَعَلۡنَآ أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةٗۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا وَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ ﴿٣١﴾ كَلَّا وَٱلۡقَمَرِ ﴿٣٢﴾ وَٱلَّيۡلِ إِذۡ أَدۡبَرَ ﴿٣٣﴾ وَٱلصُّبۡحِ إِذَآ أَسۡفَرَ ﴿٣٤﴾ إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ ﴿٣٥﴾ نَذِيرٗا لِّلۡبَشَرِ ﴿٣٦﴾ لِمَن شَآءَ مِنكُمۡ أَن يَتَقَدَّمَ أَوۡ يَتَأَخَّرَ ﴿٣٧﴾", "w": [["وما جعلنا عدّتهم", "كونهم تسعة عشر."], ["إلا فتنة للذين كفروا", "ليستخفّوا بهم كما قال أبو الأشدّين الجمحي، فيزدادوا ضلالاً."], ["ليستيقن الذين أوتوا الكتاب", "ليحصل اليقين لأهل التوراة والإنجيل بموافقة القرآن لكتابيهما."], ["ولا يرتاب", "ولا يشكّ أهل الكتاب والمؤمنون في حقيقة ذلك."], ["وليقول الذين في قلوبهم مرض", "مرض النفاق."], ["ماذا أراد الله بهذا مثلاً", "أي شيء أراد الله بهذا العدد الغريب؟ استنكاراً منهم."], ["كذلك", "مثل إضلال منكر هذا العدد وهدى مصدّقه يضل الله من يشاء ويهدي من يشاء."], ["وما هي إلا ذكرى للبشر", "وما النار إلا ذكرى للبشر يتذكّرون بها."], ["إذ أدبر", "ولّى ومضى."], ["إذا أسفر", "أضاء وظهر."], ["إنها لإحدى الكُبَر", "إن جهنم لإحدى البلايا العظام."], ["نذيراً للبشر", "عذاب جهنم نذير لبني آدم."], ["أن يتقدّم", "بالطاعة."], ["أو يتأخّر", "بالمعصية."]], "m": "نزلت هذه الآية ردّاً على أبي الأشدّين كلدة الجمحي الذي قال لما سمع «عليها تسعة عشر» ساخراً: أنا أكفيكم سبعة عشر واكفوني أنتم اثنين، فأنزل الله: وما جعلنا أصحاب النار إلا ملائكة، لم نجعلهم بشراً ولا جناً حتى لا يرحموا أهل النار كما قد يرحم الجنس جنسه، والمراد بأصحاب النار خزنتها، وهم مالك وثمانية عشر، هؤلاء رؤساء في جهنم، أما من عداهم فلا يعلم جنود ربك إلا هو. وما جعلنا عدّتهم تسعة عشر إلا فتنة للذين كفروا ليزدادوا ضلالاً وكفراً، وقد تم هذا فإن أبا جهل وأبا الأشدّين قد فُتنا بهذا العدد، وليستيقن الذين أوتوا الكتاب لموافقة القرآن لما عندهم، ويزداد الذين آمنوا إيماناً حين يرون موافقة الكتب للقرآن، ولا يرتاب أهل الكتاب والمؤمنون في يوم من الأيام، وليقول المنافقون والكافرون: أي شيء أراده الله بهذا الخبر الغريب؟ استنكاراً وتكذيباً. كذلك يضل الله من يشاء ويهدي من يشاء. وما يعلم جنود ربك إلا هو: جواب أبي جهل القائل: أما لمحمد أعوان إلا تسعة عشر؟ فأخبر تعالى أن له جنوداً لا يعلم عددها ولا قوتها إلا هو. وما جهنم إلا ذكرى للبشر يذكرون بها عظمة الله ويخافون عقابه. كلا، ليس القول كما يزعم المشركون، أقسم تعالى بالقمر والليل إذا ولّى والصبح إذا أضاء، على أن جهنم لإحدى البلايا العظام، عذابها نذير للبشر، لمن شاء منكم أن يتقدّم في طاعة الله ورسوله حتى يبلغ الدرجات العلا، أو يتأخّر في المعصية حتى ينزل الدركات السفلى.", "h": ["بيان الحكمة من جعل عدد الزبانية تسعة عشر والإخبار عنهم بذلك.", "موافقة التوراة والإنجيل للقرآن من شأنها أن تزيد إيمان المؤمنين من الفريقين.", "في النار من الزبانية ما لا يعلم عددهم إلا الله تعالى خالقهم.", "جهنم نذير للبشر، أي عذابها نذير لمن شاء أن يتقدّم بالطاعة أو يتأخّر بالمعصية."], "k": "«لمن شاء منكم أن يتقدّم أو يتأخّر»… لا وقوف في الطريق؛ فهل تقدّمت اليوم أم تأخّرت؟"}, {"lbl": "الآيات ٣٨ – ٥٦", "q": "كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ ﴿٣٨﴾ إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ ﴿٣٩﴾ فِي جَنَّـٰتٖ يَتَسَآءَلُونَ ﴿٤٠﴾ عَنِ ٱلۡمُجۡرِمِينَ ﴿٤١﴾ مَا سَلَكَكُمۡ فِي سَقَرَ ﴿٤٢﴾ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ ﴿٤٣﴾ وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ ﴿٤٤﴾ وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ ﴿٤٥﴾ وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ ﴿٤٦﴾ حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ ﴿٤٧﴾ فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّـٰفِعِينَ ﴿٤٨﴾ فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِينَ ﴿٤٩﴾ كَأَنَّهُمۡ حُمُرٞ مُّسۡتَنفِرَةٞ ﴿٥٠﴾ فَرَّتۡ مِن قَسۡوَرَةِۭ ﴿٥١﴾ بَلۡ يُرِيدُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفٗا مُّنَشَّرَةٗ ﴿٥٢﴾ كَلَّاۖ بَل لَّا يَخَافُونَ ٱلۡأٓخِرَةَ ﴿٥٣﴾ كَلَّآ إِنَّهُۥ تَذۡكِرَةٞ ﴿٥٤﴾ فَمَن شَآءَ ذَكَرَهُۥ ﴿٥٥﴾ وَمَا يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ ﴿٥٦﴾", "w": [["كل نفس بما كسبت رهينة", "مرهونة مأخوذة بعملها في جهنم."], ["إلا أصحاب اليمين", "المؤمنين، فهم ناجون من النار، وهم في جنات النعيم يتساءلون عن المجرمين."], ["ولم نكُ نطعم المسكين", "بخلاً بما آتاهم الله."], ["وكنا نخوض مع الخائضين", "في الباطل وفيما يكره الله تعالى."], ["وكنا نكذّب بيوم الدين", "بيوم المجازاة، ولا نصدّق بثواب ولا عقاب."], ["حتى أتانا اليقين", "الموت."], ["عن التذكرة معرضين", "عن الموعظة منصرفين، لا يسمعونها ولا يقبلون عليها."], ["حُمُر مستنفرة", "كأنهم حمر وحشية مستنفرة."], ["فرّت من قسورة", "هربت من أسد أشد الهرب."], ["أن يؤتى صحفاً منشّرة", "أن يصبح وعند رأسه كتاب من الله إلى فلان: آمن بنبيّنا."], ["إنه تذكرة", "عظة وعبرة."], ["فمن شاء ذكره", "قرأه واتّعظ به."], ["هو أهل التقوى", "أهل لأن يُتّقى لعظمة سلطانه وأليم عقابه."], ["وأهل المغفرة", "أهل لأن يغفر للتائبين من عباده والموحّدين."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: كل نفس مكلّفة يوم القيامة مرهونة محبوسة بما كسبت، إلا أصحاب اليمين فإنهم قد فُكّ رهنهم، وهم في جنات النعيم يتساءلون عن أصحاب الجحيم، ثم يتّصلون بهم برؤية وسماع، وفي الصناعات الحديثة اليوم ما جعل هذا أمراً معقولاً، فيقولون لهم: ما أدخلكم في سقر؟ فأجابوا: لم نكُ من المصلّين، ولم نكُ نطعم المسكين، وكنا نخوض مع أهل الباطل، وكنا نكذّب بيوم الدين، حتى أتانا الموت. فذكروا أعظم الجرائم: ترك الصلاة، ومنع الزكاة، والخوض مع أهل الباطل، والتكذيب بيوم القيامة، ولم يتوبوا منها حتى أتاهم الموت. فما تنفعهم شفاعة الشافعين من الملائكة والأنبياء والعلماء، لأنهم مشركون مجرمون. فما لهؤلاء المكذّبين عن التذكرة معرضين؟ إنه أمر عجيب، كأنهم حمر وحشية فرّت أشد الهرب من أسد، وليس فرارهم عن قصور في الأدلة، بل يريد كل واحد منهم أن يؤتى كتاباً من الله يأمره بالإيمان، وهذا هو العناد. كلا، بل علّة إعراضهم الحقيقية أنهم لا يخافون الآخرة. كلا إن هذا القرآن تذكرة، فمن شاء قرأه فاتّعظ به فآمن واتقى فنجا وسعد، وما يذكرون إلا أن يشاء الله، فلا بد من الافتقار إلى الله وطلب توفيقه، إذ لا استقلال لأحد عنه، ومشيئة العبد تابعة لمشيئته. هو أهل التقوى وأهل المغفرة، وقد صحّ أن النبي ﷺ فسّر هذه الآية فقال: «قال ربكم: أنا أهل أن أُتّقى فلا يُجعل معي إله، فمن اتّقاني فلم يجعل معي إلهاً فأنا أهل أن أغفر له».", "h": ["فكاك كل نفس مرهونة بكسبها هو الإيمان والتقوى.", "بيان أكبر الجرائم، وهي ترك الصلاة، ومنع الزكاة، والخوض في الباطل، وعدم التصديق بالحساب.", "لا شفاعة يوم القيامة لمن مات وهو يشرك بالله شيئاً.", "مردّ الانحراف في الإنسان إلى ضعف إيمانه بالبعث والجزاء.", "الله جل جلاله هو ذو الأهلية الحقة لأمرين عظيمين: التقوى، فلا يُتّقى على الحقيقة إلا هو، والمغفرة، فلا يغفر الذنوب إلا هو."], "k": "«لم نكُ من المصلّين»… أول جواب لأهل سقر ترك الصلاة؛ فكيف حال صلاتي اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 428;
insert into public.tdb_cards(topic, i, body) select 428, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣١ – ٣٧", "q": "وَمَا جَعَلۡنَآ أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةٗۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا وَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ ﴿٣١﴾ كَلَّا وَٱلۡقَمَرِ ﴿٣٢﴾ وَٱلَّيۡلِ إِذۡ أَدۡبَرَ ﴿٣٣﴾ وَٱلصُّبۡحِ إِذَآ أَسۡفَرَ ﴿٣٤﴾ إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ ﴿٣٥﴾ نَذِيرٗا لِّلۡبَشَرِ ﴿٣٦﴾ لِمَن شَآءَ مِنكُمۡ أَن يَتَقَدَّمَ أَوۡ يَتَأَخَّرَ ﴿٣٧﴾", "w": [["وما جعلنا عدّتهم", "كونهم تسعة عشر."], ["إلا فتنة للذين كفروا", "ليستخفّوا بهم كما قال أبو الأشدّين الجمحي، فيزدادوا ضلالاً."], ["ليستيقن الذين أوتوا الكتاب", "ليحصل اليقين لأهل التوراة والإنجيل بموافقة القرآن لكتابيهما."], ["ولا يرتاب", "ولا يشكّ أهل الكتاب والمؤمنون في حقيقة ذلك."], ["وليقول الذين في قلوبهم مرض", "مرض النفاق."], ["ماذا أراد الله بهذا مثلاً", "أي شيء أراد الله بهذا العدد الغريب؟ استنكاراً منهم."], ["كذلك", "مثل إضلال منكر هذا العدد وهدى مصدّقه يضل الله من يشاء ويهدي من يشاء."], ["وما هي إلا ذكرى للبشر", "وما النار إلا ذكرى للبشر يتذكّرون بها."], ["إذ أدبر", "ولّى ومضى."], ["إذا أسفر", "أضاء وظهر."], ["إنها لإحدى الكُبَر", "إن جهنم لإحدى البلايا العظام."], ["نذيراً للبشر", "عذاب جهنم نذير لبني آدم."], ["أن يتقدّم", "بالطاعة."], ["أو يتأخّر", "بالمعصية."]], "m": "نزلت هذه الآية ردّاً على أبي الأشدّين كلدة الجمحي الذي قال لما سمع «عليها تسعة عشر» ساخراً: أنا أكفيكم سبعة عشر واكفوني أنتم اثنين، فأنزل الله: وما جعلنا أصحاب النار إلا ملائكة، لم نجعلهم بشراً ولا جناً حتى لا يرحموا أهل النار كما قد يرحم الجنس جنسه، والمراد بأصحاب النار خزنتها، وهم مالك وثمانية عشر، هؤلاء رؤساء في جهنم، أما من عداهم فلا يعلم جنود ربك إلا هو. وما جعلنا عدّتهم تسعة عشر إلا فتنة للذين كفروا ليزدادوا ضلالاً وكفراً، وقد تم هذا فإن أبا جهل وأبا الأشدّين قد فُتنا بهذا العدد، وليستيقن الذين أوتوا الكتاب لموافقة القرآن لما عندهم، ويزداد الذين آمنوا إيماناً حين يرون موافقة الكتب للقرآن، ولا يرتاب أهل الكتاب والمؤمنون في يوم من الأيام، وليقول المنافقون والكافرون: أي شيء أراده الله بهذا الخبر الغريب؟ استنكاراً وتكذيباً. كذلك يضل الله من يشاء ويهدي من يشاء. وما يعلم جنود ربك إلا هو: جواب أبي جهل القائل: أما لمحمد أعوان إلا تسعة عشر؟ فأخبر تعالى أن له جنوداً لا يعلم عددها ولا قوتها إلا هو. وما جهنم إلا ذكرى للبشر يذكرون بها عظمة الله ويخافون عقابه. كلا، ليس القول كما يزعم المشركون، أقسم تعالى بالقمر والليل إذا ولّى والصبح إذا أضاء، على أن جهنم لإحدى البلايا العظام، عذابها نذير للبشر، لمن شاء منكم أن يتقدّم في طاعة الله ورسوله حتى يبلغ الدرجات العلا، أو يتأخّر في المعصية حتى ينزل الدركات السفلى.", "h": ["بيان الحكمة من جعل عدد الزبانية تسعة عشر والإخبار عنهم بذلك.", "موافقة التوراة والإنجيل للقرآن من شأنها أن تزيد إيمان المؤمنين من الفريقين.", "في النار من الزبانية ما لا يعلم عددهم إلا الله تعالى خالقهم.", "جهنم نذير للبشر، أي عذابها نذير لمن شاء أن يتقدّم بالطاعة أو يتأخّر بالمعصية."], "k": "«لمن شاء منكم أن يتقدّم أو يتأخّر»… لا وقوف في الطريق؛ فهل تقدّمت اليوم أم تأخّرت؟"}, {"lbl": "الآيات ٣٨ – ٥٦", "q": "كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِينَةٌ ﴿٣٨﴾ إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ ﴿٣٩﴾ فِي جَنَّـٰتٖ يَتَسَآءَلُونَ ﴿٤٠﴾ عَنِ ٱلۡمُجۡرِمِينَ ﴿٤١﴾ مَا سَلَكَكُمۡ فِي سَقَرَ ﴿٤٢﴾ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ ﴿٤٣﴾ وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ ﴿٤٤﴾ وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ ﴿٤٥﴾ وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ ﴿٤٦﴾ حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ ﴿٤٧﴾ فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّـٰفِعِينَ ﴿٤٨﴾ فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِينَ ﴿٤٩﴾ كَأَنَّهُمۡ حُمُرٞ مُّسۡتَنفِرَةٞ ﴿٥٠﴾ فَرَّتۡ مِن قَسۡوَرَةِۭ ﴿٥١﴾ بَلۡ يُرِيدُ كُلُّ ٱمۡرِيٕٖ مِّنۡهُمۡ أَن يُؤۡتَىٰ صُحُفٗا مُّنَشَّرَةٗ ﴿٥٢﴾ كَلَّاۖ بَل لَّا يَخَافُونَ ٱلۡأٓخِرَةَ ﴿٥٣﴾ كَلَّآ إِنَّهُۥ تَذۡكِرَةٞ ﴿٥٤﴾ فَمَن شَآءَ ذَكَرَهُۥ ﴿٥٥﴾ وَمَا يَذۡكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ ﴿٥٦﴾", "w": [["كل نفس بما كسبت رهينة", "مرهونة مأخوذة بعملها في جهنم."], ["إلا أصحاب اليمين", "المؤمنين، فهم ناجون من النار، وهم في جنات النعيم يتساءلون عن المجرمين."], ["ولم نكُ نطعم المسكين", "بخلاً بما آتاهم الله."], ["وكنا نخوض مع الخائضين", "في الباطل وفيما يكره الله تعالى."], ["وكنا نكذّب بيوم الدين", "بيوم المجازاة، ولا نصدّق بثواب ولا عقاب."], ["حتى أتانا اليقين", "الموت."], ["عن التذكرة معرضين", "عن الموعظة منصرفين، لا يسمعونها ولا يقبلون عليها."], ["حُمُر مستنفرة", "كأنهم حمر وحشية مستنفرة."], ["فرّت من قسورة", "هربت من أسد أشد الهرب."], ["أن يؤتى صحفاً منشّرة", "أن يصبح وعند رأسه كتاب من الله إلى فلان: آمن بنبيّنا."], ["إنه تذكرة", "عظة وعبرة."], ["فمن شاء ذكره", "قرأه واتّعظ به."], ["هو أهل التقوى", "أهل لأن يُتّقى لعظمة سلطانه وأليم عقابه."], ["وأهل المغفرة", "أهل لأن يغفر للتائبين من عباده والموحّدين."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: كل نفس مكلّفة يوم القيامة مرهونة محبوسة بما كسبت، إلا أصحاب اليمين فإنهم قد فُكّ رهنهم، وهم في جنات النعيم يتساءلون عن أصحاب الجحيم، ثم يتّصلون بهم برؤية وسماع، وفي الصناعات الحديثة اليوم ما جعل هذا أمراً معقولاً، فيقولون لهم: ما أدخلكم في سقر؟ فأجابوا: لم نكُ من المصلّين، ولم نكُ نطعم المسكين، وكنا نخوض مع أهل الباطل، وكنا نكذّب بيوم الدين، حتى أتانا الموت. فذكروا أعظم الجرائم: ترك الصلاة، ومنع الزكاة، والخوض مع أهل الباطل، والتكذيب بيوم القيامة، ولم يتوبوا منها حتى أتاهم الموت. فما تنفعهم شفاعة الشافعين من الملائكة والأنبياء والعلماء، لأنهم مشركون مجرمون. فما لهؤلاء المكذّبين عن التذكرة معرضين؟ إنه أمر عجيب، كأنهم حمر وحشية فرّت أشد الهرب من أسد، وليس فرارهم عن قصور في الأدلة، بل يريد كل واحد منهم أن يؤتى كتاباً من الله يأمره بالإيمان، وهذا هو العناد. كلا، بل علّة إعراضهم الحقيقية أنهم لا يخافون الآخرة. كلا إن هذا القرآن تذكرة، فمن شاء قرأه فاتّعظ به فآمن واتقى فنجا وسعد، وما يذكرون إلا أن يشاء الله، فلا بد من الافتقار إلى الله وطلب توفيقه، إذ لا استقلال لأحد عنه، ومشيئة العبد تابعة لمشيئته. هو أهل التقوى وأهل المغفرة، وقد صحّ أن النبي ﷺ فسّر هذه الآية فقال: «قال ربكم: أنا أهل أن أُتّقى فلا يُجعل معي إله، فمن اتّقاني فلم يجعل معي إلهاً فأنا أهل أن أغفر له».", "h": ["فكاك كل نفس مرهونة بكسبها هو الإيمان والتقوى.", "بيان أكبر الجرائم، وهي ترك الصلاة، ومنع الزكاة، والخوض في الباطل، وعدم التصديق بالحساب.", "لا شفاعة يوم القيامة لمن مات وهو يشرك بالله شيئاً.", "مردّ الانحراف في الإنسان إلى ضعف إيمانه بالبعث والجزاء.", "الله جل جلاله هو ذو الأهلية الحقة لأمرين عظيمين: التقوى، فلا يُتّقى على الحقيقة إلا هو، والمغفرة، فلا يغفر الذنوب إلا هو."], "k": "«لم نكُ من المصلّين»… أول جواب لأهل سقر ترك الصلاة؛ فكيف حال صلاتي اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (429, 75, 1, 40, 'سورة القيامة ١ – ٤٠', 'القيامة: بل الإنسان على نفسه بصيرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 429) = $j$[{"lbl": "الآيات ١ – ١٥", "q": "لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ ﴿١﴾ وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ ﴿٢﴾ أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ ﴿٣﴾ بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ ﴿٤﴾ بَلۡ يُرِيدُ ٱلۡإِنسَٰنُ لِيَفۡجُرَ أَمَامَهُۥ ﴿٥﴾ يَسۡـَٔلُ أَيَّانَ يَوۡمُ ٱلۡقِيَٰمَةِ ﴿٦﴾ فَإِذَا بَرِقَ ٱلۡبَصَرُ ﴿٧﴾ وَخَسَفَ ٱلۡقَمَرُ ﴿٨﴾ وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ ﴿٩﴾ يَقُولُ ٱلۡإِنسَٰنُ يَوۡمَئِذٍ أَيۡنَ ٱلۡمَفَرُّ ﴿١٠﴾ كَلَّا لَا وَزَرَ ﴿١١﴾ إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمُسۡتَقَرُّ ﴿١٢﴾ يُنَبَّؤُاْ ٱلۡإِنسَٰنُ يَوۡمَئِذِۭ بِمَا قَدَّمَ وَأَخَّرَ ﴿١٣﴾ بَلِ ٱلۡإِنسَٰنُ عَلَىٰ نَفۡسِهِۦ بَصِيرَةٞ ﴿١٤﴾ وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ ﴿١٥﴾", "w": [["لا أقسم بيوم القيامة", "ليس الأمر كما يدّعي المشركون من أنه لا بعث ولا جزاء، أقسم بيوم القيامة."], ["ولا أقسم بالنفس اللوّامة", "وأقسم بها لتُبعثنّ ولتحاسبنّ أيها المكذّبون."], ["اللوّامة", "التي إن أحسنت لامت على عدم الزيادة، وإن أساءت لامت على التقصير."], ["أيحسب الإنسان", "الكافر الملحد."], ["ألّن نجمع عظامه", "ألّا نجمع عظامه لنحييه للبعث والجزاء."], ["بلى قادرين على أن نسوّي بنانه", "بلى نجمعها قادرين على أن نجعل أصابعه كخفّ البعير أو حافر الفرس، كما نحن قادرون على جمع عظام البنان الدقيقة، وعلى تسوية خطوطها التي تختلف بين إنسان وإنسان اختلاف الوجوه والأصوات."], ["بل يريد الإنسان", "بإنكاره البعث والجزاء."], ["ليفجر أمامه", "ليواصل فجوره زمانه كله، ولذلك أنكر البعث."], ["يسأل أيّان يوم القيامة", "يسأل سؤال استنكار واستهزاء."], ["فإذا برق البصر", "دُهش وتحيّر لما رأى ما كان به يكذّب."], ["وخسف القمر", "أظلم بذهاب ضوئه."], ["وجُمع الشمس والقمر", "ذهب ضوؤهما، وذلك في بداية الانقلاب الكوني الذي تنتهي فيه هذه الحياة."], ["أين المفر", "إلى أين الفرار؟"], ["كلا لا وزر", "ردع له عن طلب الفرار، لا حصن ولا ملتجأ."], ["بل الإنسان على نفسه بصيرة", "هو شاهد على نفسه حيث تنطق جوارحه بعمله."], ["ولو ألقى معاذيره", "فلا بد من جزائه ولو ألقى معاذيره."]], "m": "ما الأمر كما تقولون أيها المنكرون للبعث والجزاء، أقسم بيوم القيامة الذي تنكرون، وبالنفس اللوّامة التي ستُحاسب وتُجزى، لتبعثنّ ثم لتنبّؤنّ بما عملتم. أيحسب الإنسان، والمراد الكافر الملحد، ألّن نجمع عظامه بعد موته وتفرّق أجزائه في الأرض؟ بلى نجمعها قادرين على ذلك وعلى ما هو أعظم، وهو تسوية بنانه بأن نجعل أصابعه كخفّ البعير، فيصبح يتناول الطعام بفمه. بل يريد الإنسان أن يواصل فجوره مستقبله كله، فلا يتوب من ذنوبه، لأن شهواته مستحكمة فيه، يقول: أيّان يوم القيامة؟ استبعاداً واستنكاراً وتسويفاً للتوبة، فبيّن تعالى وقت مجيئه: فإذا تحيّر البصر واندهش، وأظلم القمر وذهب ضوؤه، وجُمع الشمس والقمر فذهب ضوؤهما، وذلك في بداية الانقلاب الكوني، يقول الإنسان الكافر يومئذ: إلى أين الفرار؟ كلا، لا فرار اليوم من قبضة الجبار، لا حصن ولا ملتجأ، إلى ربك يومئذ المستقر: إما إلى جنة وإما إلى نار. يُخبر الإنسان يومئذ بما قدّم من أعماله في حياته، وبما أخّر بعد موته من سنة حسنة سنّها أو سيئة. بل الإنسان على نفسه بصيرة، فعندما يتقدّم للاستنطاق يحاول أن يتنصّل من بعض ذنوبه، فيُختم على لسانه وتنطق جوارحه شهوداً عليه، ولو ألقى معاذيره لا يُقبل منه، لكونه شاهداً على نفسه.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان إفضال الله على العبد في خلقه وتركيب أعضائه.", "معجزة قرآنية أثبتها العلم الحديث، وهي عدم تسوية خطوط الأصابع؛ فكما خالف تعالى بين الإنسان والإنسان وبين صوت وصوت فرّق بين خطوط الأصابع، فلذا استُعملت في الإمضاءات وقُبلت في الشهادات.", "تقرير مبدأ أن المؤمن يُثاب على ما أخّر من سنة حسنة يُعمل بها بعده، كما يأثم بالسنة السيئة يُعمل بها كذلك بعده."], "k": "«بل الإنسان على نفسه بصيرة ولو ألقى معاذيره»… أعرف عيوبي جيداً؛ فلماذا أعتذر عنها بدل أن أصلحها؟"}, {"lbl": "الآيات ١٦ – ٤٠", "q": "لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ﴿١٦﴾ إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ﴿١٧﴾ فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ﴿١٨﴾ ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ ﴿١٩﴾ كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ ﴿٢٠﴾ وَتَذَرُونَ ٱلۡأٓخِرَةَ ﴿٢١﴾ وُجُوهٞ يَوۡمَئِذٖ نَّاضِرَةٌ ﴿٢٢﴾ إِلَىٰ رَبِّهَا نَاظِرَةٞ ﴿٢٣﴾ وَوُجُوهٞ يَوۡمَئِذِۭ بَاسِرَةٞ ﴿٢٤﴾ تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ ﴿٢٥﴾ كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِيَ ﴿٢٦﴾ وَقِيلَ مَنۡۜ رَاقٖ ﴿٢٧﴾ وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ ﴿٢٨﴾ وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ ﴿٢٩﴾ إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ ﴿٣٠﴾ فَلَا صَدَّقَ وَلَا صَلَّىٰ ﴿٣١﴾ وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ ﴿٣٢﴾ ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ ﴿٣٣﴾ أَوۡلَىٰ لَكَ فَأَوۡلَىٰ ﴿٣٤﴾ ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ ﴿٣٥﴾ أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى ﴿٣٦﴾ أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ ﴿٣٧﴾ ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ ﴿٣٨﴾ فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ﴿٣٩﴾ أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ ﴿٤٠﴾", "w": [["لا تحرّك به لسانك", "لا تحرّك بالقرآن لسانك قبل فراغ جبريل منه."], ["لتعجل به", "مخافة أن يتفلّت منك."], ["إن علينا جمعه", "في صدرك."], ["وقرآنه", "قراءتك له بحيث تجريه على لسانك."], ["فإذا قرأناه", "قرأه جبريل عليك."], ["فاتّبع قرآنه", "استمع قراءته."], ["ثم إن علينا بيانه", "تفهيمك ما يشكل عليك من معانيه."], ["وتذرون الآخرة", "وتتركون الآخرة فلا تعملون لها."], ["ناضرة", "حسنة مضيئة."], ["إلى ربها ناظرة", "إلى الله تعالى ربها ناظرة، لا تُحجب عنه."], ["باسرة", "كالحة مسودّة عابسة."], ["تظن", "توقن."], ["فاقرة", "داهية عظيمة تكسر فقار الظهر."], ["التراقي", "عظام الحلق."], ["وقيل من راق", "قال من حوله من عوّاده: هل من يرقيه ليُشفى؟"], ["وظنّ أنه الفراق", "أيقن أنه فراق الدنيا لبلوغ الروح الحلقوم."], ["والتفّت الساق بالساق", "التقت إحدى ساقيه بالأخرى، أو التفّت شدة فراق الدنيا بشدة إقبال الآخرة."], ["إلى ربك يومئذ المساق", "تُساق الروح إلى ربها لتلقى جزاءها."], ["فلا صدّق ولا صلّى", "ما صدّق ولا صلّى."], ["وتولّى", "عن الإيمان."], ["يتمطّى", "يتبختر في مشيته إعجاباً بنفسه."], ["أولى لك فأولى", "وَلِيَك المكروه أيها المعجب المكذّب، فهو أولى بك."], ["يُمنى", "يُصبّ في الرحم."], ["فخلق فسوّى", "خلق الله منها الإنسان فسوّاه بتعديل أعضائه."]], "m": "لما ندّد تعالى بالمعرضين عن القرآن، ذكر المقبلين عليه المسارعين إلى تلقّيه، فقال مؤدّباً رسوله ﷺ: لا تحرّك بالقرآن لسانك قبل فراغ جبريل من قراءته، إذ كان ﷺ حريصاً عليه يخاف أن يتفلّت منه شيء، فطمأنه ربه: إن علينا جمعه في صدرك وقراءته على لسانك، فإذا قرأه جبريل عليك فاستمع له ثم اقرأه كما قرأه، ثم إن علينا بيان ما يشكل عليك من معانيه. ثم عاد السياق إلى تقرير عقيدة البعث والجزاء: كلا، ليس كما تدّعون، ولكن الذي جعلكم تكذّبون حبّكم للدنيا ولذّاتها، وترككم للآخرة لأنها تكلّفكم الصلاة والصيام والجهاد والتخلّي عن كثير من الشهوات. ثم عرض صورة لما يتجاهلونه: وجوه يومئذ حسنة مضيئة، لأن أرواح أصحابها كانت في الدنيا مشرقة بنور الإيمان، إلى ربها ناظرة سعيدة بلقائه، ووجوه يومئذ كالحة مسودّة، لأن أرواح أصحابها عاشت على ظلمة الكفر ودخان المعاصي فانطبعت النفس على الوجه، توقن أن يُفعل بها داهية تكسر فقار الظهر. كلا، ليس الأمر كما تحسب أيها الإنسان، انظر إليك وأنت على فراش الموت إذا بلغت روحك التراقي، وقال عوّادك: هل من راقٍ يرقيك أو طبيب يداويك؟ وأيقنت أنه الفراق لدنياك وأهلك، والتفّت ساقك بساقك، وشدة فراق الدنيا بشدة إقبال الآخرة، هنا انظر إلى أين يُذهب بك: أما جسمك فإلى مقرّه في الأرض، وأما روحك فإلى ربك ليحكم فيك، وقد كذّبت بآياته، فلا صدّقت ولا صلّيت، ولكن كذّبت وتولّيت، ثم ذهبت إلى أهلك تتبختر استكباراً، أولى لك فأولى، وليك الهلاك في الدنيا، ثم أولى لك فأولى في الآخرة. أيحسب الإنسان أن يُترك سدى، لا يُؤمر ولا يُنهى؟ ألم يكُ نطفة من منيّ يُصبّ في الرحم، ثم كان علقة فخلقه الله منها فسوّى خلقه، فجعل منه الزوجين الذكر والأنثى؟ أليس ذلك بقادر على أن يحيي الموتى؟ سبحانك اللهم بلى.", "h": ["مشروعية الرقية إذا كانت بالقرآن أو الكلم الطيب.", "التنويه بشأن الزكاة والصلاة، فرائض ونوافل.", "تحريم العجب والكبرياء والتبختر في المشي.", "تقرير عقيدة البعث والجزاء.", "الإنسان لم يُخلق عبثاً، والكون كله كذلك.", "مشروعية قول: «سبحانك اللهم بلى» لمن قرأ هذه الآية أو سمعها، إماماً كان أو مأموماً، وهي: «أليس ذلك بقادر على أن يحيي الموتى»."], "k": "«أيحسب الإنسان أن يُترك سدى»… لم أُخلق عبثاً؛ فهل يومي يشهد أن لي غاية؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 429;
insert into public.tdb_cards(topic, i, body) select 429, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٥", "q": "لَآ أُقۡسِمُ بِيَوۡمِ ٱلۡقِيَٰمَةِ ﴿١﴾ وَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ ﴿٢﴾ أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ ﴿٣﴾ بَلَىٰ قَٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّيَ بَنَانَهُۥ ﴿٤﴾ بَلۡ يُرِيدُ ٱلۡإِنسَٰنُ لِيَفۡجُرَ أَمَامَهُۥ ﴿٥﴾ يَسۡـَٔلُ أَيَّانَ يَوۡمُ ٱلۡقِيَٰمَةِ ﴿٦﴾ فَإِذَا بَرِقَ ٱلۡبَصَرُ ﴿٧﴾ وَخَسَفَ ٱلۡقَمَرُ ﴿٨﴾ وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ ﴿٩﴾ يَقُولُ ٱلۡإِنسَٰنُ يَوۡمَئِذٍ أَيۡنَ ٱلۡمَفَرُّ ﴿١٠﴾ كَلَّا لَا وَزَرَ ﴿١١﴾ إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمُسۡتَقَرُّ ﴿١٢﴾ يُنَبَّؤُاْ ٱلۡإِنسَٰنُ يَوۡمَئِذِۭ بِمَا قَدَّمَ وَأَخَّرَ ﴿١٣﴾ بَلِ ٱلۡإِنسَٰنُ عَلَىٰ نَفۡسِهِۦ بَصِيرَةٞ ﴿١٤﴾ وَلَوۡ أَلۡقَىٰ مَعَاذِيرَهُۥ ﴿١٥﴾", "w": [["لا أقسم بيوم القيامة", "ليس الأمر كما يدّعي المشركون من أنه لا بعث ولا جزاء، أقسم بيوم القيامة."], ["ولا أقسم بالنفس اللوّامة", "وأقسم بها لتُبعثنّ ولتحاسبنّ أيها المكذّبون."], ["اللوّامة", "التي إن أحسنت لامت على عدم الزيادة، وإن أساءت لامت على التقصير."], ["أيحسب الإنسان", "الكافر الملحد."], ["ألّن نجمع عظامه", "ألّا نجمع عظامه لنحييه للبعث والجزاء."], ["بلى قادرين على أن نسوّي بنانه", "بلى نجمعها قادرين على أن نجعل أصابعه كخفّ البعير أو حافر الفرس، كما نحن قادرون على جمع عظام البنان الدقيقة، وعلى تسوية خطوطها التي تختلف بين إنسان وإنسان اختلاف الوجوه والأصوات."], ["بل يريد الإنسان", "بإنكاره البعث والجزاء."], ["ليفجر أمامه", "ليواصل فجوره زمانه كله، ولذلك أنكر البعث."], ["يسأل أيّان يوم القيامة", "يسأل سؤال استنكار واستهزاء."], ["فإذا برق البصر", "دُهش وتحيّر لما رأى ما كان به يكذّب."], ["وخسف القمر", "أظلم بذهاب ضوئه."], ["وجُمع الشمس والقمر", "ذهب ضوؤهما، وذلك في بداية الانقلاب الكوني الذي تنتهي فيه هذه الحياة."], ["أين المفر", "إلى أين الفرار؟"], ["كلا لا وزر", "ردع له عن طلب الفرار، لا حصن ولا ملتجأ."], ["بل الإنسان على نفسه بصيرة", "هو شاهد على نفسه حيث تنطق جوارحه بعمله."], ["ولو ألقى معاذيره", "فلا بد من جزائه ولو ألقى معاذيره."]], "m": "ما الأمر كما تقولون أيها المنكرون للبعث والجزاء، أقسم بيوم القيامة الذي تنكرون، وبالنفس اللوّامة التي ستُحاسب وتُجزى، لتبعثنّ ثم لتنبّؤنّ بما عملتم. أيحسب الإنسان، والمراد الكافر الملحد، ألّن نجمع عظامه بعد موته وتفرّق أجزائه في الأرض؟ بلى نجمعها قادرين على ذلك وعلى ما هو أعظم، وهو تسوية بنانه بأن نجعل أصابعه كخفّ البعير، فيصبح يتناول الطعام بفمه. بل يريد الإنسان أن يواصل فجوره مستقبله كله، فلا يتوب من ذنوبه، لأن شهواته مستحكمة فيه، يقول: أيّان يوم القيامة؟ استبعاداً واستنكاراً وتسويفاً للتوبة، فبيّن تعالى وقت مجيئه: فإذا تحيّر البصر واندهش، وأظلم القمر وذهب ضوؤه، وجُمع الشمس والقمر فذهب ضوؤهما، وذلك في بداية الانقلاب الكوني، يقول الإنسان الكافر يومئذ: إلى أين الفرار؟ كلا، لا فرار اليوم من قبضة الجبار، لا حصن ولا ملتجأ، إلى ربك يومئذ المستقر: إما إلى جنة وإما إلى نار. يُخبر الإنسان يومئذ بما قدّم من أعماله في حياته، وبما أخّر بعد موته من سنة حسنة سنّها أو سيئة. بل الإنسان على نفسه بصيرة، فعندما يتقدّم للاستنطاق يحاول أن يتنصّل من بعض ذنوبه، فيُختم على لسانه وتنطق جوارحه شهوداً عليه، ولو ألقى معاذيره لا يُقبل منه، لكونه شاهداً على نفسه.", "h": ["تقرير عقيدة البعث والجزاء.", "بيان إفضال الله على العبد في خلقه وتركيب أعضائه.", "معجزة قرآنية أثبتها العلم الحديث، وهي عدم تسوية خطوط الأصابع؛ فكما خالف تعالى بين الإنسان والإنسان وبين صوت وصوت فرّق بين خطوط الأصابع، فلذا استُعملت في الإمضاءات وقُبلت في الشهادات.", "تقرير مبدأ أن المؤمن يُثاب على ما أخّر من سنة حسنة يُعمل بها بعده، كما يأثم بالسنة السيئة يُعمل بها كذلك بعده."], "k": "«بل الإنسان على نفسه بصيرة ولو ألقى معاذيره»… أعرف عيوبي جيداً؛ فلماذا أعتذر عنها بدل أن أصلحها؟"}, {"lbl": "الآيات ١٦ – ٤٠", "q": "لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ﴿١٦﴾ إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ﴿١٧﴾ فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ﴿١٨﴾ ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ ﴿١٩﴾ كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ ﴿٢٠﴾ وَتَذَرُونَ ٱلۡأٓخِرَةَ ﴿٢١﴾ وُجُوهٞ يَوۡمَئِذٖ نَّاضِرَةٌ ﴿٢٢﴾ إِلَىٰ رَبِّهَا نَاظِرَةٞ ﴿٢٣﴾ وَوُجُوهٞ يَوۡمَئِذِۭ بَاسِرَةٞ ﴿٢٤﴾ تَظُنُّ أَن يُفۡعَلَ بِهَا فَاقِرَةٞ ﴿٢٥﴾ كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِيَ ﴿٢٦﴾ وَقِيلَ مَنۡۜ رَاقٖ ﴿٢٧﴾ وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ ﴿٢٨﴾ وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ ﴿٢٩﴾ إِلَىٰ رَبِّكَ يَوۡمَئِذٍ ٱلۡمَسَاقُ ﴿٣٠﴾ فَلَا صَدَّقَ وَلَا صَلَّىٰ ﴿٣١﴾ وَلَٰكِن كَذَّبَ وَتَوَلَّىٰ ﴿٣٢﴾ ثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ ﴿٣٣﴾ أَوۡلَىٰ لَكَ فَأَوۡلَىٰ ﴿٣٤﴾ ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ ﴿٣٥﴾ أَيَحۡسَبُ ٱلۡإِنسَٰنُ أَن يُتۡرَكَ سُدًى ﴿٣٦﴾ أَلَمۡ يَكُ نُطۡفَةٗ مِّن مَّنِيّٖ يُمۡنَىٰ ﴿٣٧﴾ ثُمَّ كَانَ عَلَقَةٗ فَخَلَقَ فَسَوَّىٰ ﴿٣٨﴾ فَجَعَلَ مِنۡهُ ٱلزَّوۡجَيۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ﴿٣٩﴾ أَلَيۡسَ ذَٰلِكَ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰ ﴿٤٠﴾", "w": [["لا تحرّك به لسانك", "لا تحرّك بالقرآن لسانك قبل فراغ جبريل منه."], ["لتعجل به", "مخافة أن يتفلّت منك."], ["إن علينا جمعه", "في صدرك."], ["وقرآنه", "قراءتك له بحيث تجريه على لسانك."], ["فإذا قرأناه", "قرأه جبريل عليك."], ["فاتّبع قرآنه", "استمع قراءته."], ["ثم إن علينا بيانه", "تفهيمك ما يشكل عليك من معانيه."], ["وتذرون الآخرة", "وتتركون الآخرة فلا تعملون لها."], ["ناضرة", "حسنة مضيئة."], ["إلى ربها ناظرة", "إلى الله تعالى ربها ناظرة، لا تُحجب عنه."], ["باسرة", "كالحة مسودّة عابسة."], ["تظن", "توقن."], ["فاقرة", "داهية عظيمة تكسر فقار الظهر."], ["التراقي", "عظام الحلق."], ["وقيل من راق", "قال من حوله من عوّاده: هل من يرقيه ليُشفى؟"], ["وظنّ أنه الفراق", "أيقن أنه فراق الدنيا لبلوغ الروح الحلقوم."], ["والتفّت الساق بالساق", "التقت إحدى ساقيه بالأخرى، أو التفّت شدة فراق الدنيا بشدة إقبال الآخرة."], ["إلى ربك يومئذ المساق", "تُساق الروح إلى ربها لتلقى جزاءها."], ["فلا صدّق ولا صلّى", "ما صدّق ولا صلّى."], ["وتولّى", "عن الإيمان."], ["يتمطّى", "يتبختر في مشيته إعجاباً بنفسه."], ["أولى لك فأولى", "وَلِيَك المكروه أيها المعجب المكذّب، فهو أولى بك."], ["يُمنى", "يُصبّ في الرحم."], ["فخلق فسوّى", "خلق الله منها الإنسان فسوّاه بتعديل أعضائه."]], "m": "لما ندّد تعالى بالمعرضين عن القرآن، ذكر المقبلين عليه المسارعين إلى تلقّيه، فقال مؤدّباً رسوله ﷺ: لا تحرّك بالقرآن لسانك قبل فراغ جبريل من قراءته، إذ كان ﷺ حريصاً عليه يخاف أن يتفلّت منه شيء، فطمأنه ربه: إن علينا جمعه في صدرك وقراءته على لسانك، فإذا قرأه جبريل عليك فاستمع له ثم اقرأه كما قرأه، ثم إن علينا بيان ما يشكل عليك من معانيه. ثم عاد السياق إلى تقرير عقيدة البعث والجزاء: كلا، ليس كما تدّعون، ولكن الذي جعلكم تكذّبون حبّكم للدنيا ولذّاتها، وترككم للآخرة لأنها تكلّفكم الصلاة والصيام والجهاد والتخلّي عن كثير من الشهوات. ثم عرض صورة لما يتجاهلونه: وجوه يومئذ حسنة مضيئة، لأن أرواح أصحابها كانت في الدنيا مشرقة بنور الإيمان، إلى ربها ناظرة سعيدة بلقائه، ووجوه يومئذ كالحة مسودّة، لأن أرواح أصحابها عاشت على ظلمة الكفر ودخان المعاصي فانطبعت النفس على الوجه، توقن أن يُفعل بها داهية تكسر فقار الظهر. كلا، ليس الأمر كما تحسب أيها الإنسان، انظر إليك وأنت على فراش الموت إذا بلغت روحك التراقي، وقال عوّادك: هل من راقٍ يرقيك أو طبيب يداويك؟ وأيقنت أنه الفراق لدنياك وأهلك، والتفّت ساقك بساقك، وشدة فراق الدنيا بشدة إقبال الآخرة، هنا انظر إلى أين يُذهب بك: أما جسمك فإلى مقرّه في الأرض، وأما روحك فإلى ربك ليحكم فيك، وقد كذّبت بآياته، فلا صدّقت ولا صلّيت، ولكن كذّبت وتولّيت، ثم ذهبت إلى أهلك تتبختر استكباراً، أولى لك فأولى، وليك الهلاك في الدنيا، ثم أولى لك فأولى في الآخرة. أيحسب الإنسان أن يُترك سدى، لا يُؤمر ولا يُنهى؟ ألم يكُ نطفة من منيّ يُصبّ في الرحم، ثم كان علقة فخلقه الله منها فسوّى خلقه، فجعل منه الزوجين الذكر والأنثى؟ أليس ذلك بقادر على أن يحيي الموتى؟ سبحانك اللهم بلى.", "h": ["مشروعية الرقية إذا كانت بالقرآن أو الكلم الطيب.", "التنويه بشأن الزكاة والصلاة، فرائض ونوافل.", "تحريم العجب والكبرياء والتبختر في المشي.", "تقرير عقيدة البعث والجزاء.", "الإنسان لم يُخلق عبثاً، والكون كله كذلك.", "مشروعية قول: «سبحانك اللهم بلى» لمن قرأ هذه الآية أو سمعها، إماماً كان أو مأموماً، وهي: «أليس ذلك بقادر على أن يحيي الموتى»."], "k": "«أيحسب الإنسان أن يُترك سدى»… لم أُخلق عبثاً؛ فهل يومي يشهد أن لي غاية؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (430, 76, 1, 31, 'سورة الإنسان ١ – ٣١', 'الإنسان: إنما نطعمكم لوجه الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 430) = $j$[{"lbl": "الآيات ١ – ١٢", "q": "هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا ﴿١﴾ إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا ﴿٢﴾ إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا ﴿٣﴾ إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا ﴿٤﴾ إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا ﴿٥﴾ عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا ﴿٦﴾ يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا ﴿٧﴾ وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا ﴿٨﴾ إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا ﴿٩﴾ إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا ﴿١٠﴾ فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا ﴿١١﴾ وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ﴿١٢﴾", "w": [["هل أتى", "قد أتى."], ["على الإنسان", "آدم ﵇."], ["حين من الدهر", "أربعون سنة."], ["لم يكن شيئاً مذكوراً", "لا نباهة ولا رفعة له، لأنه طين لازب، وذلك قبل أن ينفخ الله فيه الروح."], ["أمشاج", "أخلاط من ماء المرأة وماء الرجل."], ["نبتليه", "نختبره بالتكاليف بالأمر والنهي عند تأهّله لذلك بالبلوغ والعقل."], ["إنا هديناه السبيل", "بيّنا له طريق الهدى ببعثة الرسل وإنزال الكتب."], ["إنا أعتدنا", "هيّأنا."], ["سلاسل", "يُسحبون بها في نار جهنم."], ["وأغلالاً", "في أعناقهم."], ["وسعيراً", "ناراً مسعّرة مهيّجة."], ["إن الأبرار", "المطيعين لله ورسوله، الصادقين في إيمانهم وأقوالهم وأحوالهم."], ["مزاجها", "ما تُمزج به وتُخلط."], ["يفجّرونها", "يجرونها ويسيلونها حيث شاؤوا."], ["شرّه مستطيراً", "ممتدّاً طويلاً فاشياً منتشراً."], ["عبوساً", "تكلح الوجوه من طوله وشدته."], ["نضرة وسروراً", "حسناً ووضاءة في وجوههم، وفرحاً في قلوبهم."]], "m": "يخبر تعالى عن آدم أبي البشر ﵇ أنه أتى عليه حين من الدهر، قد يكون أربعين سنة، وهو صورة من طين لا روح فيها، فلم يكن شيئاً له نباهة فيُذكر. ثم أخبر عن ابن آدم أنه خلقه من نطفة أخلاط من ماء الرجل وماء المرأة، نختبره بالتكاليف عند تأهّله بالبلوغ والعقل، ولذلك جعله سميعاً بصيراً، إذ بوجود السمع والبصر معاً أو بأحدهما يتم التكليف. إنا بيّنا له طريق الهدى، واستبان له بذلك طريق الغيّ، فهو إما أن يسلك سبيل الهدى فيكون شكوراً، وهو المؤمن المطيع، وإما أن يسلك سبيل الغيّ فيكون كفوراً. ثم شرع في بيان ما أعدّ لكلٍّ، موجزاً في عذاب الكافرين ومطنباً في نعيم الأبرار، إذ هو تفصيله محبوب: إنا أعتدنا للكافرين سلاسل يُسحبون بها في النار، وأغلالاً تُغلّ بها أيديهم في أعناقهم، وسعيراً متأجّجاً. إن الأبرار المطيعين يشربون من كأس ملأى شراباً مزاجها كافوراً لبرودته وبياض لونه وطيب رائحته، عيناً يشرب بها عباد الله، يجرونها حيث شاؤوا من غرفهم وقصورهم. ثم قطع الحديث عن نعيمهم ليذكر بعض فضائلهم ترغيباً في فعلهم: كانوا في الدنيا يوفون بالنذر، وهو ما يلتزمونه من طاعات تقرّباً إلى ربهم، ويخافون يوم الحساب الذي كان شرّه فاشياً منتشراً، ويطعمون الطعام مع حبّهم وشهوتهم له، مسكيناً أذلّته الحاجة، ويتيماً لا عائل له، وأسيراً بعيد الدار، ولسان حالهم أو مقالهم: إنما نطعمكم لوجه الله، لا نريد منكم جزاءً ولا شكوراً، إنا نخاف من ربنا يوماً كالح الوجوه ثقيلاً طويلاً. فوقاهم الله شرّ ذلك اليوم، ولقّاهم نضرة في وجوههم وسروراً في قلوبهم، وجزاهم بما صبروا على فعل الصالحات وترك المحرّمات جنة وحريراً.", "h": ["بيان نشأة الإنسان الأب والإنسان الابن، وما تدل عليه من إفضال الله وإكرامه لعباده.", "حاسّتا السمع والبصر، وجودهما معاً أو وجود إحداهما، ضروري للتكليف مع ضميمة العقل.", "بيان أن الإنسان أمامه طريقان فليسلك أيّهما شاء، وكل طريق ينتهي به إلى غاية: فطريق الرشد يوصل إلى الجنة دار النعيم، وطريق الغيّ يوصل إلى دار الشقاء الجحيم.", "وجوب الوفاء بالنذر، فمن نذر شيئاً لله وجب أن يفي بنذره، إلا أن ينذر معصية فلا يجوز له الوفاء بنذره فيها؛ فمن قال: لله عليّ أن أصوم يوم كذا، وجب عليه أن يصوم، ومن قال: لله عليّ ألا أصل رحمي، فلا يجوز له الوفاء، وليصل رحمه، ولا كفارة عليه.", "الترغيب في إطعام الطعام للمحتاجين إليه من فقير ويتيم وأسير."], "k": "«إنما نطعمكم لوجه الله لا نريد منكم جزاءً ولا شكوراً»… حين أعطي، هل أنتظر الشكر من الناس؟"}, {"lbl": "الآيات ١٣ – ٢٢", "q": "مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا ﴿١٣﴾ وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلٗا ﴿١٤﴾ وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠ ﴿١٥﴾ قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا ﴿١٦﴾ وَيُسۡقَوۡنَ فِيهَا كَأۡسٗا كَانَ مِزَاجُهَا زَنجَبِيلًا ﴿١٧﴾ عَيۡنٗا فِيهَا تُسَمَّىٰ سَلۡسَبِيلٗا ﴿١٨﴾ ۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا ﴿١٩﴾ وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمٗا وَمُلۡكٗا كَبِيرًا ﴿٢٠﴾ عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا ﴿٢١﴾ إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءٗ وَكَانَ سَعۡيُكُم مَّشۡكُورًا ﴿٢٢﴾", "w": [["على الأرائك", "على الأسرّة في الحجال، واحد الأرائك أريكة."], ["ولا زمهريراً", "ولا برداً شديداً، أو ولا قمراً، إذ هي تُضاء من نفسها."], ["ودانية", "قريبة منهم ظلال أشجار الجنة."], ["وذُلّلت قطوفها تذليلاً", "بحيث ينالها المؤمن قائماً وقاعداً ومضطجعاً."], ["وأكواب", "أقداح بلا عرى."], ["قوارير من فضة", "يُرى باطنها من ظاهرها."], ["قدّروها تقديراً", "على قدر الشاربين بلا زيادة ولا نقص."], ["ويُسقون فيها كأساً", "خمراً."], ["كان مزاجها زنجبيلاً", "ما تُمزج وتُخلط به زنجبيلاً."], ["مخلّدون", "بصفة الولدان لا يشيبون."], ["لؤلؤاً منثوراً", "من سلكه أو من صدفه، لحسنهم وجمالهم وانتشارهم في الخدمة."], ["وإذا رأيت ثَمّ", "في الجنة رأيت نعيماً لا يوصف وملكاً واسعاً لا يُقدّر."], ["ثياب سندس", "حرير."], ["وإستبرق", "ما غلظ من الديباج."], ["وحُلّوا", "تحلّيهم الملائكة."], ["شراباً طهوراً", "فائقاً على النوعين السابقين، ولذا أسند سقيه إلى الله عز وجل."], ["إن هذا", "النعيم."], ["مشكوراً", "مرضيّاً مقبولاً."]], "m": "ما زال السياق في ذكر ما أعدّ الله للأبرار: متّكئين في الجنة على الأسرّة في الحجال، لا يرون فيها شمساً ولا زمهريراً، فلا شمس في الجنة ولا قمر لعدم الحاجة إليهما، ولا حرّ ولا برد كذلك، ودانية عليهم ظلال أشجارها، يجدون فيها لذّة التظليل وإن لم تكن هناك شمس، وذُلّلت ثمارها بحيث ينالها القائم والقاعد والمضطجع، فلا شوك ولا بعد، لأن الدار دار نعيم وراحة. ويطوف عليهم الخدم بآنية من فضة وأكواب لا عرى لها، قوارير من فضة يُرى باطنها من ظاهرها لصفائها، مادّتها فضة وصفاؤها صفاء الزجاج، قدّرها الخدم بحيث لا تزيد فتفيض ولا تنقص فلا يجمل منظرها. ويُسقون فيها خمراً مزاجها زنجبيلاً، من عين في الجنة تُسمّى سلسبيلاً. ويطوف عليهم غلمان مخلّدون لا يهرمون ولا يموتون، إذا رأيتهم في جمالهم وانتشارهم في الخدمة حسبتهم لؤلؤاً منثوراً. وإذا رأيت يا رسولنا هناك في الجنة رأيت نعيماً لا يوصف وملكاً كبيراً لا يُقادر قدره، فوقهم ثياب حرير خضر وإستبرق، وحلّاهم ربهم أساور من فضة ومن ذهب أيضاً، وسقاهم ربهم شراباً طهوراً، وهذا إكرام خاص أن الله هو الذي يسقيهم. ويقال لهم تكريماً: إن هذا النعيم كان لكم جزاءً على إيمانكم وتقواكم، وكان عملكم في الدنيا مرضيّاً مقبولاً.", "h": ["تقرير عقيدة البعث والجزاء بذكر صور من الجزاء الأخروي.", "حرمة استعمال أواني الذهب والفضة، لقول الرسول ﷺ: «هي لهم في الدنيا ولنا في الآخرة».", "حرمة الخمر، لحديث: «من شرب الخمر في الدنيا لا يشربها في الآخرة».", "مشروعية اتخاذ خدم صالحين يخدمون المرء، ويُحسن إليهم.", "حرمة لبس الحرير على الرجال وإباحته للنساء، وكالحرير الذهب أيضاً."], "k": "«وكان سعيكم مشكوراً»… أن يقول الله لي يوماً: شكرت سعيك؛ فهل سعيي اليوم يستحق ذلك؟"}, {"lbl": "الآيات ٢٣ – ٣١", "q": "إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا ﴿٢٣﴾ فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا ﴿٢٤﴾ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ﴿٢٥﴾ وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ﴿٢٦﴾ إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمٗا ثَقِيلٗا ﴿٢٧﴾ نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا ﴿٢٨﴾ إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ﴿٢٩﴾ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿٣٠﴾ يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا ﴿٣١﴾", "w": [["نزّلنا عليك القرآن تنزيلاً", "شيئاً فشيئاً، ولم ننزله جملة واحدة، لحكمة بالغة."], ["فاصبر لحكم ربك", "على حمل رسالتك وإبلاغها إلى الناس."], ["ولا تطع منهم آثماً أو كفوراً", "الآثم هنا عتبة بن ربيعة، والكفور الوليد بن المغيرة."], ["واذكر اسم ربك بكرة وأصيلاً", "صلّ الصبح والظهر والعصر."], ["ومن الليل فاسجد له", "صلّ صلاة المغرب والعشاء."], ["وسبّحه ليلاً طويلاً", "تهجّد بالليل نافلة لك."], ["يحبّون العاجلة", "الدنيا."], ["ويذرون وراءهم يوماً ثقيلاً", "يوم القيامة."], ["وشددنا أسرهم", "قوّينا أعضاءهم ومفاصلهم."], ["وإذا شئنا بدّلنا أمثالهم تبديلاً", "جعلنا أمثالهم في الخلقة بدلاً منهم بعد أن نهلكهم."], ["اتّخذ إلى ربه سبيلاً", "طريقاً إلى مرضاته وجواره بالإيمان والعمل الصالح وترك الشرك والمعاصي."], ["أعدّ لهم عذاباً أليماً", "في النار، والأليم ذو الألم الموجع."]], "m": "لقد عرض المشركون على رسول الله ﷺ أن يترك دعوته إلى التوحيد ويعبد ربه وحده ويتركهم فيما هم فيه، وله مقابل ذلك مال أو أزواج أو رئاسة، فأبى الله ذلك وأنزل: إنا نحن نزّلنا عليك القرآن تنزيلاً، فاصبر لحكم ربك على تحمّل رسالتك وتبليغها، ولا تطع من مشركي قريش آثماً كأبي جهل وعتبة، ولا كفوراً كالوليد، وواصل دعوتك واستعن بالصلاة والتسبيح والذكر والدعاء: بكرة وأصيلاً إشارة إلى صلاة الصبح والظهر والعصر، ومن الليل فاسجد له إشارة إلى المغرب والعشاء، وسبّحه ليلاً طويلاً صريح في أنه التهجّد، إذ الصلاة نعم العون للعبد، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. إن هؤلاء، يعني كفار قريش، يحبّون الدنيا، وسُمّيت العاجلة لأنها ذاهبة مسرعة، ويتركون وراءهم يوم القيامة الثقيل فلم يعملوا له. نحن خلقناهم من العدم، وقوّينا ظهورهم ومفاصلهم، وإذا شئنا أهلكناهم وجعلنا أمثالهم بدلاً عنهم، ولو شاء لكان، وهو في كل قرن يبدّل جيلاً بجيل. إن هذه السورة موعظة، فمن شاء اتّخذ إلى ربه طريقاً إلى رضاه أولاً ثم مجاورته في الملكوت الأعلى، وقيّد المشيئة بمشيئته، فوجب الافتقار إلى الله بدعائه والضراعة إليه: وما تشاؤون إلا أن يشاء الله، إن الله كان عليماً بخلقه حكيماً في تدبيره. يُدخل من يشاء في رحمته، من أهل الإيمان والتقوى، والظالمين المشركين أعدّ لهم عذاباً أليماً لكفرهم به وشركهم في عبادته.", "h": ["حرمة طاعة ذوي الإثم وأهل الكفر في حال الاختيار.", "على المؤمن أن يستعين بالصلاة والذكر والدعاء، فإنها نعم العون.", "استحباب نافلة الليل.", "مشيئة الله عز وجل قبل وفوق كل مشيئة.", "القرآن تذكرة للمؤمنين."], "k": "«وما تشاؤون إلا أن يشاء الله»… حتى رغبتي في الخير منه؛ فهل أسأله أن يشاء لي الهداية؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 430;
insert into public.tdb_cards(topic, i, body) select 430, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٢", "q": "هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡـٔٗا مَّذۡكُورًا ﴿١﴾ إِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا ﴿٢﴾ إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا ﴿٣﴾ إِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَلَٰسِلَاْ وَأَغۡلَٰلٗا وَسَعِيرًا ﴿٤﴾ إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسٖ كَانَ مِزَاجُهَا كَافُورًا ﴿٥﴾ عَيۡنٗا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرٗا ﴿٦﴾ يُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا ﴿٧﴾ وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا ﴿٨﴾ إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا ﴿٩﴾ إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا ﴿١٠﴾ فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلۡيَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةٗ وَسُرُورٗا ﴿١١﴾ وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ﴿١٢﴾", "w": [["هل أتى", "قد أتى."], ["على الإنسان", "آدم ﵇."], ["حين من الدهر", "أربعون سنة."], ["لم يكن شيئاً مذكوراً", "لا نباهة ولا رفعة له، لأنه طين لازب، وذلك قبل أن ينفخ الله فيه الروح."], ["أمشاج", "أخلاط من ماء المرأة وماء الرجل."], ["نبتليه", "نختبره بالتكاليف بالأمر والنهي عند تأهّله لذلك بالبلوغ والعقل."], ["إنا هديناه السبيل", "بيّنا له طريق الهدى ببعثة الرسل وإنزال الكتب."], ["إنا أعتدنا", "هيّأنا."], ["سلاسل", "يُسحبون بها في نار جهنم."], ["وأغلالاً", "في أعناقهم."], ["وسعيراً", "ناراً مسعّرة مهيّجة."], ["إن الأبرار", "المطيعين لله ورسوله، الصادقين في إيمانهم وأقوالهم وأحوالهم."], ["مزاجها", "ما تُمزج به وتُخلط."], ["يفجّرونها", "يجرونها ويسيلونها حيث شاؤوا."], ["شرّه مستطيراً", "ممتدّاً طويلاً فاشياً منتشراً."], ["عبوساً", "تكلح الوجوه من طوله وشدته."], ["نضرة وسروراً", "حسناً ووضاءة في وجوههم، وفرحاً في قلوبهم."]], "m": "يخبر تعالى عن آدم أبي البشر ﵇ أنه أتى عليه حين من الدهر، قد يكون أربعين سنة، وهو صورة من طين لا روح فيها، فلم يكن شيئاً له نباهة فيُذكر. ثم أخبر عن ابن آدم أنه خلقه من نطفة أخلاط من ماء الرجل وماء المرأة، نختبره بالتكاليف عند تأهّله بالبلوغ والعقل، ولذلك جعله سميعاً بصيراً، إذ بوجود السمع والبصر معاً أو بأحدهما يتم التكليف. إنا بيّنا له طريق الهدى، واستبان له بذلك طريق الغيّ، فهو إما أن يسلك سبيل الهدى فيكون شكوراً، وهو المؤمن المطيع، وإما أن يسلك سبيل الغيّ فيكون كفوراً. ثم شرع في بيان ما أعدّ لكلٍّ، موجزاً في عذاب الكافرين ومطنباً في نعيم الأبرار، إذ هو تفصيله محبوب: إنا أعتدنا للكافرين سلاسل يُسحبون بها في النار، وأغلالاً تُغلّ بها أيديهم في أعناقهم، وسعيراً متأجّجاً. إن الأبرار المطيعين يشربون من كأس ملأى شراباً مزاجها كافوراً لبرودته وبياض لونه وطيب رائحته، عيناً يشرب بها عباد الله، يجرونها حيث شاؤوا من غرفهم وقصورهم. ثم قطع الحديث عن نعيمهم ليذكر بعض فضائلهم ترغيباً في فعلهم: كانوا في الدنيا يوفون بالنذر، وهو ما يلتزمونه من طاعات تقرّباً إلى ربهم، ويخافون يوم الحساب الذي كان شرّه فاشياً منتشراً، ويطعمون الطعام مع حبّهم وشهوتهم له، مسكيناً أذلّته الحاجة، ويتيماً لا عائل له، وأسيراً بعيد الدار، ولسان حالهم أو مقالهم: إنما نطعمكم لوجه الله، لا نريد منكم جزاءً ولا شكوراً، إنا نخاف من ربنا يوماً كالح الوجوه ثقيلاً طويلاً. فوقاهم الله شرّ ذلك اليوم، ولقّاهم نضرة في وجوههم وسروراً في قلوبهم، وجزاهم بما صبروا على فعل الصالحات وترك المحرّمات جنة وحريراً.", "h": ["بيان نشأة الإنسان الأب والإنسان الابن، وما تدل عليه من إفضال الله وإكرامه لعباده.", "حاسّتا السمع والبصر، وجودهما معاً أو وجود إحداهما، ضروري للتكليف مع ضميمة العقل.", "بيان أن الإنسان أمامه طريقان فليسلك أيّهما شاء، وكل طريق ينتهي به إلى غاية: فطريق الرشد يوصل إلى الجنة دار النعيم، وطريق الغيّ يوصل إلى دار الشقاء الجحيم.", "وجوب الوفاء بالنذر، فمن نذر شيئاً لله وجب أن يفي بنذره، إلا أن ينذر معصية فلا يجوز له الوفاء بنذره فيها؛ فمن قال: لله عليّ أن أصوم يوم كذا، وجب عليه أن يصوم، ومن قال: لله عليّ ألا أصل رحمي، فلا يجوز له الوفاء، وليصل رحمه، ولا كفارة عليه.", "الترغيب في إطعام الطعام للمحتاجين إليه من فقير ويتيم وأسير."], "k": "«إنما نطعمكم لوجه الله لا نريد منكم جزاءً ولا شكوراً»… حين أعطي، هل أنتظر الشكر من الناس؟"}, {"lbl": "الآيات ١٣ – ٢٢", "q": "مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا ﴿١٣﴾ وَدَانِيَةً عَلَيۡهِمۡ ظِلَٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلٗا ﴿١٤﴾ وَيُطَافُ عَلَيۡهِم بِـَٔانِيَةٖ مِّن فِضَّةٖ وَأَكۡوَابٖ كَانَتۡ قَوَارِيرَا۠ ﴿١٥﴾ قَوَارِيرَاْ مِن فِضَّةٖ قَدَّرُوهَا تَقۡدِيرٗا ﴿١٦﴾ وَيُسۡقَوۡنَ فِيهَا كَأۡسٗا كَانَ مِزَاجُهَا زَنجَبِيلًا ﴿١٧﴾ عَيۡنٗا فِيهَا تُسَمَّىٰ سَلۡسَبِيلٗا ﴿١٨﴾ ۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا ﴿١٩﴾ وَإِذَا رَأَيۡتَ ثَمَّ رَأَيۡتَ نَعِيمٗا وَمُلۡكٗا كَبِيرًا ﴿٢٠﴾ عَٰلِيَهُمۡ ثِيَابُ سُندُسٍ خُضۡرٞ وَإِسۡتَبۡرَقٞۖ وَحُلُّوٓاْ أَسَاوِرَ مِن فِضَّةٖ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابٗا طَهُورًا ﴿٢١﴾ إِنَّ هَٰذَا كَانَ لَكُمۡ جَزَآءٗ وَكَانَ سَعۡيُكُم مَّشۡكُورًا ﴿٢٢﴾", "w": [["على الأرائك", "على الأسرّة في الحجال، واحد الأرائك أريكة."], ["ولا زمهريراً", "ولا برداً شديداً، أو ولا قمراً، إذ هي تُضاء من نفسها."], ["ودانية", "قريبة منهم ظلال أشجار الجنة."], ["وذُلّلت قطوفها تذليلاً", "بحيث ينالها المؤمن قائماً وقاعداً ومضطجعاً."], ["وأكواب", "أقداح بلا عرى."], ["قوارير من فضة", "يُرى باطنها من ظاهرها."], ["قدّروها تقديراً", "على قدر الشاربين بلا زيادة ولا نقص."], ["ويُسقون فيها كأساً", "خمراً."], ["كان مزاجها زنجبيلاً", "ما تُمزج وتُخلط به زنجبيلاً."], ["مخلّدون", "بصفة الولدان لا يشيبون."], ["لؤلؤاً منثوراً", "من سلكه أو من صدفه، لحسنهم وجمالهم وانتشارهم في الخدمة."], ["وإذا رأيت ثَمّ", "في الجنة رأيت نعيماً لا يوصف وملكاً واسعاً لا يُقدّر."], ["ثياب سندس", "حرير."], ["وإستبرق", "ما غلظ من الديباج."], ["وحُلّوا", "تحلّيهم الملائكة."], ["شراباً طهوراً", "فائقاً على النوعين السابقين، ولذا أسند سقيه إلى الله عز وجل."], ["إن هذا", "النعيم."], ["مشكوراً", "مرضيّاً مقبولاً."]], "m": "ما زال السياق في ذكر ما أعدّ الله للأبرار: متّكئين في الجنة على الأسرّة في الحجال، لا يرون فيها شمساً ولا زمهريراً، فلا شمس في الجنة ولا قمر لعدم الحاجة إليهما، ولا حرّ ولا برد كذلك، ودانية عليهم ظلال أشجارها، يجدون فيها لذّة التظليل وإن لم تكن هناك شمس، وذُلّلت ثمارها بحيث ينالها القائم والقاعد والمضطجع، فلا شوك ولا بعد، لأن الدار دار نعيم وراحة. ويطوف عليهم الخدم بآنية من فضة وأكواب لا عرى لها، قوارير من فضة يُرى باطنها من ظاهرها لصفائها، مادّتها فضة وصفاؤها صفاء الزجاج، قدّرها الخدم بحيث لا تزيد فتفيض ولا تنقص فلا يجمل منظرها. ويُسقون فيها خمراً مزاجها زنجبيلاً، من عين في الجنة تُسمّى سلسبيلاً. ويطوف عليهم غلمان مخلّدون لا يهرمون ولا يموتون، إذا رأيتهم في جمالهم وانتشارهم في الخدمة حسبتهم لؤلؤاً منثوراً. وإذا رأيت يا رسولنا هناك في الجنة رأيت نعيماً لا يوصف وملكاً كبيراً لا يُقادر قدره، فوقهم ثياب حرير خضر وإستبرق، وحلّاهم ربهم أساور من فضة ومن ذهب أيضاً، وسقاهم ربهم شراباً طهوراً، وهذا إكرام خاص أن الله هو الذي يسقيهم. ويقال لهم تكريماً: إن هذا النعيم كان لكم جزاءً على إيمانكم وتقواكم، وكان عملكم في الدنيا مرضيّاً مقبولاً.", "h": ["تقرير عقيدة البعث والجزاء بذكر صور من الجزاء الأخروي.", "حرمة استعمال أواني الذهب والفضة، لقول الرسول ﷺ: «هي لهم في الدنيا ولنا في الآخرة».", "حرمة الخمر، لحديث: «من شرب الخمر في الدنيا لا يشربها في الآخرة».", "مشروعية اتخاذ خدم صالحين يخدمون المرء، ويُحسن إليهم.", "حرمة لبس الحرير على الرجال وإباحته للنساء، وكالحرير الذهب أيضاً."], "k": "«وكان سعيكم مشكوراً»… أن يقول الله لي يوماً: شكرت سعيك؛ فهل سعيي اليوم يستحق ذلك؟"}, {"lbl": "الآيات ٢٣ – ٣١", "q": "إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا ﴿٢٣﴾ فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا ﴿٢٤﴾ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ﴿٢٥﴾ وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ﴿٢٦﴾ إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلۡعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمۡ يَوۡمٗا ثَقِيلٗا ﴿٢٧﴾ نَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا ﴿٢٨﴾ إِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ﴿٢٩﴾ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿٣٠﴾ يُدۡخِلُ مَن يَشَآءُ فِي رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا ﴿٣١﴾", "w": [["نزّلنا عليك القرآن تنزيلاً", "شيئاً فشيئاً، ولم ننزله جملة واحدة، لحكمة بالغة."], ["فاصبر لحكم ربك", "على حمل رسالتك وإبلاغها إلى الناس."], ["ولا تطع منهم آثماً أو كفوراً", "الآثم هنا عتبة بن ربيعة، والكفور الوليد بن المغيرة."], ["واذكر اسم ربك بكرة وأصيلاً", "صلّ الصبح والظهر والعصر."], ["ومن الليل فاسجد له", "صلّ صلاة المغرب والعشاء."], ["وسبّحه ليلاً طويلاً", "تهجّد بالليل نافلة لك."], ["يحبّون العاجلة", "الدنيا."], ["ويذرون وراءهم يوماً ثقيلاً", "يوم القيامة."], ["وشددنا أسرهم", "قوّينا أعضاءهم ومفاصلهم."], ["وإذا شئنا بدّلنا أمثالهم تبديلاً", "جعلنا أمثالهم في الخلقة بدلاً منهم بعد أن نهلكهم."], ["اتّخذ إلى ربه سبيلاً", "طريقاً إلى مرضاته وجواره بالإيمان والعمل الصالح وترك الشرك والمعاصي."], ["أعدّ لهم عذاباً أليماً", "في النار، والأليم ذو الألم الموجع."]], "m": "لقد عرض المشركون على رسول الله ﷺ أن يترك دعوته إلى التوحيد ويعبد ربه وحده ويتركهم فيما هم فيه، وله مقابل ذلك مال أو أزواج أو رئاسة، فأبى الله ذلك وأنزل: إنا نحن نزّلنا عليك القرآن تنزيلاً، فاصبر لحكم ربك على تحمّل رسالتك وتبليغها، ولا تطع من مشركي قريش آثماً كأبي جهل وعتبة، ولا كفوراً كالوليد، وواصل دعوتك واستعن بالصلاة والتسبيح والذكر والدعاء: بكرة وأصيلاً إشارة إلى صلاة الصبح والظهر والعصر، ومن الليل فاسجد له إشارة إلى المغرب والعشاء، وسبّحه ليلاً طويلاً صريح في أنه التهجّد، إذ الصلاة نعم العون للعبد، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. إن هؤلاء، يعني كفار قريش، يحبّون الدنيا، وسُمّيت العاجلة لأنها ذاهبة مسرعة، ويتركون وراءهم يوم القيامة الثقيل فلم يعملوا له. نحن خلقناهم من العدم، وقوّينا ظهورهم ومفاصلهم، وإذا شئنا أهلكناهم وجعلنا أمثالهم بدلاً عنهم، ولو شاء لكان، وهو في كل قرن يبدّل جيلاً بجيل. إن هذه السورة موعظة، فمن شاء اتّخذ إلى ربه طريقاً إلى رضاه أولاً ثم مجاورته في الملكوت الأعلى، وقيّد المشيئة بمشيئته، فوجب الافتقار إلى الله بدعائه والضراعة إليه: وما تشاؤون إلا أن يشاء الله، إن الله كان عليماً بخلقه حكيماً في تدبيره. يُدخل من يشاء في رحمته، من أهل الإيمان والتقوى، والظالمين المشركين أعدّ لهم عذاباً أليماً لكفرهم به وشركهم في عبادته.", "h": ["حرمة طاعة ذوي الإثم وأهل الكفر في حال الاختيار.", "على المؤمن أن يستعين بالصلاة والذكر والدعاء، فإنها نعم العون.", "استحباب نافلة الليل.", "مشيئة الله عز وجل قبل وفوق كل مشيئة.", "القرآن تذكرة للمؤمنين."], "k": "«وما تشاؤون إلا أن يشاء الله»… حتى رغبتي في الخير منه؛ فهل أسأله أن يشاء لي الهداية؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (431, 77, 1, 50, 'سورة المرسلات ١ – ٥٠', 'المرسلات: ويل يومئذ للمكذبين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 431) = $j$[{"lbl": "الآيات ١ – ١٥", "q": "وَٱلۡمُرۡسَلَٰتِ عُرۡفٗا ﴿١﴾ فَٱلۡعَٰصِفَٰتِ عَصۡفٗا ﴿٢﴾ وَٱلنَّـٰشِرَٰتِ نَشۡرٗا ﴿٣﴾ فَٱلۡفَٰرِقَٰتِ فَرۡقٗا ﴿٤﴾ فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا ﴿٥﴾ عُذۡرًا أَوۡ نُذۡرًا ﴿٦﴾ إِنَّمَا تُوعَدُونَ لَوَٰقِعٞ ﴿٧﴾ فَإِذَا ٱلنُّجُومُ طُمِسَتۡ ﴿٨﴾ وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ ﴿٩﴾ وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ ﴿١٠﴾ وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ ﴿١١﴾ لِأَيِّ يَوۡمٍ أُجِّلَتۡ ﴿١٢﴾ لِيَوۡمِ ٱلۡفَصۡلِ ﴿١٣﴾ وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ ﴿١٤﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٥﴾", "w": [["والمرسلات عرفاً", "الرياح الطيبة المتتابعة."], ["فالعاصفات عصفاً", "الرياح الشديدة الهبوب المضرّة لشدتها."], ["والناشرات نشراً", "الرياح تنشر السحاب وتفرّقه في السماء."], ["فالفارقات فرقاً", "آيات القرآن تفرّق بين الحق والباطل."], ["فالملقيات ذكراً", "الملائكة تلقي بالوحي على الأنبياء للتذكير به."], ["عذراً أو نذراً", "للإعذار والإنذار."], ["إنما توعدون لواقع", "إن ما توعدون أيها الناس لكائن لا محالة."], ["فإذا النجوم طُمست", "مُحي نورها وذهب."], ["وإذا السماء فُرجت", "انشقّت وتصدّعت."], ["وإذا الجبال نُسفت", "فإذا هي هباء منبثّ مفرّق."], ["وإذا الرسل أُقّتت", "جُمعت لوقت حُدّد لها لتحضر فيه."], ["ليوم الفصل", "اليوم الذي يفصل الله فيه بين الخلائق."]], "m": "هذا بداية قسم أقسم الله فيه بعدة أشياء من مخلوقاته، وله أن يقسم بما شاء، والحكمة من الإقسام أن تسكن النفوس للخبر وتطمئن إلى صدقه: بالمرسلات، وهي الرياح المتتابعة الطيبة، والعاصفات، وهي الشديدة الهبوب التي قد تقتلع الأشجار وتهدم المباني، والناشرات، وهي الرياح المعتدلة التي تنشر السحاب وتسوقه للإمطار، والفارقات، وهي آيات القرآن تفرّق بين الحق والباطل، والملقيات ذكراً، وهي الملائكة تلقي بالوحي على من اصطفى الله للإعذار والإنذار. والمقسم عليه: إن ما توعدون أيها الناس من خير أو شر لكائن لا محالة، فأصلحوا أعمالكم بعد تصحيح نياتكم، فإن الجزاء واقع لا يتخلّف. ومتى يقع؟ إذا النجوم ذهب نورها، وإذا السماء انشقّت، وإذا الجبال فُتّتت ونُسفت، وإذا الرسل حُدّد لها وقت تحضر فيه، وهو يوم الفصل، يوم يحضر الله الشهود من الملائكة والرسل ويفصل بين الناس، وما أدراك ما يوم الفصل؟ تفخيم لشأنه وإعلام بهوله. ويل يومئذ، أي العذاب الهائل، للمكذّبين بالله وبآياته ولقائه ورسوله.", "h": ["تقرير عقيدة البعث والجزاء.", "لله تعالى أن يقسم بما شاء من خلقه، وليس للعبد أن يقسم بغير خالقه عز وجل.", "علامات القيامة وظاهرة الانقلاب الكوني العام، وهي انطماس ضوء النجوم وانفراج السماء ونسف الجبال.", "الوعيد الشديد بالويل، الذي هو وادٍ في جهنم تستغيث جهنم من حرّه، للمكذّبين بما يجب التصديق به من أركان الإيمان الستة، والوعد والوعيد الإلهيين."], "k": "«إنما توعدون لواقع»… الوعد واقع لا محالة؛ فهل أعيش كمن يصدّق أنه واقع؟"}, {"lbl": "الآيات ١٦ – ٢٨", "q": "أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِينَ ﴿١٦﴾ ثُمَّ نُتۡبِعُهُمُ ٱلۡأٓخِرِينَ ﴿١٧﴾ كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ﴿١٨﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٩﴾ أَلَمۡ نَخۡلُقكُّم مِّن مَّآءٖ مَّهِينٖ ﴿٢٠﴾ فَجَعَلۡنَٰهُ فِي قَرَارٖ مَّكِينٍ ﴿٢١﴾ إِلَىٰ قَدَرٖ مَّعۡلُومٖ ﴿٢٢﴾ فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَٰدِرُونَ ﴿٢٣﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٢٤﴾ أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ﴿٢٥﴾ أَحۡيَآءٗ وَأَمۡوَٰتٗا ﴿٢٦﴾ وَجَعَلۡنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتٖ وَأَسۡقَيۡنَٰكُم مَّآءٗ فُرَاتٗا ﴿٢٧﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٢٨﴾", "w": [["ألم نهلك الأولين", "كقوم نوح وعاد وثمود ومن بعدهم إلى البعثة النبوية."], ["ثم نتبعهم الآخرين", "إن أصرّوا على التكذيب ككفار مكة."], ["كذلك نفعل بالمجرمين", "مثل ذلك الهلاك نهلك المجرمين."], ["ويل يومئذ للمكذبين", "إذا جاء وقت الهلاك ويل فيه للمكذّبين."], ["من ماء مهين", "المنيّ، والمهين الضعيف."], ["في قرار مكين", "حريز، وهو الرحم."], ["إلى قدر معلوم", "إلى وقت الولادة."], ["فقدرنا", "قدّرنا خلقه."], ["فنعم القادرون", "نحن على الخلق والتقدير."], ["كِفاتاً", "تكفت الناس، أي تضمّهم أحياءً فوق ظهرها وأمواتاً في بطنها."], ["رواسي شامخات", "جبالاً عاليات."], ["ماءً فراتاً", "عذباً."]], "m": "لما أقسم تعالى على وقوع ما أوعد به المكذّبين وذكر وقت مجيئه وعلاماته، دلّل هنا على قدرته على إهلاكهم بما سبق له أن فعله بالمكذّبين، فقال في استفهام تقريري: ألم نهلك الأولين من الأمم السابقة كعاد وثمود وقوم إبراهيم وقوم لوط؟ ثم نتبعهم الآخرين، فقد أهلك أكابر مجرمي قريش في بدر، كذلك نفعل بالمجرمين، وهو وعيد صريح، ويل يومئذ للمكذّبين. ثم استدلّ على قدرته وعلمه اللذين لا يتم البعث والجزاء إلا عليهما: ألم نخلقكم من ماء ضعيف هو المنيّ، فجعلناه في قرار حصين هو الرحم، إلى زمن الولادة، فقدّرنا خلق الجنين على أحسن صورة وأدق تركيب، المسافات بين الأعضاء مقدّرة تقديراً عجيباً لا تزيد ولا تنقص، فنعم القادرون على الخلق والتقدير معاً؟ والجواب: بلى، فلمَ إذاً تكفرون وتكذّبون؟ ثم استدلال آخر: ألم نجعل الأرض ضامّة للناس، الأحياء على ظهرها يسكنون ويأكلون، والأموات في بطنها لا تضيق بهم أبداً، وجعلنا فيها جبالاً عاليات، وأسقيناكم ماءً عذباً من السماء نافعاً في الأرض وجارياً في الأودية والأنهار؟ والجواب: بلى، إذاً فما لكم أيها المشركون تكذّبون؟ ويل يومئذ للمكذّبين.", "h": ["تقرير عقيدة البعث والجزاء.", "الاستدلال على البعث والجزاء بالقدرة والعلم، إذ هما أساس البعث والجزاء.", "بيان إنعام الله تعالى على عباده في خلقهم ورزقهم وتدبير حياتهم أحياءً وأمواتاً.", "بيان أن الناس أكثرهم لا يشكرون.", "الوعيد الشديد للمكذّبين الكافرين."], "k": "«ألم نجعل الأرض كفاتاً أحياءً وأمواتاً»… أمشي على ظهرها اليوم وسأسكن بطنها غداً؛ فماذا أعددت؟"}, {"lbl": "الآيات ٢٩ – ٤٠", "q": "ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢٩﴾ ٱنطَلِقُوٓاْ إِلَىٰ ظِلّٖ ذِي ثَلَٰثِ شُعَبٖ ﴿٣٠﴾ لَّا ظَلِيلٖ وَلَا يُغۡنِي مِنَ ٱللَّهَبِ ﴿٣١﴾ إِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ ﴿٣٢﴾ كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ ﴿٣٣﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٣٤﴾ هَٰذَا يَوۡمُ لَا يَنطِقُونَ ﴿٣٥﴾ وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ ﴿٣٦﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٣٧﴾ هَٰذَا يَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَٰكُمۡ وَٱلۡأَوَّلِينَ ﴿٣٨﴾ فَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ ﴿٣٩﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٠﴾", "w": [["انطلقوا إلى ما كنتم به تكذّبون", "من العذاب."], ["إلى ظل ذي ثلاث شُعب", "دخان جهنم إذا ارتفع انقسم إلى ثلاث شعب لعظمته."], ["لا ظليل", "ليس ظلّاً ساتراً يكنّ ويستر."], ["ولا يغني من اللهب", "لا يردّ شيئاً من الحر."], ["إنها", "النار."], ["ترمي بشرر كالقصر", "الشررة الواحدة كالقصر في عظمته وارتفاعه."], ["كأنه جمالة صفر", "الشررة كالجمل الأصفر في هيئتها ولونها، والجمل الأصفر الأسود الذي يميل إلى الصفرة."], ["هذا يوم لا ينطقون", "لا ينطقون فيه بشيء."], ["ولا يؤذن لهم فيعتذرون", "لا يؤذن لهم في الاعتذار."], ["جمعناكم والأولين", "من المكذّبين قبلكم."], ["فإن كان لكم كيد فكيدون", "حيلة في دفع العذاب فاحتالوا لدفعه عنكم."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء التي عليها مدار الحياة كلها: يقال للمكذّبين يوم القيامة تقريعاً وتبكيتاً: انطلقوا إلى ما كنتم به تكذّبون من عذاب الآخرة، انطلقوا إلى ظل ذي ثلاث شعب، وهو دخان النار إذا ارتفع تشعّب لعظمته، ليس ظلّاً حقيقياً كظل الشجرة والجدار فيكنّ ويستر، ولا يدفع شيئاً من الحر. إنها ترمي بشرر، الشررة الواحدة كالقصر في كبره وارتفاعه، كأنها جمل أصفر، أسود مائل إلى الصفرة. ويل يومئذ للمكذّبين. هذا يوم لا ينطقون فيه بشيء، ولا يؤذن لهم في الاعتذار؛ ولطول يوم القيامة وتجدّد الأحداث فيه يخبر القرآن مرة باعتذارهم وكلامهم في موطن، وينفيه في آخر، إذ هو كذلك في الواقع: في مواطن يتكلّمون بل ويحلفون كاذبين، وفي مواطن يغلب عليهم الخوف فلا يتكلّمون. ويقال لهم: هذا يوم الفصل الذي كنتم به تكذّبون، جمعناكم فيه أيها المكذّبون من هذه الأمة والمكذّبين الأولين، فإن كان لكم حيلة في خلاصكم فاحتالوا، يقال لهم تبكيتاً وخزياً، وهو عذاب روحي أشد ألماً من العذاب الجسماني.", "h": ["التهكّم والسخرية والتبكيت من أشد أنواع العذاب الروحي يوم القيامة.", "عرصات القيامة واسعة، والمقام فيها طويل، والبلاء فيها شديد.", "تقرير عقيدة البعث والجزاء بذكر بعض ما يتم فيه.", "التكذيب هو رأس الكفر، وبموجبه يكون العذاب."], "k": "«هذا يوم لا ينطقون ولا يؤذن لهم فيعتذرون»… الاعتذار ممكن الآن؛ فمن أعتذر إليه اليوم قبل أن يُغلق الباب؟"}, {"lbl": "الآيات ٤١ – ٥٠", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي ظِلَٰلٖ وَعُيُونٖ ﴿٤١﴾ وَفَوَٰكِهَ مِمَّا يَشۡتَهُونَ ﴿٤٢﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٤٣﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٤٤﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٥﴾ كُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ ﴿٤٦﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٧﴾ وَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ﴿٤٨﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٩﴾ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ ﴿٥٠﴾", "w": [["إن المتقين", "الذين اتقوا ربهم فآمنوا به وأطاعوه بفعل ما يحب وترك ما يكره."], ["في ظلال", "في ظلال الأشجار الوارفة."], ["وعيون", "من ماء ولبن وخمر وعسل."], ["مما يشتهون", "لا مما يجدون كما هي الحال في الدنيا."], ["إنا كذلك نجزي المحسنين", "كما جزينا المتقين نجزي المحسنين."], ["كلوا وتمتّعوا قليلاً", "في هذه الحياة الدنيا."], ["وإذا قيل لهم اركعوا", "صلّوا، لا يصلّون."], ["فبأي حديث بعده يؤمنون", "بعد القرآن، إذ هو المعجز بألفاظه ومعانيه، فمن لم يؤمن به ما آمن بغيره."]], "m": "من باب الترغيب والترهيب، ذكر تعالى ما للمتقين من نعيم مقيم بعد ذكر ما للمكذّبين من عذاب: إن المتقين الذين اجتنبوا الشرك والمعاصي في ظلال أشجار الجنة، وعيونها من ماء ولبن وخمر وعسل، وفواكه مما يشتهون، على خلاف الدنيا إذ الناس يأكلون مما يجدون، أما دار النعيم فالمرء ما اشتهى شيئاً إلا وجده. ويقال لهم تطييباً لخواطرهم: كلوا واشربوا هنيئاً بما كنتم تعملون من الصالحات وتتركون من السيئات، إنا كذلك نجزي المحسنين. ويل يومئذ للمكذّبين بهذا الوعد. ثم قال لمشركي قريش مهدّداً: كلوا وتمتّعوا قليلاً إنكم مجرمون، وقد أُهلكوا في بدر. وإذا قيل لهم: صلّوا، لا يصلّون ولا يخشعون ولا يتواضعون فيقبلون الحق، ويل يومئذ للمكذّبين التاركين للصلاة. فبأي كتاب يؤمن هؤلاء إذا لم يؤمنوا بالقرآن، بما فيه من الخير والهدى، وهو المعجز بألفاظه ومعانيه، فمن لم يؤمن به لا يُرجى له أن يؤمن بغيره بحال.", "h": ["تقرير عقيدة البعث والجزاء بذكر ما أعدّ الله تعالى لأوليائه المؤمنين المتقين المحسنين.", "بيان نعيم أهل التقوى والإحسان، وفضل التقوى والإحسان.", "صدق القرآن في أخباره، إذ وعيد الله لأكابر مجرمي مكة نُفّذ بعد أقل من خمس سنوات.", "من دخل مسجداً وأهله يصلّون فليدخل معهم في صلاتهم وإن كان قد صلّى، حتى لا يكون غيره راكعاً لله وهو غير راكع، وقد جاء في الصحيح هذا المعنى."], "k": "«وإذا قيل لهم اركعوا لا يركعون»… حين أسمع النداء، هل أركع أم أؤجّل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 431;
insert into public.tdb_cards(topic, i, body) select 431, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٥", "q": "وَٱلۡمُرۡسَلَٰتِ عُرۡفٗا ﴿١﴾ فَٱلۡعَٰصِفَٰتِ عَصۡفٗا ﴿٢﴾ وَٱلنَّـٰشِرَٰتِ نَشۡرٗا ﴿٣﴾ فَٱلۡفَٰرِقَٰتِ فَرۡقٗا ﴿٤﴾ فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا ﴿٥﴾ عُذۡرًا أَوۡ نُذۡرًا ﴿٦﴾ إِنَّمَا تُوعَدُونَ لَوَٰقِعٞ ﴿٧﴾ فَإِذَا ٱلنُّجُومُ طُمِسَتۡ ﴿٨﴾ وَإِذَا ٱلسَّمَآءُ فُرِجَتۡ ﴿٩﴾ وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ ﴿١٠﴾ وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ ﴿١١﴾ لِأَيِّ يَوۡمٍ أُجِّلَتۡ ﴿١٢﴾ لِيَوۡمِ ٱلۡفَصۡلِ ﴿١٣﴾ وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ ﴿١٤﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٥﴾", "w": [["والمرسلات عرفاً", "الرياح الطيبة المتتابعة."], ["فالعاصفات عصفاً", "الرياح الشديدة الهبوب المضرّة لشدتها."], ["والناشرات نشراً", "الرياح تنشر السحاب وتفرّقه في السماء."], ["فالفارقات فرقاً", "آيات القرآن تفرّق بين الحق والباطل."], ["فالملقيات ذكراً", "الملائكة تلقي بالوحي على الأنبياء للتذكير به."], ["عذراً أو نذراً", "للإعذار والإنذار."], ["إنما توعدون لواقع", "إن ما توعدون أيها الناس لكائن لا محالة."], ["فإذا النجوم طُمست", "مُحي نورها وذهب."], ["وإذا السماء فُرجت", "انشقّت وتصدّعت."], ["وإذا الجبال نُسفت", "فإذا هي هباء منبثّ مفرّق."], ["وإذا الرسل أُقّتت", "جُمعت لوقت حُدّد لها لتحضر فيه."], ["ليوم الفصل", "اليوم الذي يفصل الله فيه بين الخلائق."]], "m": "هذا بداية قسم أقسم الله فيه بعدة أشياء من مخلوقاته، وله أن يقسم بما شاء، والحكمة من الإقسام أن تسكن النفوس للخبر وتطمئن إلى صدقه: بالمرسلات، وهي الرياح المتتابعة الطيبة، والعاصفات، وهي الشديدة الهبوب التي قد تقتلع الأشجار وتهدم المباني، والناشرات، وهي الرياح المعتدلة التي تنشر السحاب وتسوقه للإمطار، والفارقات، وهي آيات القرآن تفرّق بين الحق والباطل، والملقيات ذكراً، وهي الملائكة تلقي بالوحي على من اصطفى الله للإعذار والإنذار. والمقسم عليه: إن ما توعدون أيها الناس من خير أو شر لكائن لا محالة، فأصلحوا أعمالكم بعد تصحيح نياتكم، فإن الجزاء واقع لا يتخلّف. ومتى يقع؟ إذا النجوم ذهب نورها، وإذا السماء انشقّت، وإذا الجبال فُتّتت ونُسفت، وإذا الرسل حُدّد لها وقت تحضر فيه، وهو يوم الفصل، يوم يحضر الله الشهود من الملائكة والرسل ويفصل بين الناس، وما أدراك ما يوم الفصل؟ تفخيم لشأنه وإعلام بهوله. ويل يومئذ، أي العذاب الهائل، للمكذّبين بالله وبآياته ولقائه ورسوله.", "h": ["تقرير عقيدة البعث والجزاء.", "لله تعالى أن يقسم بما شاء من خلقه، وليس للعبد أن يقسم بغير خالقه عز وجل.", "علامات القيامة وظاهرة الانقلاب الكوني العام، وهي انطماس ضوء النجوم وانفراج السماء ونسف الجبال.", "الوعيد الشديد بالويل، الذي هو وادٍ في جهنم تستغيث جهنم من حرّه، للمكذّبين بما يجب التصديق به من أركان الإيمان الستة، والوعد والوعيد الإلهيين."], "k": "«إنما توعدون لواقع»… الوعد واقع لا محالة؛ فهل أعيش كمن يصدّق أنه واقع؟"}, {"lbl": "الآيات ١٦ – ٢٨", "q": "أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِينَ ﴿١٦﴾ ثُمَّ نُتۡبِعُهُمُ ٱلۡأٓخِرِينَ ﴿١٧﴾ كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ ﴿١٨﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿١٩﴾ أَلَمۡ نَخۡلُقكُّم مِّن مَّآءٖ مَّهِينٖ ﴿٢٠﴾ فَجَعَلۡنَٰهُ فِي قَرَارٖ مَّكِينٍ ﴿٢١﴾ إِلَىٰ قَدَرٖ مَّعۡلُومٖ ﴿٢٢﴾ فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَٰدِرُونَ ﴿٢٣﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٢٤﴾ أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ﴿٢٥﴾ أَحۡيَآءٗ وَأَمۡوَٰتٗا ﴿٢٦﴾ وَجَعَلۡنَا فِيهَا رَوَٰسِيَ شَٰمِخَٰتٖ وَأَسۡقَيۡنَٰكُم مَّآءٗ فُرَاتٗا ﴿٢٧﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٢٨﴾", "w": [["ألم نهلك الأولين", "كقوم نوح وعاد وثمود ومن بعدهم إلى البعثة النبوية."], ["ثم نتبعهم الآخرين", "إن أصرّوا على التكذيب ككفار مكة."], ["كذلك نفعل بالمجرمين", "مثل ذلك الهلاك نهلك المجرمين."], ["ويل يومئذ للمكذبين", "إذا جاء وقت الهلاك ويل فيه للمكذّبين."], ["من ماء مهين", "المنيّ، والمهين الضعيف."], ["في قرار مكين", "حريز، وهو الرحم."], ["إلى قدر معلوم", "إلى وقت الولادة."], ["فقدرنا", "قدّرنا خلقه."], ["فنعم القادرون", "نحن على الخلق والتقدير."], ["كِفاتاً", "تكفت الناس، أي تضمّهم أحياءً فوق ظهرها وأمواتاً في بطنها."], ["رواسي شامخات", "جبالاً عاليات."], ["ماءً فراتاً", "عذباً."]], "m": "لما أقسم تعالى على وقوع ما أوعد به المكذّبين وذكر وقت مجيئه وعلاماته، دلّل هنا على قدرته على إهلاكهم بما سبق له أن فعله بالمكذّبين، فقال في استفهام تقريري: ألم نهلك الأولين من الأمم السابقة كعاد وثمود وقوم إبراهيم وقوم لوط؟ ثم نتبعهم الآخرين، فقد أهلك أكابر مجرمي قريش في بدر، كذلك نفعل بالمجرمين، وهو وعيد صريح، ويل يومئذ للمكذّبين. ثم استدلّ على قدرته وعلمه اللذين لا يتم البعث والجزاء إلا عليهما: ألم نخلقكم من ماء ضعيف هو المنيّ، فجعلناه في قرار حصين هو الرحم، إلى زمن الولادة، فقدّرنا خلق الجنين على أحسن صورة وأدق تركيب، المسافات بين الأعضاء مقدّرة تقديراً عجيباً لا تزيد ولا تنقص، فنعم القادرون على الخلق والتقدير معاً؟ والجواب: بلى، فلمَ إذاً تكفرون وتكذّبون؟ ثم استدلال آخر: ألم نجعل الأرض ضامّة للناس، الأحياء على ظهرها يسكنون ويأكلون، والأموات في بطنها لا تضيق بهم أبداً، وجعلنا فيها جبالاً عاليات، وأسقيناكم ماءً عذباً من السماء نافعاً في الأرض وجارياً في الأودية والأنهار؟ والجواب: بلى، إذاً فما لكم أيها المشركون تكذّبون؟ ويل يومئذ للمكذّبين.", "h": ["تقرير عقيدة البعث والجزاء.", "الاستدلال على البعث والجزاء بالقدرة والعلم، إذ هما أساس البعث والجزاء.", "بيان إنعام الله تعالى على عباده في خلقهم ورزقهم وتدبير حياتهم أحياءً وأمواتاً.", "بيان أن الناس أكثرهم لا يشكرون.", "الوعيد الشديد للمكذّبين الكافرين."], "k": "«ألم نجعل الأرض كفاتاً أحياءً وأمواتاً»… أمشي على ظهرها اليوم وسأسكن بطنها غداً؛ فماذا أعددت؟"}, {"lbl": "الآيات ٢٩ – ٤٠", "q": "ٱنطَلِقُوٓاْ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ ﴿٢٩﴾ ٱنطَلِقُوٓاْ إِلَىٰ ظِلّٖ ذِي ثَلَٰثِ شُعَبٖ ﴿٣٠﴾ لَّا ظَلِيلٖ وَلَا يُغۡنِي مِنَ ٱللَّهَبِ ﴿٣١﴾ إِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ ﴿٣٢﴾ كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ ﴿٣٣﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٣٤﴾ هَٰذَا يَوۡمُ لَا يَنطِقُونَ ﴿٣٥﴾ وَلَا يُؤۡذَنُ لَهُمۡ فَيَعۡتَذِرُونَ ﴿٣٦﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٣٧﴾ هَٰذَا يَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَٰكُمۡ وَٱلۡأَوَّلِينَ ﴿٣٨﴾ فَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ ﴿٣٩﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٠﴾", "w": [["انطلقوا إلى ما كنتم به تكذّبون", "من العذاب."], ["إلى ظل ذي ثلاث شُعب", "دخان جهنم إذا ارتفع انقسم إلى ثلاث شعب لعظمته."], ["لا ظليل", "ليس ظلّاً ساتراً يكنّ ويستر."], ["ولا يغني من اللهب", "لا يردّ شيئاً من الحر."], ["إنها", "النار."], ["ترمي بشرر كالقصر", "الشررة الواحدة كالقصر في عظمته وارتفاعه."], ["كأنه جمالة صفر", "الشررة كالجمل الأصفر في هيئتها ولونها، والجمل الأصفر الأسود الذي يميل إلى الصفرة."], ["هذا يوم لا ينطقون", "لا ينطقون فيه بشيء."], ["ولا يؤذن لهم فيعتذرون", "لا يؤذن لهم في الاعتذار."], ["جمعناكم والأولين", "من المكذّبين قبلكم."], ["فإن كان لكم كيد فكيدون", "حيلة في دفع العذاب فاحتالوا لدفعه عنكم."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء التي عليها مدار الحياة كلها: يقال للمكذّبين يوم القيامة تقريعاً وتبكيتاً: انطلقوا إلى ما كنتم به تكذّبون من عذاب الآخرة، انطلقوا إلى ظل ذي ثلاث شعب، وهو دخان النار إذا ارتفع تشعّب لعظمته، ليس ظلّاً حقيقياً كظل الشجرة والجدار فيكنّ ويستر، ولا يدفع شيئاً من الحر. إنها ترمي بشرر، الشررة الواحدة كالقصر في كبره وارتفاعه، كأنها جمل أصفر، أسود مائل إلى الصفرة. ويل يومئذ للمكذّبين. هذا يوم لا ينطقون فيه بشيء، ولا يؤذن لهم في الاعتذار؛ ولطول يوم القيامة وتجدّد الأحداث فيه يخبر القرآن مرة باعتذارهم وكلامهم في موطن، وينفيه في آخر، إذ هو كذلك في الواقع: في مواطن يتكلّمون بل ويحلفون كاذبين، وفي مواطن يغلب عليهم الخوف فلا يتكلّمون. ويقال لهم: هذا يوم الفصل الذي كنتم به تكذّبون، جمعناكم فيه أيها المكذّبون من هذه الأمة والمكذّبين الأولين، فإن كان لكم حيلة في خلاصكم فاحتالوا، يقال لهم تبكيتاً وخزياً، وهو عذاب روحي أشد ألماً من العذاب الجسماني.", "h": ["التهكّم والسخرية والتبكيت من أشد أنواع العذاب الروحي يوم القيامة.", "عرصات القيامة واسعة، والمقام فيها طويل، والبلاء فيها شديد.", "تقرير عقيدة البعث والجزاء بذكر بعض ما يتم فيه.", "التكذيب هو رأس الكفر، وبموجبه يكون العذاب."], "k": "«هذا يوم لا ينطقون ولا يؤذن لهم فيعتذرون»… الاعتذار ممكن الآن؛ فمن أعتذر إليه اليوم قبل أن يُغلق الباب؟"}, {"lbl": "الآيات ٤١ – ٥٠", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي ظِلَٰلٖ وَعُيُونٖ ﴿٤١﴾ وَفَوَٰكِهَ مِمَّا يَشۡتَهُونَ ﴿٤٢﴾ كُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٤٣﴾ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ ﴿٤٤﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٥﴾ كُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ ﴿٤٦﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٧﴾ وَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ﴿٤٨﴾ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ﴿٤٩﴾ فَبِأَيِّ حَدِيثِۭ بَعۡدَهُۥ يُؤۡمِنُونَ ﴿٥٠﴾", "w": [["إن المتقين", "الذين اتقوا ربهم فآمنوا به وأطاعوه بفعل ما يحب وترك ما يكره."], ["في ظلال", "في ظلال الأشجار الوارفة."], ["وعيون", "من ماء ولبن وخمر وعسل."], ["مما يشتهون", "لا مما يجدون كما هي الحال في الدنيا."], ["إنا كذلك نجزي المحسنين", "كما جزينا المتقين نجزي المحسنين."], ["كلوا وتمتّعوا قليلاً", "في هذه الحياة الدنيا."], ["وإذا قيل لهم اركعوا", "صلّوا، لا يصلّون."], ["فبأي حديث بعده يؤمنون", "بعد القرآن، إذ هو المعجز بألفاظه ومعانيه، فمن لم يؤمن به ما آمن بغيره."]], "m": "من باب الترغيب والترهيب، ذكر تعالى ما للمتقين من نعيم مقيم بعد ذكر ما للمكذّبين من عذاب: إن المتقين الذين اجتنبوا الشرك والمعاصي في ظلال أشجار الجنة، وعيونها من ماء ولبن وخمر وعسل، وفواكه مما يشتهون، على خلاف الدنيا إذ الناس يأكلون مما يجدون، أما دار النعيم فالمرء ما اشتهى شيئاً إلا وجده. ويقال لهم تطييباً لخواطرهم: كلوا واشربوا هنيئاً بما كنتم تعملون من الصالحات وتتركون من السيئات، إنا كذلك نجزي المحسنين. ويل يومئذ للمكذّبين بهذا الوعد. ثم قال لمشركي قريش مهدّداً: كلوا وتمتّعوا قليلاً إنكم مجرمون، وقد أُهلكوا في بدر. وإذا قيل لهم: صلّوا، لا يصلّون ولا يخشعون ولا يتواضعون فيقبلون الحق، ويل يومئذ للمكذّبين التاركين للصلاة. فبأي كتاب يؤمن هؤلاء إذا لم يؤمنوا بالقرآن، بما فيه من الخير والهدى، وهو المعجز بألفاظه ومعانيه، فمن لم يؤمن به لا يُرجى له أن يؤمن بغيره بحال.", "h": ["تقرير عقيدة البعث والجزاء بذكر ما أعدّ الله تعالى لأوليائه المؤمنين المتقين المحسنين.", "بيان نعيم أهل التقوى والإحسان، وفضل التقوى والإحسان.", "صدق القرآن في أخباره، إذ وعيد الله لأكابر مجرمي مكة نُفّذ بعد أقل من خمس سنوات.", "من دخل مسجداً وأهله يصلّون فليدخل معهم في صلاتهم وإن كان قد صلّى، حتى لا يكون غيره راكعاً لله وهو غير راكع، وقد جاء في الصحيح هذا المعنى."], "k": "«وإذا قيل لهم اركعوا لا يركعون»… حين أسمع النداء، هل أركع أم أؤجّل؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;